INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_air-fried-vegetable-spring-rolls_v1', 'rcp_air-fried-vegetable-spring-rolls', 'air-fried-vegetable-spring-rolls', 1, 'Air-Fried Vegetable Spring Rolls', 'Cabbage, shiitake, and rice-vermicelli rolls air-fried until the wrappers are crisp, with a soy and lime dip. No shrimp and no fish sauce.', 4, 25, 16, 41, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Air fryer at 375 F. A skillet over medium-high only to soften the filling.', 'Wrappers crisp and blistered, filling hot, vermicelli tender. Dip salty, sour, and a little sweet.', '["air-fry"]', '[]', 'null', '[{"component_id":"filling","name":"cabbage and mushroom filling","made_in_recipe":true,"store_bought":false,"ingredients":["cabbage","carrot","shiitake","rice vermicelli","soy sauce"]},{"component_id":"dip","name":"soy lime dip","made_in_recipe":true,"store_bought":false,"ingredients":["soy sauce","lime","garlic","sugar","red chile"]},{"component_id":"wrappers","name":"wheat spring roll wrappers","made_in_recipe":false,"store_bought":true,"ingredients":["spring roll wrappers"],"contract":"Wheat spring roll wrappers, not rice paper. No egg wash required by the package."}]', 'published', 'draft', 'global', NULL, 'c8808686884b45fc06526723952b1d8868ba8e783ecf7066154529d09ee1f668', 'flavorweave-catalog-package', 'catalog/air-fried-vegetable-spring-rolls/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_air-fryer-honey-mustard-pork_v1', 'rcp_air-fryer-honey-mustard-pork', 'air-fryer-honey-mustard-pork', 1, 'Air-Fryer Honey-Mustard Pork Tenderloin', 'Pork tenderloin brushed with a honey-Dijon glaze and roasted in the air fryer until browned outside and juicy at 145 F.', 4, 10, 25, 35, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Air fryer 400 F. Preheat about 3 minutes (inside cook). First stretch 10 minutes, glazed finish 6 to 8 minutes, rest 5 minutes.', 'Center 145 F, juices not raw-pink watery. Glaze sticky and patch-browned, not burnt sugar. Rest 5 minutes before slicing. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"honey-mustard-glaze","name":"honey-mustard glaze","made_in_recipe":true,"store_bought":false,"ingredients":["Dijon mustard","honey","apple cider vinegar","garlic","olive oil","kosher salt","black pepper","smoked paprika"]}]', 'published', 'draft', 'global', NULL, '4d9a3f7700a60013d399986e817a4c929cfbb818076b2d69e8870cc866995f43', 'flavorweave-catalog-package', 'catalog/air-fryer-honey-mustard-pork/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_aloo-paratha-kachumber-chutney_v1', 'rcp_aloo-paratha-kachumber-chutney', 'aloo-paratha-kachumber-chutney', 1, 'Aloo Paratha with Cilantro-Mint Chutney and Kachumber Salad', 'Whole-wheat flatbreads stuffed with a spiced potato filling of green chile, ginger, cumin, amchur, and cilantro, rolled thin and cooked on a hot cast-iron pan with oil until blistered and crisp-flecked. Served with a bright cilantro-mint chutney and a cucumber, tomato, and onion kachumber.', 4, 18, 47, 65, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Steady boil for the potatoes. Medium-high dry cast-iron pan or tawa for the parathas, brushed with oil once flipped.', 'Potatoes fork-tender and dry before mashing. Parathas puffed in places, golden-brown spotted on both sides, no raw dough at the edges.', '["boil","griddle"]', '[]', 'null', '[{"component_id":"dough","name":"whole-wheat dough","made_in_recipe":true,"store_bought":false,"ingredients":["whole-wheat flour","water","salt","oil"]},{"component_id":"filling","name":"spiced potato filling","made_in_recipe":true,"store_bought":false,"ingredients":["potatoes","green chiles","ginger","cilantro","cumin seeds","amchur","garam masala","salt","water"]},{"component_id":"chutney","name":"cilantro-mint chutney","made_in_recipe":true,"store_bought":false,"ingredients":["cilantro","mint","green chile","lemon","water","salt"]},{"component_id":"kachumber","name":"kachumber salad","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber","tomato","red onion","lemon","salt"]}]', 'published', 'draft', 'global', NULL, '6407273e48d459fb4f11d5caac06b8e50b4272b36827f9caadf284c687566670', 'flavorweave-catalog-package', 'catalog/aloo-paratha-kachumber-chutney/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_amritsari-fish-mint-chutney_v1', 'rcp_amritsari-fish-mint-chutney', 'amritsari-fish-mint-chutney', 1, 'Amritsari Fish with Cilantro-Mint Chutney, Kachumber, and Basmati Rice', 'Haddock pieces marinated in ginger, garlic, lemon, chili powder, turmeric, and ajwain, coated in a chickpea flour and rice flour batter and shallow-fried crisp, served with a bright cilantro-mint chutney, a red onion, cucumber, and tomato kachumber, and basmati rice.', 4, 34, 20, 54, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', '12-inch heavy skillet with oil about 1/4 inch deep over medium-high (350 F); 2-quart saucepan for the rice.', 'Batter crisp and deep golden; fish opaque and flaking, 145 F at the thickest piece.', '["shallow-fry","steam"]', '[]', 'null', '[{"component_id":"fish","name":"Amritsari fish","made_in_recipe":true,"store_bought":false,"ingredients":["haddock","ginger","garlic","lemon juice","chili powder","turmeric","ajwain","salt","chickpea flour","rice flour","water","neutral oil"]},{"component_id":"chutney","name":"cilantro-mint chutney","made_in_recipe":true,"store_bought":false,"ingredients":["cilantro","mint","green chile","lemon juice","salt","water"]},{"component_id":"kachumber","name":"kachumber","made_in_recipe":true,"store_bought":false,"ingredients":["red onion","cucumber","tomato","lemon juice","salt"]},{"component_id":"rice","name":"basmati rice","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '63df0875018dd790f2acbba7256852c917f4b843ebd7506a11753c3a86952996', 'flavorweave-catalog-package', 'catalog/amritsari-fish-mint-chutney/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_argentine-beef-empanadas_v1', 'rcp_argentine-beef-empanadas', 'argentine-beef-empanadas', 1, 'Argentine Baked Beef Empanadas with Olives and Boiled Egg', 'Pastry discs filled with ground beef cooked with onion, red bell pepper, cumin, sweet paprika, oregano, and chile flakes, folded with chopped boiled egg, green olives, and scallions, crimped, brushed with beaten egg, and baked golden.', 4, 34, 55, 89, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Oven 400 F with racks in the upper and lower thirds; 12-inch skillet over medium-high; 2-quart saucepan for the eggs.', 'Pastry deep golden and crisp at the crimp; filling steaming hot (165 F).', '["boil","saute","bake"]', '[]', 'null', '[{"component_id":"eggs","name":"boiled eggs","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","water"]},{"component_id":"filling","name":"beef filling","made_in_recipe":true,"store_bought":false,"ingredients":["ground beef","neutral oil","yellow onion","red bell pepper","cumin","sweet paprika","dried oregano","red chile flakes","salt","eggs","green olives","scallions"]},{"component_id":"pastry","name":"empanadas","made_in_recipe":true,"store_bought":false,"ingredients":["empanada discs","eggs"]}]', 'published', 'draft', 'global', NULL, 'defe8c2b4b750ef7190d0920be60f648877e347956c185257e59020938f6a112', 'flavorweave-catalog-package', 'catalog/argentine-beef-empanadas/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_argentine-chimichurri-steak-potatoes_v1', 'rcp_argentine-chimichurri-steak-potatoes', 'argentine-chimichurri-steak-potatoes', 1, 'Argentine Grilled Strip Steak with Chimichurri, Grilled Potatoes, and Ensalada Criolla', 'Thick strip steaks seasoned simply with coarse salt and grilled over high heat, sliced and spooned with sharp chimichurri of parsley, oregano, garlic, red wine vinegar, chile, and olive oil. Served with par-boiled grilled potatoes and a tomato and onion salad.', 4, 15, 55, 70, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Grill preheated on high for 10 minutes, about 500 F at the grate. A 4-quart pot at a boil for the potatoes.', 'Steaks 130 F for medium-rare (USDA safe minimum is 145 F with a 3-minute rest). Potatoes tender inside with dark grill marks.', '["grill","boil"]', '[]', 'null', '[{"component_id":"steak","name":"grilled strip steak","made_in_recipe":true,"store_bought":false,"ingredients":["strip steaks","coarse salt"]},{"component_id":"chimichurri","name":"chimichurri","made_in_recipe":true,"store_bought":false,"ingredients":["parsley","oregano","garlic","red wine vinegar","chile flakes","olive oil"]},{"component_id":"potatoes","name":"grilled potatoes","made_in_recipe":true,"store_bought":false,"ingredients":["potatoes","water","olive oil"]},{"component_id":"salad","name":"ensalada criolla","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","onion","green pepper","vinegar","olive oil"]}]', 'published', 'draft', 'global', NULL, '442678c504d8d623a975c49324ff740a520de1696c49f7aed4ac677c01300383', 'flavorweave-catalog-package', 'catalog/argentine-chimichurri-steak-potatoes/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_austrian-pork-schnitzel-potato-salad_v1', 'rcp_austrian-pork-schnitzel-potato-salad', 'austrian-pork-schnitzel-potato-salad', 1, 'Austrian Pork Schnitzel with Warm Viennese Potato Salad and Lemon', 'Pork loin cutlets pounded thin, coated in flour, egg, and fine breadcrumbs, and shallow-fried in oil until puffed and golden, served with lemon wedges and a warm Viennese potato salad of sliced Yukon Gold potatoes, red onion, and chives in a tangy vinegar-mustard dressing.', 4, 12, 38, 50, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', '4-quart pot over high, then a simmer, for the potatoes; 1-quart saucepan for the dressing. 12-inch heavy skillet with oil about 1/4 inch deep over medium-high (340 F) for the schnitzel.', 'Potato slices tender but holding their shape. Schnitzel crust deep golden and puffed away from the meat in places; pork 145 F.', '["shallow-fry","boil"]', '[]', 'null', '[{"component_id":"schnitzel","name":"pork schnitzel","made_in_recipe":true,"store_bought":false,"ingredients":["pork loin cutlets","salt","black pepper","flour","eggs","breadcrumbs","neutral oil","lemon"]},{"component_id":"potato-salad","name":"warm Viennese potato salad","made_in_recipe":true,"store_bought":false,"ingredients":["Yukon Gold potatoes","water","salt","vinegar","Dijon mustard","sugar","neutral oil","red onion","chives"]}]', 'published', 'draft', 'global', NULL, '91e2b32a3019dfb4c844458714eb00ae9dfa771a04628b4cb57a1538b5f10b51', 'flavorweave-catalog-package', 'catalog/austrian-pork-schnitzel-potato-salad/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_baked-ziti-italian-sausage_v1', 'rcp_baked-ziti-italian-sausage', 'baked-ziti-italian-sausage', 1, 'Baked Ziti with Italian Sausage', 'Ziti tossed in a garlicky crushed-tomato and browned Italian sausage sauce with mozzarella, layered with pockets of basil-seasoned ricotta, topped with more mozzarella and Parmesan, and baked until bubbling and golden.', 4, 10, 52, 62, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-high to brown, gentle simmer for the sauce, 400°F oven upper-middle rack (preheat overlaps prep and sauce).', 'Sausage browned with no pink. Pasta just under al dente before baking, tender after. Sauce bubbling at the edges; mozzarella melted with golden-brown spots; ricotta pockets creamy. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"sausage-tomato-sauce","name":"Italian sausage tomato sauce","made_in_recipe":true,"store_bought":false,"ingredients":["Italian sausage","olive oil","onion","garlic","dried oregano","red pepper flakes","crushed tomatoes","kosher salt"]},{"component_id":"basil-ricotta","name":"seasoned basil ricotta","made_in_recipe":true,"store_bought":false,"ingredients":["whole-milk ricotta","basil","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, '4cc7e6ceedb9ae5830c2720530968fe4c3c68432635ac38ba9349a95aa459b61', 'flavorweave-catalog-package', 'catalog/baked-ziti-italian-sausage/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_balkan-cevapi-ajvar_v1', 'rcp_balkan-cevapi-ajvar', 'balkan-cevapi-ajvar', 1, 'Balkan Cevapi with Ajvar, Raw Onion, and Warm Pita', 'Small garlicky sausages of ground beef and lamb seasoned with paprika, seared until browned, tucked into warm pita with ajvar red pepper relish, chopped raw onion, and a cucumber, tomato, and parsley salad.', 4, 23, 26, 49, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '12-inch cast-iron skillet over medium-high.', 'Cevapi browned on all sides and 160 F inside, still juicy.', '["sear","toast"]', '[]', 'null', '[{"component_id":"cevapi","name":"cevapi","made_in_recipe":true,"store_bought":false,"ingredients":["ground beef","ground lamb","garlic","baking soda","sweet paprika","salt","black pepper","water","neutral oil"]},{"component_id":"salad","name":"cucumber tomato salad","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber","tomatoes","parsley","olive oil","salt"]},{"component_id":"serve","name":"pita, ajvar, and onion","made_in_recipe":true,"store_bought":false,"ingredients":["pita","ajvar","yellow onion"]}]', 'published', 'draft', 'global', NULL, 'ae700a32262c3abb1e4a1e68bb8d409f301e6ed38ac98704e1d7cc52e677daa6', 'flavorweave-catalog-package', 'catalog/balkan-cevapi-ajvar/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_bangers-and-mash-onion-gravy_v1', 'rcp_bangers-and-mash-onion-gravy', 'bangers-and-mash-onion-gravy', 1, 'Bangers and Mash with Onion Gravy', 'The British pub classic: plump pork sausages browned slowly in a skillet, served on fluffy buttery mashed potatoes and smothered in a rich, glossy onion gravy made in the same pan, finished with chives.', 4, 15, 36, 51, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-low skillet for the sausages; medium for the onions and gravy; steady boil for the potatoes.', 'Sausages browned all over and 160 F inside. Onions soft and deep golden. Gravy coats a spoon. Potatoes fall apart when pierced.', '["sear","boil","simmer"]', '[]', 'null', '[{"component_id":"sausages","name":"browned pork sausages with onion gravy","made_in_recipe":true,"store_bought":false,"ingredients":["pork sausages","onions","flour","beef stock","thyme","Dijon","oil"]},{"component_id":"mash","name":"buttery mashed potatoes","made_in_recipe":true,"store_bought":false,"ingredients":["potatoes","water","butter","milk","chives","salt"]}]', 'published', 'draft', 'global', NULL, '13a244e0de2b10fdda509743b099f412067e450b197541d7cb9ebcfda1675988', 'flavorweave-catalog-package', 'catalog/bangers-and-mash-onion-gravy/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_basque-hake-salsa-verde_v1', 'rcp_basque-hake-salsa-verde', 'basque-hake-salsa-verde', 1, 'Basque Hake in Salsa Verde with Peas and Potatoes', 'Hake fillets gently cooked in a Basque green sauce of olive oil, garlic, white wine, and plenty of parsley, thickened lightly with flour, with sweet peas, served over boiled potatoes.', 4, 10, 25, 35, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-low in a 12-inch skillet with a lid for the garlic and sauce; a covered gentle simmer for the fish. A 4-quart pot at a boil for the potatoes.', 'Garlic pale gold, never brown. Sauce lightly thickened and green. Fish opaque and flaking, 145 F. Potatoes tender.', '["simmer","boil"]', '[]', 'null', '[{"component_id":"salsa-verde","name":"Basque green sauce","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","garlic","flour","white wine","water","parsley"]},{"component_id":"fish","name":"hake with peas","made_in_recipe":true,"store_bought":false,"ingredients":["hake","peas"]},{"component_id":"potatoes","name":"boiled potatoes","made_in_recipe":true,"store_bought":false,"ingredients":["potatoes","water","salt"]}]', 'published', 'draft', 'global', NULL, '4e8261e6cec2c0b05f68a0cd7ea7fbd31a91cbb729c53e481ae79be580592a66', 'flavorweave-catalog-package', 'catalog/basque-hake-salsa-verde/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_bengali-mustard-fish_v1', 'rcp_bengali-mustard-fish', 'bengali-mustard-fish', 1, 'Bengali Shorshe Maach: Haddock in Mustard-Seed Sauce with Rice', 'Turmeric-rubbed haddock seared lightly and simmered in a pungent Bengali sauce of freshly ground yellow and brown mustard seeds, green chiles, and nigella seeds, finished with a drizzle of mustard oil. Served with plain basmati rice.', 4, 12, 24, 36, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high in a 12-inch nonstick skillet to sear the fish, then a gentle medium-low simmer. Low covered heat for the rice.', 'Fish lightly golden, opaque, flaking, and 145 F. Sauce creamy-looking, mustard-yellow, and coating the fish without splitting.', '["sear","simmer"]', '[]', 'null', '[{"component_id":"shorshe","name":"mustard-seed sauce","made_in_recipe":true,"store_bought":false,"ingredients":["yellow mustard seeds","brown mustard seeds","green chiles","nigella seeds","turmeric","mustard oil","water"]},{"component_id":"fish","name":"seared haddock","made_in_recipe":true,"store_bought":false,"ingredients":["haddock","turmeric","salt"]},{"component_id":"rice","name":"basmati rice","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '7cf61f2051462fd43a70deab2b1241d740337ce4c44d87423319cedad57176f2', 'flavorweave-catalog-package', 'catalog/bengali-mustard-fish/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_bhindi-masala-chapati_v1', 'rcp_bhindi-masala-chapati', 'bhindi-masala-chapati', 1, 'Bhindi Masala: Crisp-Edged Spiced Okra with Homemade Chapati', 'Okra cut into coins and seared in a wide skillet until browned at the edges and not slimy, then tossed with onion, tomato, cumin, and warm spices. Served with soft whole-wheat chapatis cooked on a dry skillet.', 4, 25, 44, 69, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium-high in an uncovered 12-inch skillet for the okra; medium for the masala. A dry 10-inch cast-iron skillet over medium-high for the chapatis.', 'Okra browned at the edges, tender, and no longer sticky or stringy. Onion soft and lightly golden; tomatoes broken down. Chapatis blistered with light brown spots, soft and pliable.', '["sear","saute","griddle"]', '[]', 'null', '[{"component_id":"bhindi","name":"okra masala","made_in_recipe":true,"store_bought":false,"ingredients":["okra","onion","tomatoes","garlic","ginger","green chile","spices","lemon"]},{"component_id":"chapati","name":"whole-wheat chapatis","made_in_recipe":true,"store_bought":false,"ingredients":["whole-wheat flour","water","salt","oil"]}]', 'published', 'draft', 'global', NULL, 'd9ae645eaf6cc891f5d991177020d4c884efe1724f7b540beeae022e153c9648', 'flavorweave-catalog-package', 'catalog/bhindi-masala-chapati/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_bhutanese-ema-datshi_v1', 'rcp_bhutanese-ema-datshi', 'bhutanese-ema-datshi', 1, 'Bhutanese Ema Datshi: Green Chiles in Farmer''s Cheese Sauce with Red Rice', 'Halved Anaheim chiles and jalapenos, stems left on, simmered with onion, tomatoes, garlic, and butter, then melted into a loose, tangy sauce of farmer''s cheese and feta, served over nutty Bhutanese red rice.', 4, 14, 36, 50, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '3-quart saucepan over medium, covered then uncovered, for the chiles; 2-quart saucepan for the rice.', 'Chile halves soft and olive-green but holding their shape; cheese melted into a loose, creamy, slightly curdy sauce; rice tender with a little chew.', '["simmer","steam"]', '[]', 'null', '[{"component_id":"datshi","name":"ema datshi","made_in_recipe":true,"store_bought":false,"ingredients":["Anaheim chiles","jalapenos","yellow onion","water","butter","tomatoes","garlic","farmer''s cheese","feta","salt"]},{"component_id":"rice","name":"Bhutanese red rice","made_in_recipe":true,"store_bought":false,"ingredients":["red rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '5e4f18055c53e90e58894d6e26cfbe8362a9583ddf1979e12e44b31d3eca5b5f', 'flavorweave-catalog-package', 'catalog/bhutanese-ema-datshi/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_black-bean-quesadillas_v1', 'rcp_black-bean-quesadillas', 'black-bean-quesadillas', 1, 'Black Bean Quesadillas', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["plant","dairy","tacos"]', 'null', '[]', 'retired', 'published', 'global', NULL, '35fd87e13963cdf466b205a5d7e410f13a1f8fb84ef65de920e340e4eb35fb85', 'flavorweave-legacy-catalog-package', 'catalog/black-bean-quesadillas/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_black-bean-quesadillas_v2', 'rcp_black-bean-quesadillas', 'black-bean-quesadillas', 2, 'Black Bean Quesadillas', NULL, 4, 15, 20, 35, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', NULL, NULL, '["skillet"]', '["dairy"]', 'null', '[]', 'published', 'draft', 'global', NULL, 'deb26fa1375d109d48b297588dd197d87ab31b14c99367cfa7e0ca44fe4ca14b', 'flavorweave-legacy-catalog-package', 'catalog/black-bean-quesadillas/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_brazilian-feijoada_v1', 'rcp_brazilian-feijoada', 'brazilian-feijoada', 1, 'Brazilian Feijoada with Rice, Garlicky Collards, Farofa, and Orange', 'Brazil''s Saturday feast: black beans slowly simmered with smoky bacon, browned pork shoulder, and linguica sausage until thick and inky, served with white rice, quick garlicky collard ribbons, toasty cassava-flour farofa, and fresh orange slices to cut the richness.', 4, 20, 144, 164, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium-high to render and brown; low simmer for about 2 hours; medium-high for the collards; medium for the farofa.', 'Beans creamy and fully tender, liquid thick and dark. Pork shoulder fork-tender. Rice tender. Farofa golden and sandy.', '["sear","simmer","saute"]', '[]', 'null', '[{"component_id":"feijoada","name":"black bean and pork stew","made_in_recipe":true,"store_bought":false,"ingredients":["black beans","bacon","pork shoulder","linguica","onion","garlic","bay leaves","water","salt"]},{"component_id":"linguica","name":"smoked linguica","made_in_recipe":false,"store_bought":true,"ingredients":["linguica"],"contract":"Smoked linguica whose label lists no wheat, milk, or soy."},{"component_id":"rice","name":"white rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain rice","water","salt"]},{"component_id":"collards","name":"garlicky collards (couve)","made_in_recipe":true,"store_bought":false,"ingredients":["collard greens","garlic","olive oil"]},{"component_id":"farofa","name":"farofa","made_in_recipe":true,"store_bought":false,"ingredients":["cassava flour","olive oil","garlic","salt"]},{"component_id":"oranges","name":"orange slices","made_in_recipe":true,"store_bought":false,"ingredients":["oranges"]}]', 'published', 'draft', 'global', NULL, 'aea96324c3d80d8f48532eb7fb6182241afc90c28584d409d50226744466eccc', 'flavorweave-catalog-package', 'catalog/brazilian-feijoada/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_brazilian-fish-moqueca_v1', 'rcp_brazilian-fish-moqueca', 'brazilian-fish-moqueca', 1, 'Brazilian Fish Moqueca', 'Lime-and-garlic-marinated halibut layered with onion, red and yellow pepper rings, and tomato, then gently simmered in coconut milk with sweet paprika and olive oil until just flaky; finished with lime and cilantro and served over white rice. A Bahian-style coconut moqueca made with olive oil instead of dende. White fish only; no shrimp or shellfish.', 4, 15, 25, 40, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium sauté, then gentle covered simmer at medium-low. Rice on high then low. No oven.', 'Fish opaque and flaking at the thickest part (145°F), still moist. Peppers tender with rings intact. Broth creamy, coral-colored, and bright with lime. Rice fluffy. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"lime-garlic-marinade","name":"lime-garlic-paprika fish marinade","made_in_recipe":true,"store_bought":false,"ingredients":["lime juice","garlic","sweet paprika","kosher salt","black pepper"]},{"component_id":"coconut-moqueca","name":"layered coconut moqueca","made_in_recipe":true,"store_bought":false,"ingredients":["halibut","onion","red and yellow bell peppers","tomatoes","chile","coconut milk","olive oil","cilantro","garlic","sweet paprika"]},{"component_id":"white-rice-cooked","name":"steamed white rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain white rice","water","kosher salt"]}]', 'published', 'draft', 'global', NULL, '579c986ff149b9451f5ed2403197ffe53865241793f060ee2a9bc6f591730ff4', 'flavorweave-catalog-package', 'catalog/brazilian-fish-moqueca/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_british-kedgeree-smoked-salmon_v1', 'rcp_british-kedgeree-smoked-salmon', 'british-kedgeree-smoked-salmon', 1, 'British Kedgeree with Hot-Smoked Salmon, Jammy Eggs, and Peas', 'Basmati rice cooked with onion and curry powder, folded with flakes of hot-smoked salmon and peas, and topped with jammy halved eggs, parsley, and lemon wedges.', 4, 8, 40, 48, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '3-quart saucepan over medium for the onion, then covered over low for the rice; 2-quart saucepan for the eggs.', 'Rice tender and fluffy with a yellow tint; eggs with set whites and jammy yolks (7 minutes); salmon warmed through.', '["steam","boil","saute"]', '[]', 'null', '[{"component_id":"rice","name":"curried rice","made_in_recipe":true,"store_bought":false,"ingredients":["neutral oil","yellow onion","curry powder","basmati rice","water","salt","frozen peas","hot-smoked salmon","parsley","lemon"]},{"component_id":"eggs","name":"jammy eggs","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","water"]}]', 'published', 'draft', 'global', NULL, '48fd64f02404ce82660d6e3f2c19b6285f019e6f972859c6c9b0946b9725b263', 'flavorweave-catalog-package', 'catalog/british-kedgeree-smoked-salmon/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_burmese-mohinga-fish-noodle-soup_v1', 'rcp_burmese-mohinga-fish-noodle-soup', 'burmese-mohinga-fish-noodle-soup', 1, 'Burmese Mohinga: Catfish and Lemongrass Noodle Soup', 'Myanmar''s national breakfast, perfect for dinner: a turmeric-gold catfish broth fragrant with lemongrass, ginger, and garlic, thickened with toasted chickpea flour and ground rice, poured over thin rice noodles and finished with boiled egg, lime, cilantro, and chile.', 4, 20, 43, 63, 'involved', 'adventurous', '6ee7bb37273cbc12eff6d5be73cdb6c79a88a65cdfe5ea686de96c0b7a43a78d', 'Gentle poach for the fish; medium sauté for the aromatics; medium-low simmer for the broth; rolling boil for noodles and eggs.', 'Catfish opaque and flaking (145 F). Broth lightly thickened and silky. Noodles tender. Eggs hard-boiled with set yolks.', '["poach","simmer","boil"]', '[]', 'null', '[{"component_id":"broth","name":"catfish lemongrass broth","made_in_recipe":true,"store_bought":false,"ingredients":["catfish","lemongrass","ginger","garlic","shallots","turmeric","paprika","chickpea flour","jasmine rice","fish sauce","water","oil"]},{"component_id":"noodles","name":"rice noodles","made_in_recipe":true,"store_bought":false,"ingredients":["thin rice noodles","water"]},{"component_id":"eggs","name":"hard-boiled eggs","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","water"]},{"component_id":"garnish","name":"lime, cilantro, chile","made_in_recipe":true,"store_bought":false,"ingredients":["limes","cilantro","chile flakes"]}]', 'published', 'draft', 'global', NULL, 'd3cb64e1413f1d6d83027a1b64d7f6ff64c4f64b612424f2fda5a47d0481f758', 'flavorweave-catalog-package', 'catalog/burmese-mohinga-fish-noodle-soup/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_cajun-blackened-catfish_v1', 'rcp_cajun-blackened-catfish', 'cajun-blackened-catfish', 1, 'Cajun Blackened Catfish with Herb Remoulade', 'Catfish fillets coated in Cajun blackening spices and seared hard in a hot skillet, served with a dairy-free herb remoulade.', 4, 12, 17, 29, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Skillet preheated over medium-high until very hot. Blacken over medium-high. No oven. No grill required.', 'Spice crust darkened (blackened) and fragrant, not raw-spice pale and not incinerated ash. Fish opaque and flakes at the thickest point, about 145 F. Remoulade cold and spoonable. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"cajun-blackening-rub","name":"Cajun blackening rub","made_in_recipe":true,"store_bought":false,"ingredients":["sweet paprika","cayenne pepper","garlic powder","onion powder","dried thyme","dried oregano","kosher salt","black pepper"]},{"component_id":"herb-remoulade","name":"dairy-free herb remoulade","made_in_recipe":true,"store_bought":false,"ingredients":["egg mayonnaise","Dijon mustard","lemon juice","neutral oil","dill pickle relish","capers","fresh parsley","fresh chives","garlic","hot sauce","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, 'f6f9000f85acd078d6220d96465402869319d655fdf98f7da0cd3f9140fbec97', 'flavorweave-catalog-package', 'catalog/cajun-blackened-catfish/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_cambodian-fish-amok_v1', 'rcp_cambodian-fish-amok', 'cambodian-fish-amok', 1, 'Cambodian Fish Amok: Steamed Coconut-Lemongrass Fish Custards with Jasmine Rice', 'Chunks of white fish folded into a custard of coconut milk, eggs, fish sauce, and a fresh kroeung paste of lemongrass, ginger, turmeric, garlic, shallot, lime leaves, and red chile, steamed in spinach-lined ramekins until just firm. Topped with a spoonful of the thick coconut milk, slivered lime leaf, and chile, with jasmine rice.', 4, 22, 32, 54, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', '14-inch wok (6-quart) with 4 cups water over high to boil, then medium for a steady steam under a two-tier 12-inch bamboo steamer. 2-quart saucepan covered on low for the rice.', 'Custard no longer jiggles at the center and a knife comes out clean; fish opaque and 145 F. Rice tender.', '["steam"]', '[]', 'null', '[{"component_id":"kroeung","name":"kroeung paste","made_in_recipe":true,"store_bought":false,"ingredients":["lemongrass","ginger","turmeric","garlic","shallots","makrut lime leaves","red chile","coconut milk"]},{"component_id":"amok","name":"steamed fish custards","made_in_recipe":true,"store_bought":false,"ingredients":["white fish","coconut milk","eggs","fish sauce","brown sugar","kroeung","spinach"]},{"component_id":"rice","name":"steamed jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '4854d3c76d9a5aaf7a2f015bffcf4714ec481a2fe280a6e96e0887bc567da844', 'flavorweave-catalog-package', 'catalog/cambodian-fish-amok/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_cantonese-char-siu-pork-rice_v1', 'rcp_cantonese-char-siu-pork-rice', 'cantonese-char-siu-pork-rice', 1, 'Cantonese Char Siu Pork with Rice and Blanched Gai Lan', 'Strips of pork shoulder marinated in hoisin, soy sauce, Shaoxing wine, five-spice, garlic, and honey, roasted on a rack and basted until lacquered and charred at the edges. Sliced over steamed rice with blanched gai lan and a drizzle of the reduced glaze.', 4, 10, 177, 187, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Oven preheated to 425 F with the pork on a rack over a water-filled pan. A 1-quart saucepan at a simmer for the glaze. A 4-quart pot at a boil for the gai lan. Low covered heat for the rice.', 'Pork 160 F, sticky and lacquered with charred edges. Gai lan bright green and crisp-tender. Glaze syrupy.', '["roast","boil","simmer"]', '[]', 'null', '[{"component_id":"char-siu","name":"char siu pork","made_in_recipe":true,"store_bought":false,"ingredients":["pork shoulder","hoisin","soy sauce","Shaoxing wine","honey","five-spice","garlic","sesame oil"]},{"component_id":"rice","name":"steamed rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]},{"component_id":"gai-lan","name":"blanched gai lan","made_in_recipe":true,"store_bought":false,"ingredients":["gai lan","water","oil","soy sauce"]}]', 'published', 'draft', 'global', NULL, '47c5dbbd92ece588d5980e9a46c058e492c7127c21ca2afa9c80531754b7e652', 'flavorweave-catalog-package', 'catalog/cantonese-char-siu-pork-rice/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_cashew-chicken-stir-fry_v1', 'rcp_cashew-chicken-stir-fry', 'cashew-chicken-stir-fry', 1, 'Cashew Chicken Stir-Fry', 'Takeout-style cashew chicken at home: cornstarch-velveted chicken breast seared in a hot skillet with red bell pepper, celery, onion, garlic, and ginger, glossed in a savory-sweet soy-hoisin sauce, and tossed with toasted cashews and scallions over jasmine rice.', 4, 15, 18, 33, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'High to boil the rice, then low; medium dry skillet for the cashews; high heat for searing and stir-frying. No oven.', 'Chicken golden in spots and just cooked through (165 F). Vegetables crisp-tender with a few charred spots. Sauce glossy and lightly thick, coating rather than pooling. Cashews golden. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"velveted-chicken","name":"cornstarch-velveted seared chicken","made_in_recipe":true,"store_bought":false,"ingredients":["chicken breast","soy sauce","dry sherry","cornstarch","neutral oil"]},{"component_id":"soy-hoisin-sauce","name":"soy-hoisin stir-fry sauce","made_in_recipe":true,"store_bought":false,"ingredients":["soy sauce","dry sherry","hoisin sauce","brown sugar","cornstarch","water"]},{"component_id":"cashew-vegetable-stir-fry","name":"cashew vegetable stir-fry","made_in_recipe":true,"store_bought":false,"ingredients":["red bell pepper","celery","yellow onion","scallions","garlic","fresh ginger","toasted cashews","toasted sesame oil"]},{"component_id":"jasmine-rice","name":"steamed jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]}]', 'published', 'draft', 'global', NULL, 'd25d86a4609eea21ea2350e4010c18c54b5aaf26931fbeef9891c82e31d6f083', 'flavorweave-catalog-package', 'catalog/cashew-chicken-stir-fry/v1.json', '2026-10-04T00:00:00.000Z');
