INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_chicken-andouille-gumbo_v1', 'rcp_chicken-andouille-gumbo', 'chicken-andouille-gumbo', 1, 'Chicken and Andouille Gumbo with a Dark Roux', 'A Louisiana gumbo built on a slowly stirred chocolate-brown roux and the holy trinity of onion, celery, and green pepper, simmered with smoky andouille, chicken thighs, thyme, and bay until rich and silky. Served over white rice with scallions and hot sauce.', 4, 20, 101, 121, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium-high to brown the meats; medium to medium-low for the roux (constant stirring); low simmer for the gumbo.', 'Roux the color of milk chocolate and smelling toasty, not burnt. Chicken tender enough to shred (175 F or more). Gumbo silky and coating a spoon thinly.', '["sear","simmer"]', '[]', 'null', '[{"component_id":"gumbo","name":"chicken and andouille gumbo","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","andouille","flour","oil","onion","celery","green pepper","garlic","chicken stock","Cajun seasoning","thyme","bay","hot sauce"]},{"component_id":"rice","name":"white rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain rice","water"]}]', 'published', 'draft', 'global', NULL, '9b4512540a41a95c7cedaf73d2250474283764e33795be6f912cbaa93e59593c', 'flavorweave-catalog-package', 'catalog/chicken-andouille-gumbo/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_chicken-enchiladas-verdes_v1', 'rcp_chicken-enchiladas-verdes', 'chicken-enchiladas-verdes', 1, 'Chicken Enchiladas Verdes', 'Broiler-charred tomatillos, jalapeños, onion, and garlic blended with cilantro and lime into a bright salsa verde; broiled cumin chicken thighs shredded with salsa and Monterey Jack, rolled in warm corn tortillas, smothered in more salsa and cheese, and baked until bubbling. Finished with lime crema, diced onion, radishes, and cilantro.', 4, 15, 47, 62, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'High broiler (heats during prep), then 425°F bake.', 'Chicken 175°F and tender before shredding. Salsa bubbling at the edges, cheese melted with golden spots, tortillas soft (not dry at the ends). kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"salsa-verde","name":"broiled tomatillo salsa verde","made_in_recipe":true,"store_bought":false,"ingredients":["tomatillos","white onion","jalapeños","garlic","cilantro","lime juice","kosher salt","water"]},{"component_id":"chicken-filling","name":"shredded cumin chicken filling","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","ground cumin","salsa verde","Monterey Jack"]},{"component_id":"lime-crema","name":"lime crema","made_in_recipe":true,"store_bought":false,"ingredients":["sour cream","lime juice","water"]}]', 'published', 'draft', 'global', NULL, '66ba530265c87cea6e3afefced150833767e9d9db06eec3a29b7ae2acf5ec782', 'flavorweave-catalog-package', 'catalog/chicken-enchiladas-verdes/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_chicken-tinga-tostadas_v1', 'rcp_chicken-tinga-tostadas', 'chicken-tinga-tostadas', 1, 'Chicken Tinga Tostadas with Crema, Queso Fresco, and Avocado', 'Chicken thighs poached with onion, garlic, and bay, shredded and simmered in a smoky sauce of crushed tomatoes, chipotles in adobo, sliced onion, and oregano, heaped on crisp corn tostadas with shredded lettuce, Mexican crema, queso fresco, avocado, and lime.', 4, 6, 50, 56, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '4-quart pot for poaching; 12-inch skillet over medium for the tinga.', 'Chicken 175 F and tender enough to shred; sauce reduced so the chicken is moist but not soupy.', '["poach","simmer"]', '[]', 'null', '[{"component_id":"chicken","name":"poached chicken","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","water","white onion","garlic","bay leaf","salt"]},{"component_id":"tinga","name":"tinga sauce","made_in_recipe":true,"store_bought":false,"ingredients":["neutral oil","white onion","crushed tomatoes","chipotles in adobo","dried oregano","salt"]},{"component_id":"tostadas","name":"tostadas and toppings","made_in_recipe":true,"store_bought":false,"ingredients":["corn tostadas","lettuce","Mexican crema","queso fresco","avocados","lime"]}]', 'published', 'draft', 'global', NULL, '39fd181048f1cc7cceaec946a74ac23dd416455fc6155c3ab0ef39e106d68007', 'flavorweave-catalog-package', 'catalog/chicken-tinga-tostadas/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_chilean-porotos-granados_v1', 'rcp_chilean-porotos-granados', 'chilean-porotos-granados', 1, 'Chilean Porotos Granados: Bean, Squash, and Corn Stew with Pebre', 'Chile''s summer stew of cranberry beans, butternut squash that melts into the broth, and sweet corn, seasoned with paprika, oregano, and lots of fresh basil. Topped with pebre, a bright cilantro, tomato, and chile salsa.', 4, 15, 38, 53, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Medium sauté; medium-low simmer.', 'Squash partly collapsed so the stew is thick and orange; corn tender; beans creamy.', '["saute","simmer"]', '[]', 'null', '[{"component_id":"stew","name":"bean, squash, and corn stew","made_in_recipe":true,"store_bought":false,"ingredients":["cranberry beans","butternut squash","corn","onion","garlic","paprika","oregano","basil","water","oil"]},{"component_id":"pebre","name":"pebre","made_in_recipe":true,"store_bought":false,"ingredients":["tomato","cilantro","jalapeño","red onion","red wine vinegar","oil"]}]', 'published', 'draft', 'global', NULL, '27e25b3877713865a222057d583b8b02d1b0bdf03e529bc2007b59a988118c83', 'flavorweave-catalog-package', 'catalog/chilean-porotos-granados/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_chiles-rellenos-ranchero_v1', 'rcp_chiles-rellenos-ranchero', 'chiles-rellenos-ranchero', 1, 'Cheese Chiles Rellenos with Ranchero Sauce and Rice', 'Broiler-blistered poblano chiles stuffed with melting Monterey Jack, dipped in a cloud-light whipped egg batter, and shallow-fried until golden and puffed. Served on a chunky tomato-jalapeño ranchero sauce with cilantro-lime rice and a drizzle of crema.', 4, 20, 41, 61, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Broiler on high, rack 4 inches below, to blister the chiles. Medium skillet for the sauce. Oil at 350 F in a 12-inch skillet, about 1/2 inch deep, for shallow-frying.', 'Poblano skins blackened and blistered all over; batter deep golden and puffed; cheese fully melted inside.', '["broil","shallow-fry","simmer"]', '[]', 'null', '[{"component_id":"chiles","name":"cheese-stuffed battered poblanos","made_in_recipe":true,"store_bought":false,"ingredients":["poblanos","Monterey Jack","eggs","flour","oil","salt"]},{"component_id":"ranchero","name":"ranchero sauce","made_in_recipe":true,"store_bought":false,"ingredients":["fire-roasted tomatoes","onion","garlic","jalapeño","oregano","water","oil","salt"]},{"component_id":"rice","name":"cilantro-lime rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain rice","water","cilantro","lime","salt"]},{"component_id":"crema","name":"Mexican crema","made_in_recipe":false,"store_bought":true,"ingredients":["Mexican crema"]}]', 'published', 'draft', 'global', NULL, 'e9579cede179596cd7ae93f6792039bd0403caf65edb38f3e0d72fce17c72c40', 'flavorweave-catalog-package', 'catalog/chiles-rellenos-ranchero/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_chinese-egg-foo-young_v1', 'rcp_chinese-egg-foo-young', 'chinese-egg-foo-young', 1, 'Egg Foo Young with Mushroom Gravy and Steamed Rice', 'Fluffy pan-fried omelette patties packed with bean sprouts, shiitake mushrooms, carrot, and scallions, served over steamed rice with a glossy brown soy gravy.', 4, 12, 28, 40, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', 'Medium-high in a 12-inch nonstick skillet for the vegetables, medium for the patties. A 1-quart saucepan at a simmer for the gravy. Low covered heat for the rice.', 'Vegetables just softened. Patties puffed, golden-brown on both sides, and set in the center. Gravy glossy and thick enough to coat a spoon.', '["pan-fry","saute","simmer"]', '[]', 'null', '[{"component_id":"patties","name":"egg foo young patties","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","bean sprouts","shiitake mushrooms","carrot","scallions"]},{"component_id":"gravy","name":"soy gravy","made_in_recipe":true,"store_bought":false,"ingredients":["water","soy sauce","cornstarch","sugar","sesame oil"]},{"component_id":"rice","name":"steamed rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]}]', 'published', 'draft', 'global', NULL, '310589f2ae7af7a5a9d6e10b2ef9c21e91901f2c69351ae2b33ed549d72d8249', 'flavorweave-catalog-package', 'catalog/chinese-egg-foo-young/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_chinese-hot-sour-soup-tofu_v1', 'rcp_chinese-hot-sour-soup-tofu', 'chinese-hot-sour-soup-tofu', 1, 'Chinese Hot and Sour Soup with Tofu, Shiitake, and Egg Ribbons', 'Dried shiitake mushrooms, bamboo shoots, ginger, and firm tofu simmered in vegetable broth with soy sauce, thickened with cornstarch, swirled with egg ribbons, and sharpened with rice vinegar, white pepper, and toasted sesame oil, served with jasmine rice and scallions.', 4, 4, 51, 55, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '4-quart pot over high to a boil, then a simmer; 2-quart saucepan for the rice.', 'Soup lightly thickened and glossy; egg set in thin ribbons; sour and peppery heat both clearly present.', '["simmer","steam"]', '[]', 'null', '[{"component_id":"soup","name":"hot and sour soup","made_in_recipe":true,"store_bought":false,"ingredients":["dried shiitake mushrooms","water","vegetable broth","ginger","bamboo shoots","soy sauce","firm tofu","cornstarch","water","eggs","rice vinegar","white pepper","toasted sesame oil"]},{"component_id":"rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water","salt"]},{"component_id":"garnish","name":"scallions","made_in_recipe":true,"store_bought":false,"ingredients":["scallions"]}]', 'published', 'draft', 'global', NULL, 'df286be47d2282294ff76376d2d434249ae6082b76c7f2981648ac93fa75fb07', 'flavorweave-catalog-package', 'catalog/chinese-hot-sour-soup-tofu/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_chinese-tomato-egg-stir-fry_v1', 'rcp_chinese-tomato-egg-stir-fry', 'chinese-tomato-egg-stir-fry', 1, 'Chinese Tomato and Egg Stir-Fry over Rice', 'The Chinese home-cooking classic: soft, fluffy scrambled eggs folded into juicy tomatoes cooked down with garlic, ginger, a little sugar, soy sauce, and scallions into a glossy sweet-savory sauce, spooned over jasmine rice.', 4, 10, 15, 25, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-high wok for soft-set eggs, then high for the tomatoes, then medium to fold together.', 'Eggs in large soft curds, just set and still glossy. Tomatoes collapsed into a thick, juicy sauce that clings.', '["stir-fry"]', '[]', 'null', '[{"component_id":"tomato-egg","name":"tomato and egg stir-fry","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","tomatoes","garlic","ginger","scallions","sugar","soy sauce","cornstarch","water","oil"]},{"component_id":"rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]}]', 'published', 'draft', 'global', NULL, 'c1e8a588b9845805a44eb9222d49648013a2c771ad6fd8a75efdaaac8354c9eb', 'flavorweave-catalog-package', 'catalog/chinese-tomato-egg-stir-fry/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_chipotle-lime-black-bean-bowls_v1', 'rcp_chipotle-lime-black-bean-bowls', 'chipotle-lime-black-bean-bowls', 1, 'Chipotle Lime Black Bean Bowls', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["plant","dairy-free","bowl"]', 'null', '[]', 'retired', 'published', 'global', NULL, 'dd3f209efdf2ff62d5fa5044d86f5672bc20c71275e1135975b16b090e10e5a3', 'flavorweave-legacy-catalog-package', 'catalog/chipotle-lime-black-bean-bowls/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_chipotle-lime-black-bean-bowls_v2', 'rcp_chipotle-lime-black-bean-bowls', 'chipotle-lime-black-bean-bowls', 2, 'Chipotle Lime Black Bean Bowls', 'Black beans simmered with minced chipotle and lime, with quinoa and corn. No extra toppings.', 4, 10, 20, 30, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Stovetop simmer for quinoa and beans. No oven and no grill. Mild heat from 1 tsp minced chipotle across 4 servings.', 'Quinoa is done when the grains are tender, a white ring just shows, and the water is absorbed, about 15 minutes plus a 5-minute rest. Beans are done when hot and coated, about 10 minutes. They are not a soup.', '["stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, '1e4b81cb3fb2be7f37d2dce68b2a9b4dbfd65bfc22e2643cea28934be5df5a2b', 'flavorweave-legacy-audit-draft', 'catalog/chipotle-lime-black-bean-bowls/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_cider-braised-pork-shoulder_v1', 'rcp_cider-braised-pork-shoulder', 'cider-braised-pork-shoulder', 1, 'Cider-Braised Pork Shoulder with Mustard Cabbage', 'A long cider braise of pork shoulder, reduced to a spoon-coating sauce with apple, served with skillet mustard cabbage.', 4, 20, 192, 212, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Sear on the stove over medium-high, then a covered oven braise at 325 F. Sauce reduces at a boil. Cabbage skillet is medium.', 'Pork shoulder at 195-203 F in the center and fork-tender. 145 F is not done for this cut. Rest 15 minutes. Slice 1/2 inch against the grain if it holds; pull large chunks if it collapses. Do not puree it.', '[]', '[]', 'null', '[{"component_id":"cider-mustard-sauce","name":"cider-mustard sauce","made_in_recipe":true,"store_bought":false,"ingredients":["apple cider","water","dijon mustard","yellow onion","apple","garlic","fresh thyme"]},{"component_id":"mustard-cabbage","name":"mustard cabbage","made_in_recipe":true,"store_bought":false,"ingredients":["green cabbage","olive oil","water","apple cider vinegar","dijon mustard","kosher salt"]}]', 'published', 'draft', 'global', NULL, '543e6e4d799aa2b8d1a414d94db5cba35d92645f15d3db4e2288d0a3b537c42a', 'flavorweave-catalog-package', 'catalog/cider-braised-pork-shoulder/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_citrus-fennel-arctic-char_v1', 'rcp_citrus-fennel-arctic-char', 'citrus-fennel-arctic-char', 1, 'Citrus Fennel Arctic Char', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["fish","finfish","dairy-free"]', 'null', '[]', 'retired', 'published', 'global', NULL, 'c5d794fbb31da2395ea6c5e3d29d1b797ec1844a84c3b1254ffe01f5a4bdfc08', 'flavorweave-legacy-catalog-package', 'catalog/citrus-fennel-arctic-char/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_citrus-fennel-arctic-char_v2', 'rcp_citrus-fennel-arctic-char', 'citrus-fennel-arctic-char', 2, 'Citrus Fennel Arctic Char', 'Roasted arctic char on sheet-pan fennel, finished with fresh dill and orange zest and juice.', 4, 15, 27, 42, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'none', 'Thickest part just opaque, flakes with a fork, 140-145 F. Not chalky. Fennel edges softened and starting to brown.', '["roast"]', '["dairy-free"]', '{"butter":"Do not swap the olive oil for butter. That would drop the dairy-free claim.","lemon":"Do not swap the orange for lemon. The citrus in this dish is orange."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, '49dc99220a2e78675387e8ef81e9be63fb02c9685a54bbd309666cea407c3847', 'flavorweave-legacy-catalog-package', 'catalog/citrus-fennel-arctic-char/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_classic-smash-burgers_v1', 'rcp_classic-smash-burgers', 'classic-smash-burgers', 1, 'Classic Smash Burgers with Special Sauce', 'Double smash burgers: loose balls of 80/20 ground chuck pressed thin onto a ripping-hot cast-iron skillet for lacy, deeply browned edges, stacked with melted American cheese on butter-toasted sesame buns with a tangy pickle special sauce, dill pickles, paper-thin onion, and shredded iceberg.', 4, 10, 21, 31, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-high cast iron, very hot before the first smash. No oven.', 'Patties 1/4 inch thin with lacy, deep-brown crusted edges, cooked through to no more than a trace of pink (ground beef safe target 160°F). Cheese fully melted and draped. Buns golden on the cut side. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"special-sauce","name":"pickle special sauce","made_in_recipe":true,"store_bought":false,"ingredients":["mayonnaise","ketchup","yellow mustard","chopped dill pickles","pickle brine","garlic powder","black pepper"]},{"component_id":"double-smash-patties","name":"double smash patties with American cheese","made_in_recipe":true,"store_bought":false,"ingredients":["80/20 ground chuck","American cheese","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, '666724ec16022eebef4eb2a04e1b5498c83439d7d3c4f15410cffcce4162445b', 'flavorweave-catalog-package', 'catalog/classic-smash-burgers/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_cobb-salad_v1', 'rcp_cobb-salad', 'cobb-salad', 1, 'Classic Cobb Salad with Seared Chicken, Bacon, Egg, and Blue Cheese', 'Crisp romaine arranged in rows of sliced pan-seared chicken, crisp bacon, hard-cooked eggs, avocado, cherry tomatoes, and crumbled blue cheese, dressed with a sharp red-wine and Dijon vinaigrette.', 4, 14, 36, 50, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', 'Medium in a 12-inch skillet for the bacon, then medium-high for the chicken. A 3-quart saucepan at a gentle boil for the eggs.', 'Bacon crisp. Chicken golden outside and 165 F inside. Eggs cooked 10 minutes, yolks just set.', '["sear","boil"]', '[]', 'null', '[{"component_id":"chicken","name":"seared chicken","made_in_recipe":true,"store_bought":false,"ingredients":["chicken breasts","salt","pepper"]},{"component_id":"bacon","name":"crisp bacon","made_in_recipe":false,"store_bought":true,"ingredients":["bacon"]},{"component_id":"eggs","name":"hard-cooked eggs","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","water"]},{"component_id":"salad","name":"composed salad","made_in_recipe":true,"store_bought":false,"ingredients":["romaine","avocado","cherry tomatoes","blue cheese","chives"]},{"component_id":"vinaigrette","name":"red wine vinaigrette","made_in_recipe":true,"store_bought":false,"ingredients":["red wine vinegar","Dijon","olive oil","garlic"]}]', 'published', 'draft', 'global', NULL, '439382cbbec0a2b282881001dfe012d8d8a713d5f20175de49ae9ef7922dce59', 'flavorweave-catalog-package', 'catalog/cobb-salad/v1.json', '2026-10-04T00:00:00.000Z');
