INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_hawaiian-ahi-poke-bowl_v1', 'rcp_hawaiian-ahi-poke-bowl', 'hawaiian-ahi-poke-bowl', 1, 'Hawaiian Shoyu Ahi Poke Bowls with Seasoned Rice, Cucumber, Avocado, and Edamame', 'Cubes of sashimi-grade ahi tuna tossed in a shoyu dressing of soy sauce, sesame oil, sweet onion, scallions, ginger, and red chile flakes, served over vinegar-seasoned short-grain rice with cucumber, avocado, edamame, nori strips, and toasted sesame seeds.', 4, 23, 12, 35, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', 'Only the rice is cooked: 2-quart saucepan brought to a boil, then covered on low. The tuna is served raw.', 'Rice tender and slightly sticky. Tuna cold, deep red, and freshly dressed.', '["no-cook","simmer"]', '[]', 'null', '[{"component_id":"poke","name":"shoyu ahi poke","made_in_recipe":true,"store_bought":false,"ingredients":["ahi tuna","soy sauce","toasted sesame oil","sweet onion","scallions","ginger","red chile flakes"]},{"component_id":"rice","name":"seasoned short-grain rice","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","water","rice vinegar","sugar","salt"]},{"component_id":"toppings","name":"bowl toppings","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber","avocado","edamame","nori","sesame seeds"]}]', 'published', 'draft', 'global', NULL, '3f9b53f96761dc05b7fe5d72b5fe8ad7aba0107ba90d374b692f1f8541804115', 'flavorweave-catalog-package', 'catalog/hawaiian-ahi-poke-bowl/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_hawaiian-huli-huli-chicken_v1', 'rcp_hawaiian-huli-huli-chicken', 'hawaiian-huli-huli-chicken', 1, 'Hawaiian Huli-Huli Chicken with Grilled Pineapple and Rice', 'Boneless chicken thighs marinated in pineapple juice, soy sauce, brown sugar, ketchup, ginger, and garlic, grilled and turned and basted with the reduced glaze until sticky and charred. Served with grilled pineapple, white rice, and scallions.', 4, 8, 96, 104, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', 'Grill preheated on medium-high for 10 minutes, about 425 F at the grate. A 1-quart saucepan at a lively simmer to reduce the glaze. Low covered heat for the rice.', 'Chicken charred at the edges, glazed, and 175 F. Pineapple with dark grill marks and warmed through. Glaze reduced to a syrup.', '["grill","simmer"]', '[]', 'null', '[{"component_id":"chicken","name":"huli-huli chicken","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","pineapple juice","soy sauce","brown sugar","ketchup","ginger","garlic"]},{"component_id":"pineapple","name":"grilled pineapple","made_in_recipe":true,"store_bought":false,"ingredients":["pineapple"]},{"component_id":"rice","name":"white rice","made_in_recipe":true,"store_bought":false,"ingredients":["rice","water"]}]', 'published', 'draft', 'global', NULL, '9807ba0b25ffd7ef13b4376c3b44972f8ad4fd5b09f756c8ac90d4409e9a105a', 'flavorweave-catalog-package', 'catalog/hawaiian-huli-huli-chicken/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_herb-roast-turkey-breast-cranberry_v1', 'rcp_herb-roast-turkey-breast-cranberry', 'herb-roast-turkey-breast-cranberry', 1, 'Herb-Butter Roast Turkey Breast with Cranberry-Orange Sauce and Roasted Vegetables', 'A boneless turkey breast roast rubbed under and over the skin with garlic, sage, thyme, and rosemary butter, roasted over potatoes, carrots, and red onion until golden and juicy. Served sliced with a quick fresh cranberry-orange sauce.', 4, 20, 98, 118, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Oven preheated to 375 F. A 2-quart saucepan at a simmer for the cranberry sauce.', 'Turkey 160 F at the thickest part before resting (rises to about 165 F). Skin golden. Vegetables tender and browned. Cranberries burst and the sauce thick.', '["roast","simmer"]', '[]', 'null', '[{"component_id":"turkey","name":"herb-butter roast turkey breast","made_in_recipe":true,"store_bought":false,"ingredients":["turkey breast","butter","garlic","sage","thyme","rosemary"]},{"component_id":"vegetables","name":"roasted vegetables","made_in_recipe":true,"store_bought":false,"ingredients":["potatoes","carrots","red onion","olive oil"]},{"component_id":"cranberry","name":"cranberry-orange sauce","made_in_recipe":true,"store_bought":false,"ingredients":["cranberries","orange","sugar","water"]}]', 'published', 'draft', 'global', NULL, 'f91ca81ead287961562598825bc57f39251b1d2f61962991bb602d5745ae1a88', 'flavorweave-catalog-package', 'catalog/herb-roast-turkey-breast-cranberry/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_herb-vegetable-pot-pie_v1', 'rcp_herb-vegetable-pot-pie', 'herb-vegetable-pot-pie', 1, 'Herb Vegetable Pot Pie', 'Carrots, parsnips, and Yukon Gold potatoes in a thyme-rosemary butter-and-cream gravy, baked under an egg-washed all-butter puff pastry lid until golden and flaky.', 4, 20, 67, 87, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Oven 400 F, rack in center, preheated during prep. Stovetop medium for butter and vegetables; medium-low simmer for the gravy. Bake on a rimmed sheet pan to catch bubbling.', 'Pastry puffed, flaky, and deep golden-brown (not pale, not scorched at the corners). Gravy bubbling through the vents and thick enough to coat a spoon after the 10-minute rest. Potato, carrot, and parsnip cubes fork-tender. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"herb-root-vegetable-gravy-filling","name":"herb root-vegetable gravy filling","made_in_recipe":true,"store_bought":false,"ingredients":["unsalted butter","yellow onion","celery","carrots","parsnips","Yukon Gold potatoes","garlic","fresh thyme","fresh rosemary","all-purpose flour","vegetable stock","heavy cream","frozen peas","fresh parsley","kosher salt","black pepper"]},{"component_id":"puff-pastry-lid","name":"egg-washed all-butter puff pastry lid","made_in_recipe":false,"store_bought":true,"contract":"Store-bought frozen all-butter puff pastry (wheat + butter). Egg wash made in recipe.","ingredients":["all-butter puff pastry","egg","water","all-purpose flour (for dusting)"]}]', 'published', 'draft', 'global', NULL, '45fc61066938a832ff0e551ded955998af95ddf62dc5fba448a3e4a6779ded39', 'flavorweave-catalog-package', 'catalog/herb-vegetable-pot-pie/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_herbed-polenta-tomato-stew_v1', 'rcp_herbed-polenta-tomato-stew', 'herbed-polenta-tomato-stew', 1, 'Herbed Polenta with Tomato Stew', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["plant","dairy-free"]', 'null', '[]', 'retired', 'published', 'global', NULL, '036a89689f43fd794de0a949e645e235ae5e77950392a382b7c0164a2e2e8c57', 'flavorweave-legacy-catalog-package', 'catalog/herbed-polenta-tomato-stew/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_herbed-polenta-tomato-stew_v2', 'rcp_herbed-polenta-tomato-stew', 'herbed-polenta-tomato-stew', 2, 'Herbed Polenta with Tomato Stew', 'Soft stovetop polenta with a burst cherry-tomato and white-bean stew finished with fresh rosemary.', 4, 10, 22, 32, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'none', 'Polenta thick and soft, pulling from the side of the pan. Tomatoes burst; stew spoonable, not watery.', '["stovetop"]', '["plant","dairy-free"]', '{"butter or cheese":"Do not add butter or cheese. Either one would drop the dairy-free claim.","rosemary":"Use fresh. Do not use 1 tbsp dried rosemary."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, '19a5acddec61d7d7624eb4ff5ed6c9520d7c71f0c1ccdc54b4da6425d6d81f72', 'flavorweave-legacy-catalog-package', 'catalog/herbed-polenta-tomato-stew/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_hungarian-chicken-paprikash_v1', 'rcp_hungarian-chicken-paprikash', 'hungarian-chicken-paprikash', 1, 'Hungarian Chicken Paprikash with Buttered Egg Noodles and Cucumber Salad', 'Bone-in chicken thighs browned and braised in a velvety sauce of slow-cooked onions, sweet Hungarian paprika, tomato, and pepper, finished with tangy sour cream. Served over buttered egg noodles with a cool, vinegary cucumber salad.', 4, 15, 60, 75, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high to brown; medium for the onions; low covered braise; boil for the noodles.', 'Chicken 175 F and tender at the bone. Sauce brick-orange and silky after the sour cream (not boiled).', '["sear","braise","boil"]', '[]', 'null', '[{"component_id":"paprikash","name":"chicken paprikash","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","onions","sweet paprika","hot paprika","tomato","bell pepper","chicken stock","flour","sour cream","salt"]},{"component_id":"noodles","name":"buttered egg noodles","made_in_recipe":true,"store_bought":false,"ingredients":["egg noodles","butter","parsley","water","salt"]},{"component_id":"salad","name":"cucumber salad","made_in_recipe":true,"store_bought":false,"ingredients":["cucumbers","white vinegar","sugar","salt"]}]', 'published', 'draft', 'global', NULL, 'f4d4208ef9655475e25c9923fff5b392d213aef9b32f5567bc7a321e75257225', 'flavorweave-catalog-package', 'catalog/hungarian-chicken-paprikash/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_indian-paneer-tikka_v1', 'rcp_indian-paneer-tikka', 'indian-paneer-tikka', 1, 'Paneer Tikka with Peppers and Onions, Mint Chutney, and Naan', 'Cubes of paneer marinated in thick yogurt, ginger, garlic, Kashmiri chili, garam masala, and lemon, threaded with bell peppers and red onion, and charred under the broiler. Served with a fresh mint-cilantro yogurt chutney, warm naan, and a kachumber salad.', 4, 15, 51, 66, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Broiler preheated on high for 5 minutes, with the rack 6 inches below the element.', 'Paneer edges charred in spots and hot through. Peppers and onion softened and blistered at the edges.', '["broil"]', '[]', 'null', '[{"component_id":"tikka","name":"paneer tikka","made_in_recipe":true,"store_bought":false,"ingredients":["paneer","yogurt","ginger","garlic","Kashmiri chili","garam masala","lemon","bell peppers","red onion"]},{"component_id":"chutney","name":"mint-cilantro chutney","made_in_recipe":true,"store_bought":false,"ingredients":["mint","cilantro","green chile","yogurt","lemon"]},{"component_id":"salad","name":"kachumber","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber","tomato","red onion","lemon"]},{"component_id":"naan","name":"naan","made_in_recipe":false,"store_bought":true,"ingredients":["naan"]}]', 'published', 'draft', 'global', NULL, '9a8e37779f66f7e1ac8b5b2f4a5313705b259f074b35b119eb4be6cd6fe23df8', 'flavorweave-catalog-package', 'catalog/indian-paneer-tikka/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_indo-chinese-gobi-manchurian_v1', 'rcp_indo-chinese-gobi-manchurian', 'indo-chinese-gobi-manchurian', 1, 'Indo-Chinese Gobi Manchurian with Basmati Rice', 'Cauliflower florets coated in a cornstarch-and-flour batter with chili powder, shallow-fried crisp, then tossed in a glossy sauce of ginger, garlic, onion, green bell pepper, soy sauce, ketchup, sriracha, and rice vinegar with scallions, served with basmati rice.', 4, 16, 28, 44, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', '12-inch heavy skillet with oil about 1/3 inch deep over medium-high (350 F) for the cauliflower, then 2 tbsp of that oil over high for the sauce; 2-quart saucepan for the rice.', 'Florets crisp and golden on all sides and tender in the middle; sauce glossy and just thick enough to cling.', '["shallow-fry","saute","steam"]', '[]', 'null', '[{"component_id":"gobi","name":"crisp cauliflower","made_in_recipe":true,"store_bought":false,"ingredients":["cauliflower","cornstarch","all-purpose flour","chili powder","salt","water","neutral oil"]},{"component_id":"sauce","name":"Manchurian sauce","made_in_recipe":true,"store_bought":false,"ingredients":["ginger","garlic","red onion","green bell pepper","soy sauce","ketchup","sriracha","rice vinegar","water","cornstarch","scallions"]},{"component_id":"rice","name":"basmati rice","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '5f1b33b4178c359cc13e73e1d0c4d463029ad5382ca43524ac51ccfa61f7f72c', 'flavorweave-catalog-package', 'catalog/indo-chinese-gobi-manchurian/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_indonesian-gado-gado-tempeh_v1', 'rcp_indonesian-gado-gado-tempeh', 'indonesian-gado-gado-tempeh', 1, 'Indonesian Gado-Gado with Pan-Fried Tempeh, Eggs, and Peanut Sauce', 'A composed plate of boiled potatoes, green beans, cabbage, bean sprouts, cucumber, hard-cooked eggs, and golden pan-fried tempeh, spooned with a warm sweet-spicy peanut sauce of peanut butter, garlic, red chile, tamarind, soy sauce, brown sugar, and lime.', 4, 15, 32, 47, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', '4-quart pot over high, then a steady simmer for the potatoes and eggs and a full boil for the vegetables. 12-inch skillet over medium-high for the tempeh. 2-quart saucepan over medium-low for the sauce.', 'Potatoes knife-tender. Eggs hard-cooked with set yolks (10 minutes). Green beans bright and crisp-tender; cabbage just wilted; sprouts barely softened. Tempeh golden on both sides. Sauce smooth, pourable, and warm.', '["boil","blanch","pan-fry","simmer"]', '[]', 'null', '[{"component_id":"vegetables","name":"boiled and blanched vegetables","made_in_recipe":true,"store_bought":false,"ingredients":["potatoes","green beans","cabbage","bean sprouts","cucumber"]},{"component_id":"eggs","name":"hard-cooked eggs","made_in_recipe":true,"store_bought":false,"ingredients":["eggs"]},{"component_id":"tempeh","name":"pan-fried tempeh","made_in_recipe":true,"store_bought":false,"ingredients":["tempeh","neutral oil","salt"]},{"component_id":"sauce","name":"peanut sauce","made_in_recipe":true,"store_bought":false,"ingredients":["peanut butter","water","soy sauce","brown sugar","tamarind","garlic","red chile","lime"]}]', 'published', 'draft', 'global', NULL, '354b3398a7061eb704ccf33d343a5ac389e095bd5285a798d28ddf5e328208de', 'flavorweave-catalog-package', 'catalog/indonesian-gado-gado-tempeh/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_indonesian-ikan-bakar-tilapia_v1', 'rcp_indonesian-ikan-bakar-tilapia', 'indonesian-ikan-bakar-tilapia', 1, 'Indonesian Ikan Bakar: Broiled Kecap-Glazed Tilapia with Sambal Tomat', 'Tilapia fillets marinated in kecap manis, lime, garlic, and turmeric and broiled with more glaze until lacquered and charred at the edges, served with a fresh sambal of cherry tomatoes, shallots, Thai chiles, sambal oelek, and lime, plus jasmine rice and cucumber.', 4, 12, 30, 42, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Broiler on high with a rack 5 inches below, fish on an oiled foil-lined sheet pan; 2-quart saucepan for the rice.', 'Glaze bubbling and charred in spots; fish opaque and flaking, 145 F.', '["broil","steam"]', '[]', 'null', '[{"component_id":"fish","name":"kecap-glazed tilapia","made_in_recipe":true,"store_bought":false,"ingredients":["tilapia fillets","kecap manis","lime juice","garlic","turmeric","salt","neutral oil"]},{"component_id":"sambal","name":"sambal tomat","made_in_recipe":true,"store_bought":false,"ingredients":["cherry tomatoes","shallots","Thai chiles","sambal oelek","lime juice","salt"]},{"component_id":"rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]},{"component_id":"cucumber","name":"cucumber","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber"]}]', 'published', 'draft', 'global', NULL, '8a9341a4c153f4786014e91a1f9b4a04d553e97824af693b22183f8cbfd6ba47', 'flavorweave-catalog-package', 'catalog/indonesian-ikan-bakar-tilapia/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_irish-beef-stew_v1', 'rcp_irish-beef-stew', 'irish-beef-stew', 1, 'Irish Beef and Stout Stew with Potatoes and Carrots', 'Chunks of beef chuck browned and slowly simmered in Irish stout with onions, carrots, potatoes, tomato paste, and thyme until the meat is spoon-tender and the gravy is dark and glossy. Served with crusty bread.', 4, 18, 166, 184, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-high in a 6-quart Dutch oven to brown, then a covered gentle simmer on the stovetop.', 'Beef spoon-tender. Potatoes and carrots soft. Gravy dark, glossy, and thick enough to coat a spoon.', '["sear","braise","simmer"]', '[]', 'null', '[{"component_id":"stew","name":"beef and stout stew","made_in_recipe":true,"store_bought":false,"ingredients":["beef chuck","flour","stout","onions","carrots","potatoes","tomato paste","thyme","bay","water"]},{"component_id":"bread","name":"crusty bread","made_in_recipe":false,"store_bought":true,"ingredients":["crusty bread"]}]', 'published', 'draft', 'global', NULL, 'b3866dd122ba3f0131ed29250277bb8c0ffd72a5c894b9de549952238155ab1e', 'flavorweave-catalog-package', 'catalog/irish-beef-stew/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_italian-chicken-cacciatore_v1', 'rcp_italian-chicken-cacciatore', 'italian-chicken-cacciatore', 1, 'Italian Chicken Cacciatore with Peppers, Mushrooms, and Crusty Bread', 'Bone-in chicken thighs browned and braised hunter-style with bell peppers, onion, cremini mushrooms, garlic, rosemary, red wine, tomatoes, and olives until fall-off-the-bone tender. Served with crusty bread for the sauce.', 4, 14, 67, 81, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-high in a 5-quart Dutch oven to brown, medium for the vegetables, then a covered gentle simmer on the stovetop.', 'Chicken skin browned; meat 175 F and tender near the bone. Peppers soft but holding shape. Sauce thick enough to coat a spoon.', '["sear","braise"]', '[]', 'null', '[{"component_id":"cacciatore","name":"chicken cacciatore","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","peppers","onion","mushrooms","garlic","rosemary","red wine","tomatoes","olives"]},{"component_id":"bread","name":"crusty bread","made_in_recipe":false,"store_bought":true,"ingredients":["crusty bread"]}]', 'published', 'draft', 'global', NULL, '009ba84b8374486685bfb82b2e3abbdcfaca98e34c547a775b98041aaa349f9c', 'flavorweave-catalog-package', 'catalog/italian-chicken-cacciatore/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_italian-grilled-calamari_v1', 'rcp_italian-grilled-calamari', 'italian-grilled-calamari', 1, 'Italian Grilled Calamari with Tomato-Caper Salad and Grilled Bread', 'Cleaned squid tubes and tentacles marinated briefly in olive oil, garlic, lemon zest, and chile flakes, grilled fast over high heat until tender and lightly charred, and tossed with a salad of cherry tomatoes, capers, red onion, parsley, and arugula. Served with grilled garlic bread.', 4, 12, 22, 34, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', 'Grill preheated on high for 10 minutes, about 500 F at the grate.', 'Squid opaque, lightly charred, and tender after 1 to 2 minutes per side; overcooking makes it rubbery. Bread marked and crisp at the edges.', '["grill"]', '[]', 'null', '[{"component_id":"calamari","name":"grilled calamari","made_in_recipe":true,"store_bought":false,"ingredients":["squid","olive oil","garlic","lemon zest","chile flakes"]},{"component_id":"salad","name":"tomato-caper salad","made_in_recipe":true,"store_bought":false,"ingredients":["cherry tomatoes","capers","red onion","parsley","arugula","lemon juice","olive oil"]},{"component_id":"bread","name":"grilled garlic bread","made_in_recipe":false,"store_bought":true,"ingredients":["crusty bread","garlic","olive oil"]}]', 'published', 'draft', 'global', NULL, 'f42a67192be724a132470912f56d34cf14cfaa28d58bf28de42087633c937709', 'flavorweave-catalog-package', 'catalog/italian-grilled-calamari/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_ivorian-chicken-kedjenou_v1', 'rcp_ivorian-chicken-kedjenou', 'ivorian-chicken-kedjenou', 1, 'Ivorian Chicken Kedjenou with Eggplant, Tomatoes, and Rice', 'Bone-in chicken thighs layered in a sealed Dutch oven with onion, tomatoes, eggplant, red bell pepper, a whole Scotch bonnet, garlic, ginger, thyme, and bay, gently stewed in their own juices without added liquid, served over long-grain rice.', 4, 15, 55, 70, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', '5.5-quart Dutch oven with a tight lid over medium-low; 2-quart saucepan for the rice.', 'Chicken 175 F at the bone and falling from it; vegetables collapsed into a thick red stew.', '["braise","steam"]', '[]', 'null', '[{"component_id":"stew","name":"kedjenou","made_in_recipe":true,"store_bought":false,"ingredients":["bone-in chicken thighs","salt","neutral oil","yellow onion","tomatoes","eggplant","red bell pepper","Scotch bonnet","garlic","ginger","thyme","bay leaves"]},{"component_id":"rice","name":"rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain white rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '63317416c6d4c2546846ae20c7b511009f83b2e51b40273bcefa6dec11c1b59a', 'flavorweave-catalog-package', 'catalog/ivorian-chicken-kedjenou/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_jamaican-escovitch-snapper_v1', 'rcp_jamaican-escovitch-snapper', 'jamaican-escovitch-snapper', 1, 'Jamaican Escovitch Fish: Pan-Fried Snapper with Pickled Pepper-Onion Escovitch and Rice', 'Skin-on red snapper fillets rubbed with lime, dredged in seasoned flour, and pan-fried until golden, then topped with a hot, tangy escovitch of onion, carrot, red bell pepper, garlic, and Scotch bonnet quick-cooked in vinegar with allspice and thyme. Served with steamed white rice.', 4, 12, 31, 43, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', '12-inch skillet over medium-high with a thin layer of oil, about 1/8 inch (1/2 cup), for the fish. 3-quart saucepan brought to a boil, then a brief simmer, for the escovitch. 2-quart saucepan covered on low for the rice.', 'Fish golden and crisp on the skin side, opaque and flaking at 145 F. Escovitch vegetables crisp-tender and glossy. Rice tender.', '["pan-fry","simmer"]', '[]', 'null', '[{"component_id":"fish","name":"pan-fried snapper","made_in_recipe":true,"store_bought":false,"ingredients":["red snapper","lime","salt","black pepper","flour","neutral oil"]},{"component_id":"escovitch","name":"escovitch vegetables","made_in_recipe":true,"store_bought":false,"ingredients":["vinegar","water","sugar","allspice","thyme","salt","onion","carrot","red bell pepper","Scotch bonnet","garlic"]},{"component_id":"rice","name":"steamed white rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '130e66096c3a94997443d4a891e5b63718fa1591c6d33ead6e3870992894e8a4', 'flavorweave-catalog-package', 'catalog/jamaican-escovitch-snapper/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_jamaican-ital-stew_v1', 'rcp_jamaican-ital-stew', 'jamaican-ital-stew', 1, 'Jamaican Ital Stew with Squash, Kidney Beans, and Coconut', 'Butternut squash, sweet potato, carrots, okra, and red kidney beans simmered in coconut milk with onion, garlic, ginger, scallions, thyme, allspice, and a whole scotch bonnet, finished with spinach.', 4, 18, 46, 64, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', '5.5-quart Dutch oven over medium, then a covered simmer.', 'Squash and sweet potato tender with some edges melting into the broth; okra tender; broth creamy and lightly thickened.', '["simmer"]', '[]', 'null', '[{"component_id":"stew","name":"ital stew","made_in_recipe":true,"store_bought":false,"ingredients":["neutral oil","yellow onion","garlic","ginger","scallions","thyme","allspice","butternut squash","sweet potato","carrots","coconut milk","water","salt","scotch bonnet","kidney beans","okra","baby spinach"]}]', 'published', 'draft', 'global', NULL, 'aa0b1573c1d93f0b341c8fbb52fcfa2f425a6ef697a4ecc65d4551324aa5e966', 'flavorweave-catalog-package', 'catalog/jamaican-ital-stew/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_jamaican-jerk-pork-chops_v1', 'rcp_jamaican-jerk-pork-chops', 'jamaican-jerk-pork-chops', 1, 'Jamaican Jerk Pork Chops with Pineapple Slaw', 'Bone-in pork chops coated in a blended Scotch-bonnet jerk paste, skillet-seared, served with crunchy pineapple-cabbage slaw.', 4, 20, 32, 52, 'moderate', 'adventurous', 'faa682b9a0717b5d4bda5d085b90e9d959a1bb70b759e3868f62c05f4a543240', 'Medium skillet for the chops; lower to medium-low if the paste threatens to burn. No oven.', 'Pork chops 145 F in the thickest part away from bone, then 5-minute rest. Paste deep brown, not bitter black. Slaw crunchy. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"jerk-paste","name":"jerk paste","made_in_recipe":true,"store_bought":false,"ingredients":["scallions","fresh thyme","garlic","fresh ginger","Scotch bonnet pepper","ground allspice","ground cinnamon","ground nutmeg","light brown sugar","tamari","lime juice","olive oil","kosher salt","black pepper"]},{"component_id":"pineapple-slaw","name":"pineapple slaw","made_in_recipe":true,"store_bought":false,"ingredients":["green cabbage","fresh pineapple","red bell pepper","fresh cilantro","lime","kosher salt"]}]', 'published', 'draft', 'global', NULL, 'c49e814367ccbeb825dab502b09688a15243a1f4a6ca78234eef5db8c7f3d1c2', 'flavorweave-catalog-package', 'catalog/jamaican-jerk-pork-chops/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_japanese-chicken-nanban_v1', 'rcp_japanese-chicken-nanban', 'japanese-chicken-nanban', 1, 'Japanese Chicken Nanban with Tartar Sauce, Shredded Cabbage, and Rice', 'Boneless chicken thighs dredged in flour and egg, shallow-fried golden, then dipped in a sweet-sour nanban sauce of rice vinegar, soy sauce, and sugar and topped with a chunky tartar sauce of boiled egg, mayonnaise, sweet pickle relish, onion, parsley, and lemon, served with shredded cabbage and short-grain rice.', 4, 18, 51, 69, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', '12-inch heavy skillet with oil about 1/4 inch deep over medium (340 F); 2-quart saucepan for the eggs; 1-quart saucepan for the sauce; 2-quart saucepan for the rice.', 'Coating golden and set; chicken 175 F at the thickest point; sauce soaked in but the coating still tender-crisp.', '["shallow-fry","boil","simmer","steam"]', '[]', 'null', '[{"component_id":"eggs","name":"boiled eggs","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","water"]},{"component_id":"tartar","name":"tartar sauce","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","mayonnaise","sweet pickle relish","yellow onion","parsley","lemon juice","salt"]},{"component_id":"sauce","name":"nanban sauce","made_in_recipe":true,"store_bought":false,"ingredients":["rice vinegar","soy sauce","sugar"]},{"component_id":"chicken","name":"chicken nanban","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","salt","flour","eggs","neutral oil"]},{"component_id":"sides","name":"rice and cabbage","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","water","green cabbage"]}]', 'published', 'draft', 'global', NULL, '1cb2b959d748fc24d2c3c6a3cf3943e3dcc612b7c02a36c2a84ca5cc2d820865', 'flavorweave-catalog-package', 'catalog/japanese-chicken-nanban/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_japanese-gyudon_v1', 'rcp_japanese-gyudon', 'japanese-gyudon', 1, 'Gyudon: Japanese Simmered Beef and Onion Rice Bowl', 'A 25-minute Japanese comfort bowl: thinly sliced beef and sweet onion simmered in a gingery soy, mirin, and sugar broth until tender, ladled with its juices over steamed short-grain rice and topped with scallions and pickled red ginger.', 4, 8, 17, 25, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Medium simmer for the onion; gentle simmer for the beef.', 'Onion soft and translucent; beef just cooked through and tender, with no pink.', '["simmer"]', '[]', 'null', '[{"component_id":"beef","name":"simmered beef and onion","made_in_recipe":true,"store_bought":false,"ingredients":["shaved beef","onion","soy sauce","mirin","sugar","ginger","water"]},{"component_id":"rice","name":"short-grain rice","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","water"]}]', 'published', 'draft', 'global', NULL, 'dfeef1ff4458974093b5f9f2245cf65fc56eee1571bef4090a7969ac576a612e', 'flavorweave-catalog-package', 'catalog/japanese-gyudon/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_japanese-hambagu_v1', 'rcp_japanese-hambagu', 'japanese-hambagu', 1, 'Japanese Hambagu: Beef and Pork Hamburg Steaks with Rich Pan Sauce', 'Tender, juicy Japanese-style hamburg steaks of ground beef and pork with sauteed onion, milk-soaked panko, and egg, seared and steamed until plump, then glazed in a pan sauce of red wine, ketchup, soy sauce, and butter. Served with rice and a shredded cabbage salad.', 4, 6, 38, 44, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium for the onions, medium-high to sear the patties, then covered medium-low to steam them through, then a quick simmer for the sauce. Low covered heat for the rice.', 'Patties browned on both sides, plump, and 160 F at the center; juices run clear. Sauce glossy and slightly thick.', '["sear","steam","saute","simmer"]', '[]', 'null', '[{"component_id":"hambagu","name":"hamburg steaks","made_in_recipe":true,"store_bought":false,"ingredients":["ground beef","ground pork","onion","panko","milk","egg","nutmeg"]},{"component_id":"sauce","name":"pan sauce","made_in_recipe":true,"store_bought":false,"ingredients":["red wine","ketchup","soy sauce","sugar","butter","water"]},{"component_id":"rice","name":"short-grain rice","made_in_recipe":true,"store_bought":false,"ingredients":["rice","water"]},{"component_id":"salad","name":"cabbage salad","made_in_recipe":true,"store_bought":false,"ingredients":["cabbage","carrot","rice vinegar","oil"]}]', 'published', 'draft', 'global', NULL, '04de8b788774c280ee9f66c1a608324b0b0b5ef84526f59f2b73dd5c9c74024c', 'flavorweave-catalog-package', 'catalog/japanese-hambagu/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_japanese-okonomiyaki_v1', 'rcp_japanese-okonomiyaki', 'japanese-okonomiyaki', 1, 'Okonomiyaki (Japanese Cabbage Pancakes)', 'Thick, crisp-edged cabbage-and-scallion pancakes with seared shiitake on the underside, brushed with a quick homemade okonomi-style sauce (ketchup, Worcestershire, soy), striped with Japanese egg-yolk mayonnaise, and showered with bonito flakes. No pork, shrimp, squid, or cheese.', 4, 15, 26, 41, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Stovetop medium (or griddle 375 F), covered for each side so the thick cabbage center steams through while the outside crisps. No oven.', 'Both faces deep golden and crisp at the edges; center set with no wet batter (about 160 F for the egg batter); cabbage tender-crisp; shiitake browned. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"cabbage-pancake","name":"cabbage-scallion okonomiyaki with seared shiitake","made_in_recipe":true,"store_bought":false,"ingredients":["all-purpose flour","baking powder","kosher salt","cold water","soy sauce","eggs","green cabbage","scallions","shiitake mushrooms","neutral oil"]},{"component_id":"okonomi-style-sauce","name":"quick okonomi-style sauce","made_in_recipe":true,"store_bought":false,"ingredients":["ketchup","Worcestershire sauce","soy sauce","sugar"],"contract":"Made in the recipe instead of bottled okonomi sauce, which can contain oyster extract (shellfish)."},{"component_id":"toppings","name":"Japanese mayo lattice, bonito flakes, scallion greens","made_in_recipe":false,"store_bought":true,"ingredients":["Japanese egg-yolk mayonnaise","bonito flakes","scallion greens","optional aonori","optional pickled red ginger"],"contract":"Mayonnaise is egg-yolk mayonnaise with no milk; bonito flakes are plain katsuobushi."}]', 'published', 'draft', 'global', NULL, '6e6c17cb7267e30e1648700da499eea5ac77ad62a002636b445185599072328e', 'flavorweave-catalog-package', 'catalog/japanese-okonomiyaki/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_japanese-vegetable-curry-rice_v1', 'rcp_japanese-vegetable-curry-rice', 'japanese-vegetable-curry-rice', 1, 'Japanese Vegetable Curry Rice with a Homemade Roux', 'A mild, glossy Japanese-style curry made from scratch: onions cooked until sweet, then potatoes, carrots, and mushrooms simmered and thickened with a toasted flour-and-oil curry roux, with grated apple and a dash of soy and ketchup for depth. Served over short-grain rice.', 4, 14, 38, 52, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium in a 5-quart Dutch oven for the onions, a gentle simmer for the vegetables. Medium-low in a small skillet for the roux. Low covered heat for the rice.', 'Onions soft and lightly golden. Potatoes and carrots tender when pierced. Curry glossy, thick enough to coat a spoon. Rice tender and slightly sticky.', '["saute","simmer"]', '[]', 'null', '[{"component_id":"curry","name":"vegetable curry","made_in_recipe":true,"store_bought":false,"ingredients":["onion","potatoes","carrots","mushrooms","apple","water","soy sauce","ketchup"]},{"component_id":"roux","name":"curry roux","made_in_recipe":true,"store_bought":false,"ingredients":["flour","oil","curry powder","garam masala"]},{"component_id":"rice","name":"short-grain rice","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","water"]}]', 'published', 'draft', 'global', NULL, '466a4b144ee5df656c23be7f32a39b291058591f3065feeebcd57dfbf4537945', 'flavorweave-catalog-package', 'catalog/japanese-vegetable-curry-rice/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_japanese-vegetable-omurice_v1', 'rcp_japanese-vegetable-omurice', 'japanese-vegetable-omurice', 1, 'Japanese Vegetable Omurice with Mushroom Ketchup Rice', 'Short-grain rice stir-fried with onion, carrot, cremini mushrooms, peas, ketchup, and soy sauce, shaped into ovals and draped with a soft, barely set two-egg omelet, finished with a zigzag of ketchup.', 4, 2, 58, 60, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '2-quart saucepan for the rice; 12-inch skillet over medium-high for the rice; 8-inch nonstick skillet over medium for the omelets.', 'Rice evenly red and hot through with the ketchup lightly toasted; omelet set underneath and still soft and glossy on top.', '["steam","stir-fry","omelet"]', '[]', 'null', '[{"component_id":"rice","name":"ketchup rice","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","water","neutral oil","onion","carrot","cremini mushrooms","frozen peas","ketchup","soy sauce","salt"]},{"component_id":"omelets","name":"omelets","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","salt","neutral oil"]}]', 'published', 'draft', 'global', NULL, '6618f0062617c936f6ec39aac24d1e6fe62bbfce74719d13424c70d2d14069d5', 'flavorweave-catalog-package', 'catalog/japanese-vegetable-omurice/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_kasespatzle-caramelized-onions_v1', 'rcp_kasespatzle-caramelized-onions', 'kasespatzle-caramelized-onions', 1, 'Käsespätzle with Caramelized Onions and Cucumber-Dill Salad', 'Southern German cheese spätzle: soft homemade egg dumplings layered with nutty Gruyère and Emmental, baked until bubbling, and crowned with deep-brown butter-caramelized onions and chives. Served with a cool, tangy cucumber-dill salad.', 4, 10, 52, 62, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Oven preheated to 400 F. Medium-low skillet for the onions. Rolling boil for the spätzle.', 'Onions deep amber and jammy. Spätzle float and are tender, about 1 minute after they rise. Cheese fully melted and bubbling at the edges.', '["saute","boil","bake"]', '[]', 'null', '[{"component_id":"spaetzle","name":"egg spätzle","made_in_recipe":true,"store_bought":false,"ingredients":["flour","eggs","milk","nutmeg","salt","water"]},{"component_id":"onions","name":"caramelized onions","made_in_recipe":true,"store_bought":false,"ingredients":["onions","butter","salt"]},{"component_id":"bake","name":"layered cheese bake","made_in_recipe":true,"store_bought":false,"ingredients":["spätzle","Gruyère","Emmental","chives"]},{"component_id":"salad","name":"cucumber-dill salad","made_in_recipe":true,"store_bought":false,"ingredients":["cucumbers","white wine vinegar","sugar","dill","salt"]}]', 'published', 'draft', 'global', NULL, '5cee3280f5d0d478e0927d188e803c7394dbb82a39c09d800900a75f96acf36b', 'flavorweave-catalog-package', 'catalog/kasespatzle-caramelized-onions/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_kenyan-tilapia-ugali-sukuma_v1', 'rcp_kenyan-tilapia-ugali-sukuma', 'kenyan-tilapia-ugali-sukuma', 1, 'Kenyan Tilapia in Tomato-Onion Sauce with Ugali and Sukuma Wiki', 'Tilapia fillets pan-fried until golden, then simmered briefly in a tomato, onion, and pepper sauce with garlic and coriander. Served Kenyan-style with firm white-cornmeal ugali and sukuma wiki, collard greens sauteed with onion and tomato.', 4, 15, 48, 63, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', 'Medium-high in a 12-inch skillet to pan-fry the fish, medium for the sauce. A 4-quart pot at a boil, then medium-low, for the ugali. Medium in a second skillet for the greens.', 'Fish golden on both sides, opaque, and 145 F. Sauce thick and chunky. Ugali stiff enough to pull away from the pot in one mass and hold its shape. Collards wilted and tender but still green.', '["pan-fry","simmer","saute","boil"]', '[]', 'null', '[{"component_id":"fish","name":"tilapia in tomato-onion sauce","made_in_recipe":true,"store_bought":false,"ingredients":["tilapia","onion","tomatoes","bell pepper","garlic","coriander"]},{"component_id":"ugali","name":"ugali","made_in_recipe":true,"store_bought":false,"ingredients":["white cornmeal","water"]},{"component_id":"sukuma","name":"sukuma wiki","made_in_recipe":true,"store_bought":false,"ingredients":["collard greens","onion","tomato"]}]', 'published', 'draft', 'global', NULL, '63a6871dcaf1df9f59dc32407769cbc0869cb1cb05f22545c2205344a092d39b', 'flavorweave-catalog-package', 'catalog/kenyan-tilapia-ugali-sukuma/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_kimchi-fried-rice_v1', 'rcp_kimchi-fried-rice', 'kimchi-fried-rice', 1, 'Kimchi Fried Rice', 'Day-old rice stir-fried with chopped plant kimchi, kimchi brine, scallions, gochujang, and sesame oil. Vegan kimchi contracted; no egg, no bacon.', 4, 10, 15, 25, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high skillet or wok throughout. No oven.', 'Rice hot, red from kimchi, lightly toasted in spots. Kimchi jammy at edges. No raw onion crunch left in the base. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"kimchi-gochujang-base","name":"kimchi gochujang skillet base","made_in_recipe":true,"store_bought":false,"ingredients":["plant kimchi","kimchi brine","gochujang","soy sauce","garlic","onion","sugar"]},{"component_id":"kimchi-fried-rice","name":"kimchi fried rice","made_in_recipe":true,"store_bought":false,"ingredients":["day-old rice","kimchi gochujang skillet base","toasted sesame oil"]}]', 'published', 'draft', 'global', NULL, '0846b480613dd870aaac2b37362c4a383e4e0184a91d5934de3fab81ce0517ad', 'flavorweave-catalog-package', 'catalog/kimchi-fried-rice/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_korean-braised-mackerel-radish_v1', 'rcp_korean-braised-mackerel-radish', 'korean-braised-mackerel-radish', 1, 'Korean Braised Mackerel with Radish (Godeungeo Jorim)', 'Mackerel fillets braised on a bed of thick radish slices in a spicy, savory sauce of gochugaru, gochujang, soy sauce, garlic, and ginger until the radish turns tender and translucent and soaks up the sauce. Served with short-grain rice.', 4, 12, 32, 44, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high to boil the radish, then a covered medium simmer in a 12-inch braiser, then uncovered to reduce. Low covered heat for the rice.', 'Radish tender and translucent at the edges. Fish opaque, flaking, 145 F. Sauce reduced to a thick, spoonable glaze.', '["braise","simmer"]', '[]', 'null', '[{"component_id":"jorim","name":"braised mackerel and radish","made_in_recipe":true,"store_bought":false,"ingredients":["mackerel","Korean radish","onion","scallions","garlic","ginger","gochugaru","gochujang","soy sauce","sugar","water"]},{"component_id":"rice","name":"short-grain rice","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","water"]}]', 'published', 'draft', 'global', NULL, 'c8ac7aad0f7af579763d23049b42a7f7818f78a0f0ebe2350e3e22b92b8a55a9', 'flavorweave-catalog-package', 'catalog/korean-braised-mackerel-radish/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_korean-galbi-jjim_v1', 'rcp_korean-galbi-jjim', 'korean-galbi-jjim', 1, 'Korean Galbi-Jjim: Braised Beef Short Ribs with Radish and Carrots', 'Bone-in beef short ribs blanched and slowly braised on the stovetop in soy sauce, grated Asian pear, onion, garlic, and ginger until meltingly tender, with chunks of Korean radish, carrots, and shiitake mushrooms in a glossy, sweet-savory sauce. Served with short-grain rice.', 4, 18, 130, 148, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'A rolling boil in an 8-quart stockpot to blanch, then a covered gentle simmer in a 6-quart Dutch oven, then uncovered to reduce.', 'Ribs tender enough to pull from the bone with chopsticks. Radish and carrots tender. Sauce reduced to a glossy glaze.', '["boil","braise","simmer"]', '[]', 'null', '[{"component_id":"galbi-jjim","name":"braised short ribs","made_in_recipe":true,"store_bought":false,"ingredients":["short ribs","soy sauce","Asian pear","onion","garlic","ginger","brown sugar","mirin","sesame oil","radish","carrots","shiitake","water"]},{"component_id":"rice","name":"short-grain rice","made_in_recipe":true,"store_bought":false,"ingredients":["rice","water"]}]', 'published', 'draft', 'global', NULL, 'e2c861e0dc3689aa5e1d8dab97d829d9614056ea2340626ba6c8fad4b72db7c2', 'flavorweave-catalog-package', 'catalog/korean-galbi-jjim/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_korean-japchae-vegetables_v1', 'rcp_korean-japchae-vegetables', 'korean-japchae-vegetables', 1, 'Japchae: Korean Sweet Potato Glass Noodles with Vegetables and Shiitake', 'Chewy sweet potato glass noodles tossed with stir-fried onion, carrot, red bell pepper, shiitake, and scallions plus blanched spinach in a garlicky sesame-soy sauce, finished with toasted sesame seeds.', 4, 15, 28, 43, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '6-quart pot over high for the noodles and spinach. 12-inch skillet over medium-high for the vegetables, medium for the sesame seeds.', 'Onion and carrot crisp-tender; pepper bright; shiitake browned. Spinach just wilted and bright green. Noodles chewy and translucent, not mushy. Sesame seeds golden.', '["stir-fry","boil","blanch","toast"]', '[]', 'null', '[{"component_id":"noodles","name":"sweet potato glass noodles","made_in_recipe":true,"store_bought":false,"ingredients":["dangmyeon"]},{"component_id":"vegetables","name":"stir-fried vegetables and spinach","made_in_recipe":true,"store_bought":false,"ingredients":["onion","carrot","red bell pepper","shiitake","scallions","spinach"]},{"component_id":"sauce","name":"sesame-soy sauce","made_in_recipe":true,"store_bought":false,"ingredients":["soy sauce","sugar","toasted sesame oil","garlic","black pepper"]}]', 'published', 'draft', 'global', NULL, '812dcc3e52059e2ac5e1aa9f5d43479e98277012fde43f839fd85776a9001fd1', 'flavorweave-catalog-package', 'catalog/korean-japchae-vegetables/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_korean-ojingeo-bokkeum-squid_v1', 'rcp_korean-ojingeo-bokkeum-squid', 'korean-ojingeo-bokkeum-squid', 1, 'Korean Ojingeo Bokkeum: Spicy Stir-Fried Squid with Vegetables and Rice', 'Scored squid pieces and tentacles stir-fried over high heat with cabbage, carrot, onion, scallions, and jalapeno in a sweet-hot sauce of gochugaru, gochujang, soy sauce, sugar, garlic, and ginger, finished with toasted sesame oil and sesame seeds and served over short-grain rice.', 4, 24, 11, 35, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', '12-inch skillet over high; 2-quart saucepan for the rice.', 'Vegetables crisp-tender and glossy; squid just turned opaque and curled, tender rather than rubbery (about 2 minutes).', '["stir-fry","steam"]', '[]', 'null', '[{"component_id":"sauce","name":"chile sauce","made_in_recipe":true,"store_bought":false,"ingredients":["gochugaru","gochujang","soy sauce","sugar","garlic","ginger"]},{"component_id":"stir-fry","name":"squid stir-fry","made_in_recipe":true,"store_bought":false,"ingredients":["neutral oil","onion","carrot","green cabbage","jalapeno","squid","scallions","toasted sesame oil","sesame seeds"]},{"component_id":"rice","name":"short-grain rice","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","water"]}]', 'published', 'draft', 'global', NULL, '8fe60e636a308d3d4ffde5d92ccea9410f6ee9b077029d03c3ae8de12806b886', 'flavorweave-catalog-package', 'catalog/korean-ojingeo-bokkeum-squid/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_korean-soft-tofu-stew_v1', 'rcp_korean-soft-tofu-stew', 'korean-soft-tofu-stew', 1, 'Korean Soft Tofu Stew', 'Soft tofu simmered in a spicy gochugaru broth with plant kimchi, zucchini, and mushrooms. No egg, no seafood, no meat.', 4, 15, 21, 36, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', 'Medium for aromatics and chili bloom. Medium-high to bring the broth up, then medium simmer. Gentle simmer for the tofu. No oven.', 'Zucchini tender-crisp after about 8 minutes of simmer. Soft tofu hot through after about 5 gentle minutes, still in large spoonable chunks, not scrambled. Broth spicy, sour from plant kimchi, savory from soy and gochujang. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"spicy-kimchi-broth","name":"spicy kimchi broth","made_in_recipe":true,"store_bought":false,"ingredients":["neutral oil","toasted sesame oil","yellow onion","garlic","fresh ginger","shiitake mushrooms","gochugaru","gochujang","plant kimchi","zucchini","vegetable stock","water","soy sauce","sugar","kosher salt","black pepper"]}]', 'retired', 'draft', 'global', NULL, '95251c7637bc91079532daa8ae702061caf5f5fd09c956de7fbd70d9cee2152b', 'flavorweave-catalog-package', 'catalog/korean-soft-tofu-stew/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_korean-soft-tofu-stew_v2', 'rcp_korean-soft-tofu-stew', 'korean-soft-tofu-stew', 2, 'Korean Soft Tofu Stew', 'Soft tofu simmered in a spicy gochugaru broth with plant kimchi and zucchini. No egg, no seafood, no meat.', 4, 15, 21, 36, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', 'Medium for aromatics and chili bloom. Medium-high to bring the broth up, then medium simmer. Gentle simmer for the tofu. No oven.', 'Zucchini tender-crisp after about 8 minutes of simmer. Soft tofu hot through after about 5 gentle minutes, still in large spoonable chunks, not scrambled. Broth spicy, sour from plant kimchi, savory from soy and gochujang. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"spicy-kimchi-broth","name":"spicy kimchi broth","made_in_recipe":true,"store_bought":false,"ingredients":["neutral oil","toasted sesame oil","yellow onion","garlic","fresh ginger","gochugaru","gochujang","plant kimchi","zucchini","vegetable stock","water","soy sauce","sugar","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, 'bbdbf4ee368e5f59cbd96f93fc687895b1c39a9d0d57dd22d7210a976069e457', 'flavorweave-catalog-package', 'catalog/korean-soft-tofu-stew/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_korean-spicy-cod-stew_v1', 'rcp_korean-spicy-cod-stew', 'korean-spicy-cod-stew', 1, 'Korean Maeuntang: Spicy Cod Stew with Radish, Tofu, and Watercress', 'Chunks of cod simmered in a fiery broth of gochugaru, gochujang, garlic, soy sauce, and fish sauce with Korean radish, onion, zucchini, and tofu, finished with watercress, scallions, and sliced jalapeno and served with short-grain rice.', 4, 16, 32, 48, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', '5.5-quart Dutch oven over high to a boil, then a steady simmer; 2-quart saucepan for the rice.', 'Radish translucent and tender; cod opaque and just flaking, 145 F; watercress barely wilted.', '["simmer","steam"]', '[]', 'null', '[{"component_id":"stew","name":"maeuntang","made_in_recipe":true,"store_bought":false,"ingredients":["water","Korean radish","onion","garlic","gochugaru","gochujang","soy sauce","fish sauce","salt","zucchini","firm tofu","cod","watercress","scallions","jalapeno"]},{"component_id":"rice","name":"short-grain rice","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","water"]}]', 'published', 'draft', 'global', NULL, 'd0f400937e3a6991d5550cede1410e2bc5116cc68e0a6a66623cca1043ea6ebe', 'flavorweave-catalog-package', 'catalog/korean-spicy-cod-stew/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_lebanese-arayes_v1', 'rcp_lebanese-arayes', 'lebanese-arayes', 1, 'Lebanese Arayes: Spiced Lamb-Stuffed Pita with Tahini Sauce', 'Pita halves filled with a thin layer of ground lamb mixed with grated onion, parsley, garlic, allspice, cinnamon, cumin, and Aleppo pepper, brushed with olive oil and baked crisp, served with a lemony tahini sauce, sliced cucumber, and radishes.', 4, 22, 20, 42, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Oven 425 F with racks in the upper and lower thirds.', 'Pita crisp and deep golden on both sides; lamb filling 160 F at the center.', '["bake"]', '[]', 'null', '[{"component_id":"arayes","name":"arayes","made_in_recipe":true,"store_bought":false,"ingredients":["ground lamb","yellow onion","parsley","garlic","allspice","cinnamon","cumin","Aleppo pepper","salt","pita","olive oil"]},{"component_id":"tahini","name":"tahini sauce","made_in_recipe":true,"store_bought":false,"ingredients":["tahini","lemon juice","garlic","water","salt"]},{"component_id":"veg","name":"cucumber and radishes","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber","radishes"]}]', 'published', 'draft', 'global', NULL, '58af6b331987d0953e77abf9c8e03f2dcea1357298d121edcaa5f545d9556906', 'flavorweave-catalog-package', 'catalog/lebanese-arayes/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_lebanese-baked-kibbeh_v1', 'rcp_lebanese-baked-kibbeh', 'lebanese-baked-kibbeh', 1, 'Lebanese Baked Kibbeh with Pine Nuts, Yogurt-Cucumber Salad, and Fattoush-Style Greens', 'A tray of kibbeh bil sanieh: a shell of fine bulgur kneaded with ground lamb, onion, and seven-spice layered around a filling of spiced lamb, onion, and toasted pine nuts, scored into diamonds, drizzled with olive oil, and baked until crisp-edged. Served with a garlicky yogurt-cucumber salad and a lemony tomato-cucumber salad.', 4, 12, 102, 114, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium in a 10-inch skillet for the filling. Oven preheated to 400 F for the tray.', 'Top deep golden-brown with crisp edges, layers holding together when cut, 160 F inside.', '["saute","bake"]', '[]', 'null', '[{"component_id":"shell","name":"kibbeh shell","made_in_recipe":true,"store_bought":false,"ingredients":["fine bulgur","ground lamb","onion","seven-spice","salt","water"]},{"component_id":"filling","name":"lamb and pine-nut filling","made_in_recipe":true,"store_bought":false,"ingredients":["ground lamb","onion","pine nuts","seven-spice","olive oil"]},{"component_id":"yogurt-salad","name":"yogurt-cucumber salad","made_in_recipe":true,"store_bought":false,"ingredients":["yogurt","cucumber","garlic","mint"]},{"component_id":"salad","name":"tomato-cucumber salad","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","cucumber","parsley","lemon","olive oil","sumac"]}]', 'published', 'draft', 'global', NULL, '9cec65a14942b5f619ed6195bd4e8483bf1918e632d4d928dee7a66cc133c936', 'flavorweave-catalog-package', 'catalog/lebanese-baked-kibbeh/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_lebanese-samke-harra-bulgur_v1', 'rcp_lebanese-samke-harra-bulgur', 'lebanese-samke-harra-bulgur', 1, 'Lebanese Samke Harra: Spicy Tahini-Baked Cod with Bulgur Pilaf', 'Cod fillets spread with a sizzling garlic, red chile, Aleppo pepper, and cilantro topping, blanketed in lemony tahini sauce, and baked until bubbling and just flaking. Served over a toasty onion and tomato bulgur pilaf.', 4, 15, 34, 49, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Oven preheated to 400 F, middle rack. Medium skillet for the harra topping. Covered low simmer for the bulgur.', 'Tahini sauce bubbling at the edges and lightly golden in spots; cod opaque, flaking, and 145 F in the thickest part. Bulgur tender and separate with no liquid left.', '["bake","saute","simmer"]', '[]', 'null', '[{"component_id":"harra","name":"garlic-chile-cilantro harra","made_in_recipe":true,"store_bought":false,"ingredients":["garlic","red chiles","Aleppo pepper","cumin","cilantro","olive oil"]},{"component_id":"tahini-sauce","name":"lemon tahini sauce","made_in_recipe":true,"store_bought":false,"ingredients":["tahini","lemon","garlic","water","salt"]},{"component_id":"fish","name":"baked cod","made_in_recipe":true,"store_bought":false,"ingredients":["cod","salt"]},{"component_id":"bulgur","name":"onion-tomato bulgur pilaf","made_in_recipe":true,"store_bought":false,"ingredients":["coarse bulgur","onion","tomato paste","water","olive oil"]}]', 'published', 'draft', 'global', NULL, 'e7e4121babf163c590649a2526889