INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_lemon-pea-risotto_v1', 'rcp_lemon-pea-risotto', 'lemon-pea-risotto', 1, 'Lemon Pea Risotto', 'Arborio rice stirred with hot vegetable stock until creamy, finished with peas, lemon, butter, and microbial-rennet Parmesan.', 4, 12, 28, 40, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Stock held at a bare simmer. Risotto pot over medium for shallot and toast, then medium to medium-low while ladling. Finish off heat.', 'Rice al dente with creamy starch suspension. Peas hot and bright. Spreads slowly on a plate. Lemon bright, not bitter from too much pith. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"lemon-parmesan-finish","name":"lemon-Parmesan finish","made_in_recipe":true,"store_bought":false,"ingredients":["unsalted butter","vegetarian Parmesan","lemon zest","lemon juice","black pepper","kosher salt","fresh parsley","frozen peas"]}]', 'published', 'draft', 'global', NULL, 'f56ca409b3ca8384c0e39bc875a7aa41a0c972b7a9091f9339f9dc7e80676a7e', 'flavorweave-catalog-package', 'catalog/lemon-pea-risotto/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_lentil-stuffed-cabbage_v1', 'rcp_lentil-stuffed-cabbage', 'lentil-stuffed-cabbage', 1, 'Lentil-Stuffed Cabbage with Tomato Sauce', 'Cabbage leaves rolled around brown lentils and parcooked rice, baked in a tomato sauce made from crushed tomatoes.', 4, 35, 106, 141, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Stove for the lentils, rice, filling, and sauce. Oven 375 F for the covered bake, then uncovered.', 'Lentils are simmered only until tender with a bite, then finish in the oven. Rolls bake 40 minutes covered and 10 minutes uncovered at 375 F until the center filling is hot and steaming and the leaf edges show browned spots.', '[]', '[]', 'null', '[{"component_id":"lentil-rice-filling","name":"lentil-rice filling","made_in_recipe":true,"store_bought":false,"ingredients":["brown lentils","long-grain white rice","yellow onion","garlic","olive oil","kosher salt","black pepper","sweet paprika","fresh parsley"]},{"component_id":"tomato-sauce","name":"tomato sauce","made_in_recipe":true,"store_bought":false,"ingredients":["crushed tomatoes","yellow onion","garlic","olive oil","water","red wine vinegar","brown sugar","kosher salt","green cabbage"]}]', 'published', 'draft', 'global', NULL, 'dd84c30742df80e54d6790c21118b42301ed5c06fd62dfc4e9cff5fe5b0336ff', 'flavorweave-catalog-package', 'catalog/lentil-stuffed-cabbage/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_linguine-with-clams_v1', 'rcp_linguine-with-clams', 'linguine-with-clams', 1, 'Linguine with Clams', 'Littleneck clams steamed open in garlic and white wine, tossed with linguine, parsley, and lemon. No cheese and no butter.', 4, 15, 18, 33, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'A large pot of boiling water for the pasta. A 12-inch skillet or wide pot over medium for the clams.', 'Pasta tender with a slight bite. Clams open. Any clam that stays shut is discarded. Sauce glossy from the clam liquor and olive oil, not creamy.', '["stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'c0e654c2983e420a18838d4d3f67bf08edc2e529f11a202ee688f88cd430515c', 'flavorweave-catalog-package', 'catalog/linguine-with-clams/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_malaysian-curry-laksa_v1', 'rcp_malaysian-curry-laksa', 'malaysian-curry-laksa', 1, 'Malaysian Curry Laksa with Shrimp', 'A rich, spicy coconut noodle soup: a homemade paste of shallots, lemongrass, ginger, garlic, dried chiles, turmeric, and shrimp paste, sizzled in oil and simmered with coconut milk and stock, then poured over rice vermicelli and shrimp and piled with bean sprouts, cucumber, mint, and lime.', 4, 25, 28, 53, 'involved', 'adventurous', '6ee7bb37273cbc12eff6d5be73cdb6c79a88a65cdfe5ea686de96c0b7a43a78d', 'Medium to cook the paste until the oil separates; medium-low simmer; gentle simmer to poach the shrimp; boil for the noodles.', 'Paste dark and fragrant with oil separating; broth creamy and orange-red; shrimp pink and just opaque (120 to 125 F).', '["saute","simmer","boil"]', '[]', 'null', '[{"component_id":"paste","name":"laksa paste","made_in_recipe":true,"store_bought":false,"ingredients":["shallots","garlic","ginger","lemongrass","dried chiles","turmeric","coriander","shrimp paste","oil"]},{"component_id":"broth","name":"coconut laksa broth with shrimp","made_in_recipe":true,"store_bought":false,"ingredients":["coconut milk","chicken stock","fish sauce","brown sugar","shrimp"]},{"component_id":"noodles","name":"rice vermicelli","made_in_recipe":true,"store_bought":false,"ingredients":["rice vermicelli","water"]},{"component_id":"garnish","name":"fresh garnishes","made_in_recipe":true,"store_bought":false,"ingredients":["bean sprouts","cucumber","mint","limes"]}]', 'published', 'draft', 'global', NULL, '664e134dd4a46fb521e61c76415dabd9835c4618031847d75a0d248f53051ccc', 'flavorweave-catalog-package', 'catalog/malaysian-curry-laksa/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_malian-chicken-maafe_v1', 'rcp_malian-chicken-maafe', 'malian-chicken-maafe', 1, 'Malian Chicken Maafe: Peanut and Tomato Stew with Sweet Potatoes', 'West African groundnut stew: chicken thighs simmered in a rich sauce of peanut butter, tomato paste, onion, garlic, and ginger with a whole Scotch bonnet for gentle heat, sweet potatoes, and carrots. Served over white rice.', 4, 14, 61, 75, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-high in a 5-quart Dutch oven to brown, medium for the aromatics, then a gentle partly covered simmer, stirring so the peanut sauce does not catch. Low covered heat for the rice.', 'Chicken 175 F and tender. Sweet potatoes soft. Sauce thick, glossy, and rust-colored, with a little reddish oil at the surface.', '["sear","simmer"]', '[]', 'null', '[{"component_id":"maafe","name":"peanut stew","made_in_recipe":true,"store_bought":false,"ingredients":["chicken","peanut butter","tomato paste","onion","garlic","ginger","Scotch bonnet","sweet potatoes","carrots","water"]},{"component_id":"rice","name":"white rice","made_in_recipe":true,"store_bought":false,"ingredients":["rice","water"]}]', 'published', 'draft', 'global', NULL, '91d222195fa690103de83379c42d6d4780779803737d6b3393fa61905680e89b', 'flavorweave-catalog-package', 'catalog/malian-chicken-maafe/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_maple-mustard-glazed-salmon_v1', 'rcp_maple-mustard-glazed-salmon', 'maple-mustard-glazed-salmon', 1, 'Maple Mustard Glazed Salmon', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["fish","finfish","dairy-free"]', 'null', '[]', 'retired', 'published', 'global', NULL, '876f49cbba3f2eb3ef8cfbce68775f8c81a0b32445e0eb624f229f6990585b34', 'flavorweave-legacy-catalog-package', 'catalog/maple-mustard-glazed-salmon/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_maple-mustard-glazed-salmon_v2', 'rcp_maple-mustard-glazed-salmon', 'maple-mustard-glazed-salmon', 2, 'Maple Mustard Glazed Salmon', 'Salmon fillets and asparagus brushed with Dijon and maple syrup and roasted until the salmon is opaque at the center.', 4, 10, 15, 25, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Oven 400 F on a sheet pan.', 'Salmon is done when opaque at the center, 12 to 15 minutes at 400 F. That is cooked through, not rare and not a medium-rare center. Asparagus is tender at the same time.', '["oven"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, '003805c8ff4691652cf11494e195a1ea37bf7d40174921823d21f1abaf5adf25', 'flavorweave-legacy-audit-draft', 'catalog/maple-mustard-glazed-salmon/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_maryland-crab-cakes-slaw_v1', 'rcp_maryland-crab-cakes-slaw', 'maryland-crab-cakes-slaw', 1, 'Maryland Crab Cakes with Old Bay Coleslaw and Lemon', 'Jumbo lump crab bound lightly with mayonnaise, egg, Dijon, Old Bay, parsley, and crushed saltines, chilled, then pan-fried until golden and crisp outside and barely held together inside. Served with a tangy Old Bay coleslaw and lemon wedges.', 4, 46, 20, 66, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium in a 12-inch nonstick skillet with a thin layer of oil.', 'Cakes deep golden and crisp on both sides, hot through (165 F at the center).', '["pan-fry"]', '[]', 'null', '[{"component_id":"crab-cakes","name":"crab cakes","made_in_recipe":true,"store_bought":false,"ingredients":["lump crab","mayonnaise","egg","Dijon","Old Bay","parsley","saltines","lemon"]},{"component_id":"slaw","name":"Old Bay coleslaw","made_in_recipe":true,"store_bought":false,"ingredients":["cabbage","carrot","mayonnaise","cider vinegar","sugar","Old Bay"]}]', 'published', 'draft', 'global', NULL, 'f98bd4fd651c9e5d51839eaab0773ea1dea40f6451717a48cc53a443d7aa62dc', 'flavorweave-catalog-package', 'catalog/maryland-crab-cakes-slaw/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_mexican-enfrijoladas_v1', 'rcp_mexican-enfrijoladas', 'mexican-enfrijoladas', 1, 'Enfrijoladas: Corn Tortillas in Smoky Pinto Bean Sauce with Zucchini and Poblano', 'Warm corn tortillas dipped in a silky chipotle pinto bean sauce, folded around sauteed zucchini, corn, and poblano, then blanketed with more sauce and finished with avocado, radish, cilantro, and lime.', 4, 15, 40, 55, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium in a 3-quart saucepan for the bean sauce. Medium-high in a 12-inch skillet for the vegetables. A dry 10-inch skillet over medium to warm the tortillas.', 'Bean sauce smooth and pourable, like heavy cream. Zucchini browned at the edges and tender-crisp. Tortillas hot and pliable so they fold without cracking.', '["saute","simmer"]', '[]', 'null', '[{"component_id":"sauce","name":"chipotle pinto bean sauce","made_in_recipe":true,"store_bought":false,"ingredients":["pinto beans","onion","garlic","chipotle","cumin","water"]},{"component_id":"filling","name":"zucchini, corn, and poblano","made_in_recipe":true,"store_bought":false,"ingredients":["zucchini","corn","poblano"]},{"component_id":"tortillas","name":"corn tortillas","made_in_recipe":false,"store_bought":true,"ingredients":["corn tortillas"]},{"component_id":"garnish","name":"garnishes","made_in_recipe":true,"store_bought":false,"ingredients":["avocado","radishes","cilantro","lime"]}]', 'published', 'draft', 'global', NULL, '6d55a110f52815fb309e17aec7b4ea481c990c84a0421908fdf6cd5a78bd5c3f', 'flavorweave-catalog-package', 'catalog/mexican-enfrijoladas/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_mexican-rajas-con-crema-tacos_v1', 'rcp_mexican-rajas-con-crema-tacos', 'mexican-rajas-con-crema-tacos', 1, 'Mexican Rajas con Crema Tacos with Corn and Queso Fresco', 'Blistered poblano strips cooked with onion, garlic, and corn kernels in Mexican crema with oregano, spooned into warm corn tortillas and finished with crumbled queso fresco, cilantro, and lime.', 4, 24, 33, 57, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Broiler on high with the rack 4 inches below for the poblanos; 12-inch skillet over medium for the rajas; 10-inch skillet over medium-high for the tortillas.', 'Poblano skins blackened and blistered all over; onion soft and golden at the edges; crema simmered to a light coating sauce.', '["broil","saute"]', '[]', 'null', '[{"component_id":"rajas","name":"rajas con crema","made_in_recipe":true,"store_bought":false,"ingredients":["poblano peppers","neutral oil","white onion","garlic","corn kernels","Mexican crema","dried oregano","salt"]},{"component_id":"tortillas","name":"corn tortillas","made_in_recipe":false,"store_bought":true,"ingredients":["corn tortillas"]},{"component_id":"toppings","name":"toppings","made_in_recipe":true,"store_bought":false,"ingredients":["queso fresco","cilantro","lime"]}]', 'published', 'draft', 'global', NULL, 'dfda3d0eca72174a0c9d14c6d39c09ed515d16ae8f369853999bc8e4ffe51a7f', 'flavorweave-catalog-package', 'catalog/mexican-rajas-con-crema-tacos/v1.json', '2026-10-04T00:00:00.000Z');
