INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_miso-mushroom-ramen_v1', 'rcp_miso-mushroom-ramen', 'miso-mushroom-ramen', 1, 'Miso Mushroom Ramen', 'Springy ramen noodles in a dried-shiitake broth enriched with white miso, tahini, garlic, and ginger, topped with soy-seared shiitake, tender baby bok choy, sweet corn, nori, scallions, and sesame. Fully plant-based: no egg, no bonito, no pork or chicken broth, no butter.', 4, 12, 32, 44, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high sear, then simmer; broth held below a boil after the miso goes in.', 'Mushrooms browned with crisp edges. Bok choy stems crisp-tender and bright. Noodles springy, not soft. Broth opaque, savory, and creamy-bodied from miso and tahini, not boiled after seasoning. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"shiitake-miso-broth","name":"shiitake miso-tahini broth","made_in_recipe":true,"store_bought":false,"ingredients":["dried shiitake","water","garlic","ginger","scallion whites","toasted sesame oil","white miso","tahini","soy sauce","sweet corn"]},{"component_id":"soy-seared-shiitake","name":"soy-seared shiitake topping","made_in_recipe":true,"store_bought":false,"ingredients":["fresh shiitake","neutral oil","soy sauce"]},{"component_id":"ramen-noodles-cooked","name":"cooked egg-free ramen noodles","made_in_recipe":true,"store_bought":false,"ingredients":["egg-free wheat ramen noodles"]}]', 'published', 'draft', 'global', NULL, 'b6f070b8f0faa37adfea7f3e0c335d653c805f101284d2530368d4312af944a6', 'flavorweave-catalog-package', 'catalog/miso-mushroom-ramen/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_moroccan-chermoula-fish-tagine_v1', 'rcp_moroccan-chermoula-fish-tagine', 'moroccan-chermoula-fish-tagine', 1, 'Moroccan Chermoula Fish Tagine with Potatoes, Peppers, and Olives', 'Cod marinated in chermoula (cilantro, parsley, garlic, cumin, paprika, and lemon) and braised on a bed of thin-sliced potatoes, red peppers, and tomatoes with green olives and preserved lemon. Served with crusty bread for the juices.', 4, 15, 37, 52, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high to bring the vegetables to a simmer, then covered medium-low in a 12-inch skillet with a lid (or a stovetop tagine).', 'Potatoes tender all the way through when pierced. Fish opaque, flaking, and 145 F. Juices reduced and fragrant.', '["braise","simmer"]', '[]', 'null', '[{"component_id":"chermoula","name":"chermoula","made_in_recipe":true,"store_bought":false,"ingredients":["cilantro","parsley","garlic","cumin","paprika","lemon","olive oil"]},{"component_id":"tagine","name":"potato-pepper braise with fish","made_in_recipe":true,"store_bought":false,"ingredients":["cod","potatoes","red pepper","tomatoes","olives","preserved lemon"]},{"component_id":"bread","name":"crusty bread","made_in_recipe":false,"store_bought":true,"ingredients":["crusty bread"]}]', 'published', 'draft', 'global', NULL, '12c40b944f74e5f16ac2cbfc95d0b358cbeccb929befb58b46d40df61cc113f6', 'flavorweave-catalog-package', 'catalog/moroccan-chermoula-fish-tagine/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_moroccan-chicken-preserved-lemon-tagine_v1', 'rcp_moroccan-chicken-preserved-lemon-tagine', 'moroccan-chicken-preserved-lemon-tagine', 1, 'Moroccan Chicken Tagine with Preserved Lemon, Green Olives, and Couscous', 'Bone-in chicken thighs braised with grated onion, garlic, ginger, turmeric, and saffron in a covered Dutch oven until tender, finished with preserved lemon, green olives, cilantro, and parsley, served over fluffed couscous.', 4, 12, 69, 81, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', '5.5-quart Dutch oven over medium, then low and covered; 2-quart saucepan for the couscous.', 'Chicken 175 F at the bone and pulling from it; onion melted into a thick golden sauce.', '["sear","braise","steep"]', '[]', 'null', '[{"component_id":"tagine","name":"chicken tagine","made_in_recipe":true,"store_bought":false,"ingredients":["bone-in chicken thighs","salt","olive oil","yellow onions","garlic","ginger","turmeric","saffron","water","preserved lemon","green olives","cilantro","parsley"]},{"component_id":"couscous","name":"couscous","made_in_recipe":true,"store_bought":false,"ingredients":["couscous","water","olive oil","salt"]}]', 'published', 'draft', 'global', NULL, '5b1127bf62d73c7c7457d8f8cb6147c2c669c3b6946bdd1ac44fd1a7119f4f1b', 'flavorweave-catalog-package', 'catalog/moroccan-chicken-preserved-lemon-tagine/v1.json', '2026-10-04T00:00:00.000Z');
