INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_moroccan-chickpea-skillet_v2', 'rcp_moroccan-chickpea-skillet', 'moroccan-chickpea-skillet', 2, 'Moroccan Chickpea Skillet', 'Chickpeas with ras el hanout, preserved-lemon rind, and spinach, served over couscous.', 4, 10, 15, 25, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', 'mild', 'Chickpeas glossy, skillet not soupy. Spinach just wilted. Couscous tender and separate, not mush.', '["stovetop"]', '["plant","dairy-free"]', '{"couscous":"This version uses wheat couscous. A gluten-free stand-in would change the allergen list and is not this version.","preserved lemon":"Rind only. Do not chop in the salty pulp, and do not swap in fresh lemon wedges."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, '4aec4970775f316e4a60cf47bbdfd6b49c182a1b5cc0199363d9482bd920814d', 'flavorweave-legacy-catalog-package', 'catalog/moroccan-chickpea-skillet/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_moroccan-seven-vegetable-couscous_v1', 'rcp_moroccan-seven-vegetable-couscous', 'moroccan-seven-vegetable-couscous', 1, 'Moroccan Seven-Vegetable Couscous', 'Fluffy couscous crowned with a fragrant ras el hanout broth of carrots, turnips, butternut squash, cabbage, zucchini, tomato, and onion, simmered until tender with ginger, turmeric, cinnamon, and plump raisins. Served with harissa for heat.', 4, 25, 48, 73, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium sauté; medium-low simmer; couscous steamed off the heat.', 'Carrots and turnips tender; squash soft but holding its shape; zucchini just tender; couscous fluffy and separate.', '["saute","simmer","steam"]', '[]', 'null', '[{"component_id":"broth","name":"seven-vegetable broth","made_in_recipe":true,"store_bought":false,"ingredients":["onion","carrots","turnips","butternut squash","cabbage","zucchini","tomatoes","ras el hanout","ginger","turmeric","cinnamon","raisins","cilantro","water","oil"]},{"component_id":"couscous","name":"steamed couscous","made_in_recipe":true,"store_bought":false,"ingredients":["couscous","water","oil","salt"]},{"component_id":"harissa","name":"harissa","made_in_recipe":false,"store_bought":true,"ingredients":["harissa paste"]}]', 'published', 'draft', 'global', NULL, '2a912aad99eb72ab0638189c144d1e89ca01ace84b6cf0d4b081563a3f663cfc', 'flavorweave-catalog-package', 'catalog/moroccan-seven-vegetable-couscous/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_mushroom-hominy-pozole-rojo_v1', 'rcp_mushroom-hominy-pozole-rojo', 'mushroom-hominy-pozole-rojo', 1, 'Mushroom and Hominy Pozole Rojo', 'A brick-red pozole of toasted guajillo and ancho chile broth with deeply browned cremini mushrooms and plump hominy, finished at the table with crunchy cabbage, radish, white onion, oregano, lime, and corn tostadas. Vegetable broth; no cheese, no crema.', 4, 15, 48, 63, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium for toasting chiles; medium-high for browning mushrooms; medium for onion and frying the puree; high to boil, then a steady simmer. No oven.', 'Mushrooms deeply browned at the edges. Chile puree darkened to brick red before the broth goes in. Hominy plump and tender; broth brick red, rounded, and not bitter. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"guajillo-ancho-puree","name":"toasted guajillo-ancho chile puree","made_in_recipe":true,"store_bought":false,"ingredients":["guajillo chiles","ancho chiles","soaking water","garlic","dried Mexican oregano","ground cumin","kosher salt"]},{"component_id":"mushroom-hominy-pozole","name":"mushroom and hominy pozole broth","made_in_recipe":true,"store_bought":false,"ingredients":["browned cremini mushrooms","white onion","garlic","chile puree","hominy","vegetable broth","bay leaves"]},{"component_id":"pozole-garnish","name":"crunchy table garnish","made_in_recipe":true,"store_bought":false,"ingredients":["green cabbage","radishes","raw white onion","dried Mexican oregano","limes"]},{"component_id":"corn-tostadas","name":"corn tostadas","made_in_recipe":false,"store_bought":true,"ingredients":["corn tostadas"]}]', 'published', 'draft', 'global', NULL, 'c6844f3c5ba3b77ec2ea9df7dcc562d7a778c2ed421d3bc9601286f4ee33d37d', 'flavorweave-catalog-package', 'catalog/mushroom-hominy-pozole-rojo/v1.json', '2026-10-04T00:00:00.000Z');
