INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_mushroom-walnut-bolognese_v2', 'rcp_mushroom-walnut-bolognese', 'mushroom-walnut-bolognese', 2, 'Mushroom Walnut Bolognese', NULL, 4, 15, 30, 45, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', NULL, NULL, '["skillet"]', '["plant","dairy-free"]', 'null', '[]', 'published', 'draft', 'global', NULL, 'a385012ed7e626f71651c3c90df7741c63adddd636c568dcdce73c2dd1c2afca', 'flavorweave-legacy-catalog-package', 'catalog/mushroom-walnut-bolognese/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_nepali-aloo-tama_v1', 'rcp_nepali-aloo-tama', 'nepali-aloo-tama', 1, 'Nepali Aloo Tama: Potato, Bamboo Shoot, and Black-Eyed Pea Curry with Rice', 'A tangy, brothy Nepali curry of potatoes, bamboo shoots, and black-eyed peas simmered with tomatoes, ginger, garlic, turmeric, and fenugreek seeds tempered in oil until fragrant. Served over basmati rice with cilantro.', 4, 14, 41, 55, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium in a 5-quart Dutch oven for the tempering and masala, then a steady simmer. Low covered heat for the rice.', 'Fenugreek seeds a shade darker, not black. Potatoes tender and starting to break at the edges, thickening the broth slightly. Bamboo shoots tender. Broth tangy and spoonable.', '["saute","simmer"]', '[]', 'null', '[{"component_id":"tama","name":"aloo tama","made_in_recipe":true,"store_bought":false,"ingredients":["potatoes","bamboo shoots","black-eyed peas","tomatoes","onion","ginger","garlic","spices","water"]},{"component_id":"rice","name":"basmati rice","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '4f0dc838c60d84b161b80fcfc956ca2cfea86973610f3ee281a1039398d5eb20', 'flavorweave-catalog-package', 'catalog/nepali-aloo-tama/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_new-england-clam-chowder_v1', 'rcp_new-england-clam-chowder', 'new-england-clam-chowder', 1, 'New England Clam Chowder with Bacon and Oyster Crackers', 'A creamy, comforting chowder of tender clams, Yukon Gold potatoes, onion, and celery in a thyme-scented milk and cream base built on rendered bacon and a light roux, finished with chives and served with oyster crackers.', 4, 12, 37, 49, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium to render the bacon and soften the vegetables; medium-low simmer; low once the dairy is in (do not boil).', 'Potatoes tender; chowder lightly thickened and steaming (do not boil after adding the dairy).', '["saute","simmer"]', '[]', 'null', '[{"component_id":"chowder","name":"clam chowder","made_in_recipe":true,"store_bought":false,"ingredients":["bacon","butter","onion","celery","flour","clam juice","potatoes","thyme","bay leaf","milk","heavy cream","clams","salt","pepper"]},{"component_id":"crackers","name":"oyster crackers","made_in_recipe":false,"store_bought":true,"ingredients":["oyster crackers"]}]', 'published', 'draft', 'global', NULL, '80d4222ca0ae64e67024abe1531b78ddd8cdbbf13e1f16f4a59db2868203efad', 'flavorweave-catalog-package', 'catalog/new-england-clam-chowder/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_new-mexican-carne-adovada_v1', 'rcp_new-mexican-carne-adovada', 'new-mexican-carne-adovada', 1, 'New Mexican Carne Adovada with Warm Flour Tortillas', 'Cubes of pork shoulder slowly braised in the oven in a brick-red sauce of dried New Mexico red chiles, garlic, oregano, cumin, and a splash of vinegar until spoon-tender. Served with warm flour tortillas, shredded cabbage, and lime.', 4, 15, 184, 199, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Oven preheated to 325 F for a covered braise in a 5-quart Dutch oven. Medium on the stovetop to soak the chiles.', 'Pork falls apart under a spoon. Sauce thick, glossy, and brick-red, clinging to the meat.', '["braise","simmer"]', '[]', 'null', '[{"component_id":"adovada","name":"red chile pork","made_in_recipe":true,"store_bought":false,"ingredients":["pork shoulder","dried New Mexico chiles","garlic","oregano","cumin","vinegar","water"]},{"component_id":"tortillas","name":"flour tortillas","made_in_recipe":false,"store_bought":true,"ingredients":["flour tortillas"]},{"component_id":"garnish","name":"cabbage and lime","made_in_recipe":true,"store_bought":false,"ingredients":["cabbage","lime","cilantro"]}]', 'published', 'draft', 'global', NULL, '25546760cc66ef3dcc7e4e808cee5e62afa050c18c9f156b7f9d9441e511d239', 'flavorweave-catalog-package', 'catalog/new-mexican-carne-adovada/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_nigerian-beef-suya-skewers_v1', 'rcp_nigerian-beef-suya-skewers', 'nigerian-beef-suya-skewers', 1, 'Nigerian Beef Suya Skewers with Tomato-Onion Salad and Rice', 'Thin strips of beef coated in yaji, a smoky, spicy ground-peanut spice blend with ginger, garlic, paprika, and cayenne, grilled hot on skewers and served with sliced tomato, red onion, cabbage, lime, and steamed jasmine rice.', 4, 20, 36, 56, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'High direct grill heat (or a grill pan on high); low simmer for the rice.', 'Beef charred at the edges and cooked to at least medium (about 140 F in thicker pieces). Rice tender with no liquid left.', '["grill","simmer"]', '[]', 'null', '[{"component_id":"yaji","name":"yaji suya spice","made_in_recipe":true,"store_bought":false,"ingredients":["roasted peanuts","ground ginger","garlic powder","onion powder","smoked paprika","cayenne","salt"]},{"component_id":"suya","name":"grilled beef suya","made_in_recipe":true,"store_bought":false,"ingredients":["beef sirloin","oil","yaji"]},{"component_id":"salad","name":"tomato, onion, and cabbage","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","red onion","cabbage","lime"]},{"component_id":"rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '8f014fbf532d593e3df7ae75a419e0bcfa8cf4b6b7980058f8a1a59b177ccb8c', 'flavorweave-catalog-package', 'catalog/nigerian-beef-suya-skewers/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_nigerian-jollof-rice-boiled-eggs_v1', 'rcp_nigerian-jollof-rice-boiled-eggs', 'nigerian-jollof-rice-boiled-eggs', 1, 'Nigerian Jollof Rice with Boiled Eggs', 'Parboiled long-grain rice steamed in a reduced red base of blended red bell peppers, plum tomatoes, onion, and scotch bonnet with tomato paste, curry powder, thyme, bay leaves, and vegetable broth until each grain is tinted red and separate, served with halved boiled eggs.', 4, 10, 72, 82, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '5.5-quart Dutch oven over medium to reduce the base, then covered over low to steam the rice; 3-quart saucepan for the eggs.', 'Base reduced by about half with oil pooling at the edges. Rice tender, separate, and evenly orange with no liquid left; eggs firm-cooked.', '["simmer","steam","boil"]', '[]', 'null', '[{"component_id":"jollof","name":"jollof rice","made_in_recipe":true,"store_bought":false,"ingredients":["red bell peppers","plum tomatoes","onions","scotch bonnet","neutral oil","tomato paste","curry powder","dried thyme","bay leaves","salt","parboiled rice","vegetable broth"]},{"component_id":"eggs","name":"boiled eggs","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","water"]}]', 'published', 'draft', 'global', NULL, '6f0c6324cf6d7e6e215ddfbea9df0db05d16bd4a35d0d758250b90cd3dba0001', 'flavorweave-catalog-package', 'catalog/nigerian-jollof-rice-boiled-eggs/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_orecchiette-sausage-broccoli-rabe_v1', 'rcp_orecchiette-sausage-broccoli-rabe', 'orecchiette-sausage-broccoli-rabe', 1, 'Orecchiette with Italian Sausage, Broccoli Rabe, Garlic, and Pecorino', 'Dried orecchiette tossed with crumbled browned Italian sausage, blanched broccoli rabe cooked down with garlic, chile flakes, and olive oil, loosened with starchy cooking liquid and finished with grated Pecorino Romano and lemon zest.', 4, 10, 32, 42, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '6-quart pot over high; 12-inch skillet over medium-high.', 'Sausage browned with no pink; rabe tender with bite; pasta al dente and glossy with a light emulsified sauce.', '["boil","blanch","saute"]', '[]', 'null', '[{"component_id":"pasta","name":"orecchiette with sausage and rabe","made_in_recipe":true,"store_bought":false,"ingredients":["orecchiette","water","salt","broccoli rabe","Italian sausage","olive oil","garlic","red chile flakes","Pecorino Romano","lemon"]}]', 'published', 'draft', 'global', NULL, 'e032c5b4b1d26869ed3bef2873bb110154d039fca0c23ff5ab07c8f92148459b', 'flavorweave-catalog-package', 'catalog/orecchiette-sausage-broccoli-rabe/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_oven-bbq-baby-back-ribs_v1', 'rcp_oven-bbq-baby-back-ribs', 'oven-bbq-baby-back-ribs', 1, 'Oven-Barbecued Baby Back Ribs with Corn and Quick Pickles', 'Baby back ribs rubbed with brown sugar, smoked paprika, and chili powder, baked low and slow in foil until tender, then lacquered with a homemade tangy molasses barbecue sauce and broiled until sticky and caramelized. Served with boiled sweet corn and crisp quick-pickled cucumbers and red onion.', 4, 15, 168, 183, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Oven preheated to 275 F for the slow bake; broiler on high for the finish. Medium-low simmer for the sauce. Rolling boil for the corn.', 'Meat pulls back from the bone ends about 1/2 inch and a rack bends deeply when lifted from the center (about 195 F). Sauce sticky and caramelized at the edges.', '["bake","broil","simmer","boil"]', '[]', 'null', '[{"component_id":"ribs","name":"oven-barbecued ribs","made_in_recipe":true,"store_bought":false,"ingredients":["baby back ribs","brown sugar","smoked paprika","chili powder","garlic powder","onion powder","salt","pepper"]},{"component_id":"sauce","name":"molasses barbecue sauce","made_in_recipe":true,"store_bought":false,"ingredients":["ketchup","cider vinegar","molasses","Dijon","brown sugar","smoked paprika"]},{"component_id":"corn","name":"boiled corn","made_in_recipe":true,"store_bought":false,"ingredients":["corn","water","salt"]},{"component_id":"pickles","name":"quick-pickled cucumbers","made_in_recipe":true,"store_bought":false,"ingredients":["cucumbers","red onion","cider vinegar","sugar","salt"]}]', 'published', 'draft', 'global', NULL, '238decc6c1c74996e8e987059f737180e70164f4b9d5cc3710b123e88b170fbf', 'flavorweave-catalog-package', 'catalog/oven-bbq-baby-back-ribs/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_pakistani-chicken-karahi_v1', 'rcp_pakistani-chicken-karahi', 'pakistani-chicken-karahi', 1, 'Pakistani Chicken Karahi with Warm Naan', 'Bone-in chicken seared hard in a wok-shaped karahi or wide skillet, then cooked down with fresh tomatoes, plenty of ginger, garlic, and green chiles until the sauce clings and the oil separates. Finished with julienned ginger and cilantro and served with warm naan.', 4, 15, 40, 55, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'High in a 12-inch wok or deep skillet to sear, then medium-high to cook down the tomatoes, then medium-low covered.', 'Chicken 175 F at the bone. Tomatoes completely broken down; sauce thick and clinging, with oil separating at the edges.', '["sear","simmer"]', '[]', 'null', '[{"component_id":"karahi","name":"chicken karahi","made_in_recipe":true,"store_bought":false,"ingredients":["chicken","tomatoes","ginger","garlic","green chiles","spices","oil"]},{"component_id":"naan","name":"warm naan","made_in_recipe":false,"store_bought":true,"ingredients":["naan"]}]', 'published', 'draft', 'global', NULL, 'd698ef17d174a514055fc14f3e63b339f08280e765c591180963760c33753a81', 'flavorweave-catalog-package', 'catalog/pakistani-chicken-karahi/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_pakistani-lamb-keema-peas_v1', 'rcp_pakistani-lamb-keema-peas', 'pakistani-lamb-keema-peas', 1, 'Pakistani Lamb Keema Matar with Green Peas and Warm Chapatis', 'Ground lamb cooked down with browned onions, garlic, ginger, green chiles, and tomatoes in cumin seeds, coriander, Kashmiri chile, turmeric, and yogurt until dry and fragrant, folded with green peas and garam masala, finished with cilantro, and scooped up with warm chapatis.', 4, 12, 52, 64, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '12-inch deep skillet over medium-high, then medium; 10-inch dry skillet for the chapatis.', 'Lamb browned and no pink remains; masala thick and the oil separating at the edges; peas bright and tender.', '["saute","simmer","toast"]', '[]', 'null', '[{"component_id":"keema","name":"lamb keema with peas","made_in_recipe":true,"store_bought":false,"ingredients":["ground lamb","neutral oil","cumin seeds","yellow onions","garlic","ginger","green chiles","tomatoes","ground coriander","Kashmiri chile powder","turmeric","salt","plain yogurt","peas","garam masala","cilantro"]},{"component_id":"bread","name":"chapatis","made_in_recipe":true,"store_bought":false,"ingredients":["chapatis"]}]', 'published', 'draft', 'global', NULL, 'ef924c9485917a8d1305aa7ee4d958f7cb847fe4f6db7946c03bb06bd72e7cb6', 'flavorweave-catalog-package', 'catalog/pakistani-lamb-keema-peas/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_palestinian-musakhan-chicken_v1', 'rcp_palestinian-musakhan-chicken', 'palestinian-musakhan-chicken', 1, 'Palestinian Musakhan: Sumac Chicken and Onions on Flatbread', 'Boneless chicken thighs rubbed with sumac, allspice, and cardamom and roasted, then piled with a heap of onions slowly cooked in olive oil and sumac onto taboon-style flatbreads and baked until the edges crisp, finished with parsley and lemon.', 4, 14, 42, 56, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Oven 425 F; 12-inch skillet over medium-low for the onions.', 'Chicken 175 F with browned edges; onions very soft, sweet, and deep purple-red with sumac; flatbread edges crisp and the centers soaked with oil.', '["roast","saute","bake"]', '[]', 'null', '[{"component_id":"chicken","name":"spiced chicken","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","sumac","allspice","cardamom","salt","olive oil"]},{"component_id":"onions","name":"sumac onions","made_in_recipe":true,"store_bought":false,"ingredients":["yellow onions","olive oil","sumac","salt"]},{"component_id":"bread","name":"flatbreads","made_in_recipe":true,"store_bought":false,"ingredients":["flatbreads","parsley","lemon"]}]', 'published', 'draft', 'global', NULL, 'ba0f2386d1319e76b19f03b253f5180f0b075d0ef77baffbb21b7c25c0b2b3bc', 'flavorweave-catalog-package', 'catalog/palestinian-musakhan-chicken/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_pan-fried-pork-dumplings_v1', 'rcp_pan-fried-pork-dumplings', 'pan-fried-pork-dumplings', 1, 'Pan-Fried Pork and Cabbage Dumplings', 'Ground pork and napa cabbage dumplings, pleated by hand and pan-fried to a crisp golden bottom with a short covered steam, served with a simple soy-vinegar dipping sauce.', 4, 39, 24, 63, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium-high to preheat the oil and fry the bottoms; medium for the covered steam; medium uncovered to evaporate water and re-crisp. Stovetop only. No deep-fry, no boil, no oven.', 'Bottoms deep golden and crisp; tops tender and translucent, not gummy-white. Filling firm, juicy, no pink, 160 F if checked. Water fully evaporated before plating so bottoms stay crisp. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"pork-cabbage-filling","name":"pork and napa cabbage filling","made_in_recipe":true,"store_bought":false,"ingredients":["ground pork","napa cabbage","scallions","fresh ginger","garlic","soy sauce","toasted sesame oil","granulated sugar","ground white pepper","kosher salt","cornstarch","water"]},{"component_id":"dumpling-wrappers","name":"round dumpling wrappers","made_in_recipe":false,"store_bought":true,"contract":"Store-bought wheat-and-water round dumpling wrappers; egg-free (no yellow wonton/egg-roll wrappers).","ingredients":["round dumpling wrappers"]},{"component_id":"soy-vinegar-dip","name":"soy-vinegar dipping sauce","made_in_recipe":true,"store_bought":false,"ingredients":["soy sauce","unseasoned rice vinegar","toasted sesame oil","scallion green"]}]', 'published', 'draft', 'global', NULL, 'b48621c12d7f80ab057e171b49bf15a15ba7b6e1b11c54235b3c05671134d101', 'flavorweave-catalog-package', 'catalog/pan-fried-pork-dumplings/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_pan-fried-trout-lemon-capers_v1', 'rcp_pan-fried-trout-lemon-capers', 'pan-fried-trout-lemon-capers', 1, 'Pan-Fried Trout with Lemon and Capers', 'Trout fillets pan-fried in olive oil, with a lemon and caper pan sauce made with vegetable broth. No butter.', 4, 10, 14, 24, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high skillet for the trout, then medium for the sauce.', 'Trout golden on the floured side, opaque, and 145 F. Sauce tart and spoonable, not a thick gravy.', '["pan-fry"]', '[]', 'null', '[{"component_id":"sauce","name":"lemon caper pan sauce","made_in_recipe":true,"store_bought":false,"ingredients":["lemon","capers","garlic","vegetable broth","parsley"]}]', 'published', 'draft', 'global', NULL, '431791d4f842f3a31d5b6b5a568fb77a4df1126f566a68b8118e9d7cb6c1b209', 'flavorweave-catalog-package', 'catalog/pan-fried-trout-lemon-capers/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_pan-seared-halibut-lemon-butter-corn_v1', 'rcp_pan-seared-halibut-lemon-butter-corn', 'pan-seared-halibut-lemon-butter-corn', 1, 'Pan-Seared Halibut with Lemon Butter and Sweet Corn Saute', 'A 25-minute summer plate: thick halibut fillets seared golden and basted in garlicky lemon butter, served over a quick saute of sweet corn, cherry tomatoes, and scallions with torn basil.', 4, 8, 17, 25, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Medium-high for the corn; medium-high to sear the fish, then medium to baste.', 'Halibut golden on one side and just opaque, flaking at the center (130 to 135 F). Corn bright and lightly browned.', '["sear","saute"]', '[]', 'null', '[{"component_id":"fish","name":"halibut with lemon butter","made_in_recipe":true,"store_bought":false,"ingredients":["halibut","oil","butter","garlic","lemon","salt","pepper"]},{"component_id":"corn","name":"corn saute","made_in_recipe":true,"store_bought":false,"ingredients":["corn","cherry tomatoes","scallions","basil","olive oil","salt"]}]', 'published', 'draft', 'global', NULL, '7f93cc06e910fc69ed385ad4b0dfb0ae3cf5b62683195b7a64d0b072c4d7bb10', 'flavorweave-catalog-package', 'catalog/pan-seared-halibut-lemon-butter-corn/v1.json', '2026-10-04T00:00:00.000Z');
