INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_penne-alla-vodka_v1', 'rcp_penne-alla-vodka', 'penne-alla-vodka', 1, 'Penne alla Vodka with Basil', 'Penne tossed in a rosy sauce of shallot, garlic, and red pepper flakes cooked in butter and olive oil with tomato paste and crushed tomatoes, simmered with vodka, finished with heavy cream and a vegetarian Parmesan-style cheese, and topped with basil.', 4, 6, 32, 38, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '8-quart pot at a rolling boil for the pasta; 12-inch skillet over medium for the sauce.', 'Penne al dente; sauce an even blush pink that coats the pasta and clings inside the tubes.', '["boil","simmer"]', '[]', 'null', '[{"component_id":"pasta","name":"penne","made_in_recipe":true,"store_bought":false,"ingredients":["penne","water","salt"]},{"component_id":"sauce","name":"vodka sauce","made_in_recipe":true,"store_bought":false,"ingredients":["extra-virgin olive oil","butter","shallot","garlic","red pepper flakes","tomato paste","crushed tomatoes","vodka","heavy cream","Parmesan-style cheese","basil","salt"]}]', 'published', 'draft', 'global', NULL, '33eb3fc71e0e0ee3299686d7b9b00005ed92dc33802f40f11e87fa2fc7af522f', 'flavorweave-catalog-package', 'catalog/penne-alla-vodka/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_persian-ash-reshteh_v1', 'rcp_persian-ash-reshteh', 'persian-ash-reshteh', 1, 'Persian Ash Reshteh: Herb, Bean, and Noodle Soup with Kashk and Mint Oil', 'A thick soup of green lentils, chickpeas, and kidney beans simmered in vegetable broth with turmeric and heaps of parsley, cilantro, dill, spinach, and scallions, thickened with broken linguine, and topped with tangy kashk, deep-brown onions, garlic, and dried mint bloomed in oil.', 4, 20, 55, 75, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', '6-quart Dutch oven over high to a boil, then a steady simmer; 10-inch skillet over medium for the onion and mint toppings.', 'Lentils soft, herbs dark green and melted into the soup, noodles tender, soup thick enough to coat a ladle; onions deep brown.', '["simmer","saute"]', '[]', 'null', '[{"component_id":"ash","name":"ash reshteh","made_in_recipe":true,"store_bought":false,"ingredients":["green lentils","vegetable broth","water","turmeric","salt","chickpeas","kidney beans","parsley","cilantro","dill","spinach","scallions","linguine","black pepper"]},{"component_id":"toppings","name":"onion, garlic, and mint oil","made_in_recipe":true,"store_bought":false,"ingredients":["neutral oil","yellow onions","garlic","dried mint"]},{"component_id":"kashk","name":"kashk","made_in_recipe":false,"store_bought":true,"ingredients":["kashk"]}]', 'published', 'draft', 'global', NULL, 'db0b42ebd3cefad83c3031bc1445de5da68d319ebeec04379db1ba88d38cb4ef', 'flavorweave-catalog-package', 'catalog/persian-ash-reshteh/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_persian-ghormeh-sabzi_v1', 'rcp_persian-ghormeh-sabzi', 'persian-ghormeh-sabzi', 1, 'Persian Ghormeh Sabzi: Herb and Lamb Stew with Dried Lime', 'Iran''s beloved herb stew: lamb shoulder braised with a mountain of slow-cooked parsley, cilantro, scallions, and fenugreek, kidney beans, turmeric, and whole dried limes that lend a deep, sour, almost smoky tang. Served with fluffy steamed basmati.', 4, 25, 108, 133, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium-high to brown the lamb; low covered simmer for the braise; medium-low to cook down the herbs. Boil then low steam for the rice.', 'Lamb fork-tender; herbs cooked down to a very dark green; sauce thick with a layer of glossy oil on top. Rice long, separate, and fluffy.', '["saute","braise","boil","steam"]', '[]', 'null', '[{"component_id":"stew","name":"lamb and herb stew","made_in_recipe":true,"store_bought":false,"ingredients":["lamb shoulder","onion","turmeric","parsley","cilantro","scallions","fenugreek","dried limes","kidney beans","lemon","water","oil"]},{"component_id":"rice","name":"steamed basmati","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","water","salt","oil"]}]', 'published', 'draft', 'global', NULL, 'a8216f25fa35b3b375a3ca08c6b868c8e793e1f7bee646e791ee9b6851d5e91f', 'flavorweave-catalog-package', 'catalog/persian-ghormeh-sabzi/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_persian-lamb-koobideh-saffron-rice_v1', 'rcp_persian-lamb-koobideh-saffron-rice', 'persian-lamb-koobideh-saffron-rice', 1, 'Persian Lamb Koobideh Kebabs with Saffron Rice and Grilled Tomatoes', 'Ground lamb kneaded with grated onion, turmeric, and black pepper, shaped onto flat skewers, and grilled until juicy and charred. Served on fluffy saffron basmati with a pat of butter, blistered grilled tomatoes, sumac, raw onion, and herbs.', 4, 18, 49, 67, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Grill preheated on high for 10 minutes, about 500 F at the grate. A 6-quart pot at a rolling boil to par-cook the rice, then low covered heat to steam it.', 'Kebabs charred at the ridges and 160 F inside. Tomatoes blistered and softened. Rice grains long, separate, and tender.', '["grill","boil","steam"]', '[]', 'null', '[{"component_id":"koobideh","name":"lamb koobideh","made_in_recipe":true,"store_bought":false,"ingredients":["ground lamb","onion","turmeric","black pepper","salt"]},{"component_id":"rice","name":"saffron rice","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","saffron","butter","water","salt"]},{"component_id":"sides","name":"grilled tomatoes, sumac, onion, herbs","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","sumac","red onion","mint","basil"]}]', 'published', 'draft', 'global', NULL, '3503ec70d13ba1e6630e71701b363c0f8f6f4d401efd4a6b6512efef111eced9', 'flavorweave-catalog-package', 'catalog/persian-lamb-koobideh-saffron-rice/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_persian-sabzi-polo-salmon_v1', 'rcp_persian-sabzi-polo-salmon', 'persian-sabzi-polo-salmon', 1, 'Persian Sabzi Polo with Seared Salmon: Herbed Dill Rice and Lemon', 'Basmati rice parboiled, then steamed in layers with a big handful of dill, parsley, cilantro, chives, and garlic until fluffy and green-flecked, served with skin-on salmon seared until the skin is crisp and finished with lemon.', 4, 10, 41, 51, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '4-quart pot at a full boil to parboil, then medium and low with a towel-wrapped lid to steam. 12-inch skillet over medium-high for the salmon.', 'Rice grains long, separate, and tender; the herbs bright green. Salmon skin crisp and the flesh opaque and flaking at 145 F.', '["boil","steam","sear"]', '[]', 'null', '[{"component_id":"sabzi-polo","name":"herbed steamed rice","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","water","salt","dill","parsley","cilantro","chives","garlic","neutral oil"]},{"component_id":"salmon","name":"seared salmon","made_in_recipe":true,"store_bought":false,"ingredients":["salmon","salt","black pepper","neutral oil","lemon"]}]', 'published', 'draft', 'global', NULL, '6a3bb216858c7032f29f75a727d2f5478f11ee29840b05a6d9e5f4430ed8fd7d', 'flavorweave-catalog-package', 'catalog/persian-sabzi-polo-salmon/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_peruvian-aji-de-gallina_v1', 'rcp_peruvian-aji-de-gallina', 'peruvian-aji-de-gallina', 1, 'Peruvian Ají de Gallina: Creamy Ají Amarillo Chicken with Rice and Potatoes', 'Poached, shredded chicken folded into a silky golden sauce of ají amarillo, onion, garlic, milk-soaked bread, ground walnuts, and Parmesan. Served over white rice with boiled yellow potatoes, halved eggs, and black olives.', 4, 10, 52, 62, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'A bare simmer in a 4-quart pot for the chicken. Medium in a 12-inch skillet for the sauce. A 3-quart saucepan at a boil for the potatoes and eggs. Low covered heat for the rice.', 'Chicken 165 F, shredded into fine strands. Sauce thick, smooth, and golden, coating the chicken. Potatoes tender. Eggs cooked 10 minutes.', '["poach","saute","simmer","boil"]', '[]', 'null', '[{"component_id":"chicken","name":"poached shredded chicken","made_in_recipe":true,"store_bought":false,"ingredients":["chicken breasts","onion","water","salt"]},{"component_id":"sauce","name":"ají sauce","made_in_recipe":true,"store_bought":false,"ingredients":["ají amarillo paste","onion","garlic","bread","evaporated milk","walnuts","Parmesan","cumin"]},{"component_id":"rice","name":"white rice","made_in_recipe":true,"store_bought":false,"ingredients":["rice","water"]},{"component_id":"garnish","name":"potatoes, eggs, olives","made_in_recipe":true,"store_bought":false,"ingredients":["yellow potatoes","eggs","black olives"]}]', 'published', 'draft', 'global', NULL, 'bf38549e8e2a8ee007dd6dd8e311418fa8337ecb83b7510543df41633358b635', 'flavorweave-catalog-package', 'catalog/peruvian-aji-de-gallina/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_peruvian-ceviche-sweet-potato-corn_v1', 'rcp_peruvian-ceviche-sweet-potato-corn', 'peruvian-ceviche-sweet-potato-corn', 1, 'Peruvian Ceviche with Sweet Potato and Corn', 'Cubes of very fresh flounder cured in lime juice with habanero, garlic, and ginger, folded with paper-thin red onion and cilantro. Served Peruvian-style on lettuce with boiled sweet potato rounds and corn on the cob. The fish is lime-cured, not heat-cooked.', 4, 15, 23, 38, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Boil for the sweet potatoes and corn. No heat on the fish.', 'Fish opaque on the outside with a slightly translucent center after about 10 minutes in lime. Sweet potato tender to a knife; corn bright yellow and tender.', '["cure","boil"]', '[]', 'null', '[{"component_id":"ceviche","name":"lime-cured flounder ceviche","made_in_recipe":true,"store_bought":false,"ingredients":["flounder","lime juice","habanero","garlic","ginger","red onion","cilantro","salt"]},{"component_id":"sides","name":"boiled sweet potato and corn","made_in_recipe":true,"store_bought":false,"ingredients":["sweet potatoes","corn","water","salt"]}]', 'published', 'draft', 'global', NULL, '8890be6e17c01dee9f4bb441393e32ee9ec330a2bbbbc40b706ce921504f27b4', 'flavorweave-catalog-package', 'catalog/peruvian-ceviche-sweet-potato-corn/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_peruvian-lomo-saltado_v1', 'rcp_peruvian-lomo-saltado', 'peruvian-lomo-saltado', 1, 'Peruvian Lomo Saltado', 'Soy-and-cumin-marinated sirloin strips seared hard in a smoking-hot skillet, tossed with charred red onion, juicy tomato wedges, garlic, and a fruity ají amarillo-vinegar-soy sauce, finished with cilantro and folded with crisp oven fries; served with white rice.', 4, 15, 25, 40, 'involved', 'adventurous', '6ee7bb37273cbc12eff6d5be73cdb6c79a88a65cdfe5ea686de96c0b7a43a78d', '425°F oven for fries (preheat overlaps prep); rice high then low; skillet on high, smoking hot, for the stir-fry.', 'Beef browned outside, pink and juicy inside (about medium). Onion edges charred but crisp. Tomatoes warmed, not collapsed. Fries deep golden and crisp. Rice fluffy. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"beef-marinade","name":"soy-garlic-cumin beef marinade","made_in_recipe":true,"store_bought":false,"ingredients":["soy sauce","garlic","ground cumin","black pepper"]},{"component_id":"aji-saltado-sauce","name":"ají amarillo-vinegar-soy sauce","made_in_recipe":true,"store_bought":false,"ingredients":["soy sauce","red wine vinegar","ají amarillo paste"]},{"component_id":"oven-fries","name":"oven-baked fries","made_in_recipe":true,"store_bought":false,"ingredients":["frozen straight-cut French fries"]},{"component_id":"white-rice-cooked","name":"steamed white rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain white rice","water","kosher salt"]}]', 'published', 'draft', 'global', NULL, '108ee6c6fde7a793346f27d10b8fe697480763a3530313a97d8d15b36550c75a', 'flavorweave-catalog-package', 'catalog/peruvian-lomo-saltado/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_peruvian-tacu-tacu-egg_v1', 'rcp_peruvian-tacu-tacu-egg', 'peruvian-tacu-tacu-egg', 1, 'Peruvian Tacu Tacu with a Pan-Fried Egg and Salsa Criolla', 'A crisp-crusted cake of rice and canary beans seasoned with onion, garlic, and ají amarillo, pan-fried until golden, topped with a runny pan-fried egg and a tangy salsa criolla of red onion, ají, and lime.', 4, 2, 63, 65, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', 'Low covered heat for the rice. Medium in a 12-inch nonstick skillet for the aromatics, then medium-high to pan-fry the cakes. Medium for the eggs.', 'Cakes deep golden and crisp on both sides, hot through. Egg whites set with runny yolks. Onions in the salsa crisp and tangy.', '["pan-fry","simmer","saute"]', '[]', 'null', '[{"component_id":"tacu","name":"tacu tacu cakes","made_in_recipe":true,"store_bought":false,"ingredients":["rice","canary beans","onion","garlic","ají amarillo","oregano"]},{"component_id":"salsa","name":"salsa criolla","made_in_recipe":true,"store_bought":false,"ingredients":["red onion","ají","lime","cilantro"]},{"component_id":"eggs","name":"pan-fried eggs","made_in_recipe":true,"store_bought":false,"ingredients":["eggs"]}]', 'published', 'draft', 'global', NULL, '2dc3c71905f61c90e522ad88790a5e8a76944670067ddced73672175c62b4b36', 'flavorweave-catalog-package', 'catalog/peruvian-tacu-tacu-egg/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_philly-cheesesteaks_v1', 'rcp_philly-cheesesteaks', 'philly-cheesesteaks', 1, 'Philly Cheesesteaks with Griddled Onions and Provolone', 'Thin-shaved ribeye seared hard on a hot griddle, chopped with sweet browned onions, blanketed with melting provolone, and scooped into toasted hoagie rolls. Served with crunchy dill pickle spears and pickled pepper rings.', 4, 8, 25, 33, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium for the onions; high for the steak; medium-low to melt the cheese.', 'Onions soft and browned. Steak browned in spots and just cooked through. Provolone fully melted into the meat. Rolls toasted on the cut side.', '["sear","griddle"]', '[]', 'null', '[{"component_id":"onions","name":"griddled onions","made_in_recipe":true,"store_bought":false,"ingredients":["onions","oil","salt"]},{"component_id":"steak","name":"chopped steak and provolone","made_in_recipe":true,"store_bought":false,"ingredients":["shaved ribeye","provolone","salt","pepper","oil"]},{"component_id":"rolls","name":"toasted hoagie rolls with pickles","made_in_recipe":false,"store_bought":true,"ingredients":["hoagie rolls","dill pickles","pickled pepper rings"],"contract":"Hoagie rolls: seedless, and the label lists no soy (including soy flour or soy lecithin), milk, egg, or sesame."}]', 'published', 'draft', 'global', NULL, 'cd92c75e62e37d1d6ddaf84e1304e221086f661b4d308254e99a2c57845a0a16', 'flavorweave-catalog-package', 'catalog/philly-cheesesteaks/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_polish-bigos_v1', 'rcp_polish-bigos', 'polish-bigos', 1, 'Polish Bigos: Hunter''s Stew of Sauerkraut, Cabbage, Kielbasa, and Pork', 'Poland''s slow-simmered hunter''s stew of sauerkraut and fresh cabbage with browned pork shoulder, smoked kielbasa, dried porcini, prunes, onion, tomato paste, bay, and allspice, cooked until deep, tangy, and savory. Served with rye bread.', 4, 18, 125, 143, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', 'Medium-high in a 6-quart Dutch oven to brown, medium for the onions and cabbage, then a covered low simmer, stirring occasionally.', 'Pork tender, cabbage soft and silky, stew thick and brown with very little loose liquid.', '["sear","saute","braise"]', '[]', 'null', '[{"component_id":"bigos","name":"hunter''s stew","made_in_recipe":true,"store_bought":false,"ingredients":["sauerkraut","green cabbage","pork shoulder","kielbasa","dried porcini","prunes","onion","tomato paste","bay","allspice","water"]},{"component_id":"bread","name":"rye bread","made_in_recipe":false,"store_bought":true,"ingredients":["rye bread"]}]', 'published', 'draft', 'global', NULL, 'bd75c11a9ad33e1311b3e5c6bf34bec58b91bafde4894a0a8ffd28cc6c4abe4f', 'flavorweave-catalog-package', 'catalog/polish-bigos/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_polish-mushroom-barley-krupnik_v1', 'rcp_polish-mushroom-barley-krupnik', 'polish-mushroom-barley-krupnik', 1, 'Polish Krupnik: Mushroom and Barley Soup with Dill', 'A hearty Polish barley soup built on dried porcini and fresh cremini mushrooms, with carrot, parsnip, celery, and potato, scented with bay and allspice and finished with plenty of fresh dill.', 4, 15, 59, 74, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Medium sauté; medium-low simmer.', 'Barley tender with a slight chew; potatoes and root vegetables tender; broth lightly thickened by the barley.', '["saute","simmer"]', '[]', 'null', '[{"component_id":"soup","name":"mushroom barley soup","made_in_recipe":true,"store_bought":false,"ingredients":["pearl barley","porcini","cremini","carrots","parsnip","celery","potatoes","onion","garlic","dill","bay","allspice","water","oil"]}]', 'published', 'draft', 'global', NULL, 'e48cd8796d1449a4a1bfaf170c402163f9998f3208fcc704b6e10ef941c8985f', 'flavorweave-catalog-package', 'catalog/polish-mushroom-barley-krupnik/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_polish-potato-cheese-pierogi_v1', 'rcp_polish-potato-cheese-pierogi', 'polish-potato-cheese-pierogi', 1, 'Polish Potato-and-Cheese Pierogi with Golden Onions and Sour Cream', 'Handmade pierogi of tender flour-and-egg dough filled with mashed russet potatoes, farmer''s cheese, and onions cooked in butter, boiled until they float, tossed in more golden butter onions, and served with sour cream and chives.', 4, 52, 38, 90, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', '3-quart saucepan for the potatoes; 10-inch skillet over medium for the onions; 8-quart pot at a gentle boil for the pierogi.', 'Potatoes tender enough to mash smooth; onions deep golden; pierogi float and the dough edges are tender, not floury, about 3 minutes after floating.', '["boil","saute"]', '[]', 'null', '[{"component_id":"dough","name":"pierogi dough","made_in_recipe":true,"store_bought":false,"ingredients":["all-purpose flour","egg","warm water","neutral oil","salt"]},{"component_id":"filling","name":"potato-cheese filling","made_in_recipe":true,"store_bought":false,"ingredients":["russet potatoes","water","farmer''s cheese","yellow onions","butter","black pepper","salt"]},{"component_id":"topping","name":"onions and sour cream","made_in_recipe":true,"store_bought":false,"ingredients":["yellow onions","butter","sour cream","chives"]}]', 'published', 'draft', 'global', NULL, '8aa23380cc9df1a13da628d4ca54576895d9822d8862124a33caca3b8f27648f', 'flavorweave-catalog-package', 'catalog/polish-potato-cheese-pierogi/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_pork-shogayaki_v1', 'rcp_pork-shogayaki', 'pork-shogayaki', 1, 'Pork Shōgayaki: Japanese Ginger Pork with Shredded Cabbage', 'A Japanese weeknight staple: thin slices of pork loin seared in a hot pan with onion, then glazed in a punchy fresh-ginger, soy, and mirin sauce. Served with a cool pile of finely shredded cabbage and steamed rice.', 4, 12, 17, 29, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-high skillet for the pork; medium for the onion and glaze.', 'Pork just cooked through (145 F), lightly browned; sauce reduced to a glossy glaze that coats the slices.', '["sear"]', '[]', 'null', '[{"component_id":"pork","name":"ginger-glazed pork","made_in_recipe":true,"store_bought":false,"ingredients":["pork loin","flour","onion","ginger","soy sauce","mirin","sugar","oil"]},{"component_id":"cabbage","name":"shredded cabbage","made_in_recipe":true,"store_bought":false,"ingredients":["green cabbage","scallions"]},{"component_id":"rice","name":"steamed rice","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","water"]}]', 'published', 'draft', 'global', NULL, 'b56f9235bee20411134ddede78791fe24d6a521c5fe516a3eda6850e197c06f7', 'flavorweave-catalog-package', 'catalog/pork-shogayaki/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_portuguese-grilled-sardines-potatoes_v1', 'rcp_portuguese-grilled-sardines-potatoes', 'portuguese-grilled-sardines-potatoes', 1, 'Portuguese Grilled Sardines with Boiled Potatoes and Charred Pepper Salad', 'Whole cleaned sardines brushed with olive oil and coarse salt and grilled over high heat until the skin blisters, served Lisbon-style with olive-oil boiled potatoes and a salad of charred red peppers, onion, garlic, and vinegar.', 4, 12, 37, 49, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Grill preheated on high for 10 minutes, about 500 F at the grate. A 4-quart pot at a steady boil for the potatoes.', 'Sardine skin charred and blistered, flesh opaque and pulling from the backbone, 145 F. Pepper skins blackened so they peel. Potatoes tender when pierced.', '["grill","boil"]', '[]', 'null', '[{"component_id":"sardines","name":"grilled sardines","made_in_recipe":true,"store_bought":false,"ingredients":["sardines","olive oil","coarse salt"]},{"component_id":"potatoes","name":"boiled potatoes","made_in_recipe":true,"store_bought":false,"ingredients":["potatoes","water","olive oil"]},{"component_id":"salad","name":"charred pepper salad","made_in_recipe":true,"store_bought":false,"ingredients":["red peppers","onion","garlic","vinegar","parsley"]}]', 'published', 'draft', 'global', NULL, 'f20711a75a9de4239ac494be8fa7a74e0009026cef59ae7386c8c7f4875dc436', 'flavorweave-catalog-package', 'catalog/portuguese-grilled-sardines-potatoes/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_portuguese-piri-piri-chicken_v1', 'rcp_portuguese-piri-piri-chicken', 'portuguese-piri-piri-chicken', 1, 'Portuguese Piri-Piri Roast Chicken with Rice and Tomato Salad', 'A spatchcocked whole chicken marinated in a fiery blended piri-piri sauce of red chiles, garlic, smoked paprika, lemon, and vinegar, then high-heat roasted until the skin is blistered and burnished. Served with onion rice and a sharp tomato and red-onion salad.', 4, 45, 55, 100, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Oven preheated to 425 F, rack in the upper-middle. Covered low simmer for the rice.', 'Thigh 175 F and breast 160 F (carryover to 165 F during the rest); skin deep bronze with charred spots; juices clear.', '["roast","simmer"]', '[]', 'null', '[{"component_id":"chicken","name":"piri-piri roast chicken","made_in_recipe":true,"store_bought":false,"ingredients":["whole chicken","Fresno chiles","bird''s eye chiles","garlic","smoked paprika","lemon","red wine vinegar","oregano","olive oil","salt"]},{"component_id":"rice","name":"onion rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain rice","onion","water","olive oil","salt"]},{"component_id":"salad","name":"tomato and red-onion salad","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","red onion","parsley","red wine vinegar","olive oil"]}]', 'published', 'draft', 'global', NULL, '31b3d126ce52805dcc7fa83bcdb5fb578ae74e029438434651e387dbffe5bbee', 'flavorweave-catalog-package', 'catalog/portuguese-piri-piri-chicken/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_potato-leek-gratin_v1', 'rcp_potato-leek-gratin', 'potato-leek-gratin', 1, 'Potato and Leek Gratin', 'Thinly sliced potatoes and leeks baked in a cream and cheese custard until the center is tender and the top is browned.', 4, 15, 55, 70, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Oven 400 F. Leeks sauté over medium during the preheat. Bake on the middle rack.', 'Center potato slice takes a knife with little resistance. Cream is bubbling at the edges and thickened, not watery. Cheese on top is browned in patches. No breadcrumb crust. Rest 5 minutes. Written bake is 40 minutes at 400 F for 1/8-inch slices. kitchen_tested is false. Extra time beyond 40 minutes, if the center is still firm, is not included in the 70-minute total.', '[]', '[]', 'null', '[{"component_id":"cream-cheese-custard","name":"cream-cheese custard","made_in_recipe":true,"store_bought":false,"ingredients":["heavy cream","vegetarian Gruyère","garlic","kosher salt","black pepper","ground nutmeg","fresh thyme"]}]', 'published', 'draft', 'global', NULL, '6f7addeef404ad541177eb096a8a78dc077bda23867edaccf7c67f25c5d3bb90', 'flavorweave-catalog-package', 'catalog/potato-leek-gratin/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_pressure-cooker-butter-chicken_v1', 'rcp_pressure-cooker-butter-chicken', 'pressure-cooker-butter-chicken', 1, 'Pressure-Cooker Butter Chicken', 'Tender chicken thigh pieces in a silky, gently spiced tomato-butter-cream sauce made in an electric pressure cooker: onion, garlic, and ginger bloomed in butter with garam masala and paprika, pressure-cooked with tomato puree, then finished with cream and a last knob of butter. Served with fluffy basmati rice and cilantro.', 4, 15, 37, 52, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Electric pressure cooker: Sauté (high) for butter and aromatics; Pressure Cook High 5 minutes with 5-minute natural release; Sauté to finish with cream. Stovetop saucepan for rice: boil, then low. No oven.', 'Chicken very tender, at least 165 F (175 F ideal for thighs); sauce thick enough to coat a spoon, glossy after the cold butter; no raw spice taste. Rice tender and fluffy with separate grains. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"butter-chicken","name":"pressure-cooker butter chicken","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","kosher salt","garam masala","ground cumin","ground coriander","ground turmeric","sweet paprika","cayenne","unsalted butter","neutral oil","yellow onion","garlic","fresh ginger","water","tomato puree","heavy cream","sugar"]},{"component_id":"basmati-rice","name":"steamed basmati rice","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","water","kosher salt"]}]', 'published', 'draft', 'global', NULL, 'd3d5014a545c565d50d6b0396b92c89429641e13b989fbe0888ca39b57940b4b', 'flavorweave-catalog-package', 'catalog/pressure-cooker-butter-chicken/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_puerto-rican-pollo-guisado_v1', 'rcp_puerto-rican-pollo-guisado', 'puerto-rican-pollo-guisado', 1, 'Puerto Rican Pollo Guisado with White Rice', 'Bone-in chicken browned and stewed in fresh sofrito with tomato sauce, homemade sazón of achiote, cumin, coriander, and oregano, potatoes, carrots, and briny olives with pimientos. Served over white rice.', 4, 15, 64, 79, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high in a 5-quart Dutch oven to brown, medium for the sofrito, then a covered gentle simmer. Low covered heat for the rice.', 'Chicken 175 F near the bone and tender. Potatoes and carrots tender when pierced. Sauce brick-orange and thick enough to coat the potatoes.', '["sear","braise"]', '[]', 'null', '[{"component_id":"sofrito","name":"sofrito","made_in_recipe":true,"store_bought":false,"ingredients":["onion","green pepper","cubanelle pepper","garlic","cilantro"]},{"component_id":"guisado","name":"chicken stew","made_in_recipe":true,"store_bought":false,"ingredients":["chicken","sofrito","tomato sauce","sazón spices","potatoes","carrots","olives","water"]},{"component_id":"rice","name":"white rice","made_in_recipe":true,"store_bought":false,"ingredients":["rice","water","salt","oil"]}]', 'published', 'draft', 'global', NULL, 'f5c78d1af391d35fa91578981e8e2dfb1c7f7bd54e6981a8526f55659166c6d8', 'flavorweave-catalog-package', 'catalog/puerto-rican-pollo-guisado/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_pumpkin-pinto-bean-chili_v1', 'rcp_pumpkin-pinto-bean-chili', 'pumpkin-pinto-bean-chili', 1, 'Smoky Pumpkin and Pinto Bean Chili', 'A thick, brick-red pinto bean chili built on smoked paprika, chili powder, and fire-roasted tomatoes, with canned pumpkin melted in for body and a gentle sweetness. Finished with lime and topped with diced avocado, radish, cilantro, and crushed corn tortilla chips. Plant-based; no cheese, no sour cream.', 4, 12, 33, 45, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', 'Stovetop only. Medium to soften the onion and pepper; medium-high to return to a simmer; medium-low uncovered simmer. No oven.', 'Chili thick enough to mound on a spoon; beans tender and some crushed into the base; pumpkin fully melted into a brick-red, glossy chili; no raw spice taste. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"smoky-pumpkin-pinto-chili","name":"smoky pumpkin pinto bean chili","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","yellow onion","red bell pepper","garlic","chili powder","ground cumin","smoked paprika","ground chipotle","dried oregano","tomato paste","pumpkin puree","fire-roasted tomatoes","pinto beans","vegetable broth","kosher salt","lime juice"]},{"component_id":"fresh-toppings","name":"avocado, radish, cilantro, and tortilla-chip toppings","made_in_recipe":true,"store_bought":false,"ingredients":["avocados","radishes","cilantro","corn tortilla chips","lime wedges"],"contract":"Assembled from raw/whole ingredients; tortilla chips are store-bought with a plain-corn, non-peanut-oil contract."}]', 'published', 'draft', 'global', NULL, 'f4d299138ca21c4bc70b59343a44c92f1fa8ea1e790d41ecf8bcd99b52d2c7c1', 'flavorweave-catalog-package', 'catalog/pumpkin-pinto-bean-chili/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_punjabi-rajma-chawal_v1', 'rcp_punjabi-rajma-chawal', 'punjabi-rajma-chawal', 1, 'Punjabi Rajma Chawal: Kidney Bean Curry with Basmati Rice', 'Red kidney beans simmered in a deeply browned onion, ginger, garlic, and tomato masala until the gravy turns thick and glossy, finished with garam masala and lemon. Served over steamed basmati with cilantro.', 4, 12, 44, 56, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium heat in a heavy 4-quart pot for the masala, then a gentle simmer. Low covered heat for the rice.', 'Onions deep golden-brown before the tomatoes go in. Masala thick with oil shining at the edges. Beans soft enough to crush against the pot; gravy coats a spoon. Rice tender and separate.', '["saute","simmer"]', '[]', 'null', '[{"component_id":"rajma","name":"kidney bean curry","made_in_recipe":true,"store_bought":false,"ingredients":["kidney beans","onion","ginger","garlic","green chile","tomatoes","spices"]},{"component_id":"rice","name":"steamed basmati","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","water","salt"]}]', 'published', 'draft', 'global', NULL, 'c3e7534b80f12d39fda8d45743664a675040c21dd8ce89e4af5f30cfc5e946fa', 'flavorweave-catalog-package', 'catalog/punjabi-rajma-chawal/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_red-snapper-veracruzana_v1', 'rcp_red-snapper-veracruzana', 'red-snapper-veracruzana', 1, 'Red Snapper a la Veracruzana with White Rice', 'Red snapper fillets simmered in a Veracruz-style tomato sauce with green olives, capers, pickled jalapeños, garlic, bay, and oregano. Served with white rice and lime.', 4, 12, 33, 45, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium in a 12-inch skillet for the sauce, then a covered medium-low simmer for the fish. Low covered heat for the rice.', 'Sauce chunky and saucy, tomatoes softened. Fish opaque and flaking, 145 F at the thickest part. Rice tender.', '["simmer","braise"]', '[]', 'null', '[{"component_id":"veracruzana","name":"Veracruz tomato-olive sauce","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","onion","garlic","olives","capers","pickled jalapenos","bay","oregano"]},{"component_id":"fish","name":"simmered snapper","made_in_recipe":true,"store_bought":false,"ingredients":["red snapper"]},{"component_id":"rice","name":"white rice","made_in_recipe":true,"store_bought":false,"ingredients":["rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '7e33e28a66a6f9c5dcdad2c21c89797424a1411df4fb787154090a0caf94083f', 'flavorweave-catalog-package', 'catalog/red-snapper-veracruzana/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_roasted-butternut-farro-plate_v1', 'rcp_roasted-butternut-farro-plate', 'roasted-butternut-farro-plate', 1, 'Roasted Butternut Plate with Farro and Lemon-Herb Dressing', 'Oven-roasted butternut wedges beside simmered pearled farro, with a lemon, garlic, and parsley dressing spooned over the plate.', 4, 15, 35, 50, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Oven 425 F for the squash. Farro simmers on the stove. Dressing is not cooked.', 'Squash is done when the edges are browned and a knife meets no resistance, about 35 minutes, flipped at 20. Pearled farro is done when the grains are tender and some have split, about 30 minutes. This recipe is pearled farro only.', '[]', '[]', 'null', '[{"component_id":"lemon-herb-dressing","name":"lemon-herb dressing","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","lemon","garlic","dijon mustard","fresh parsley","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, 'b31a64f4553e5dd21984399d58b6460114886716fb6cb1f1d94b2c4484d5bf2f', 'flavorweave-catalog-package', 'catalog/roasted-butternut-farro-plate/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_roasted-cabbage-cashew-romesco_v1', 'rcp_roasted-cabbage-cashew-romesco', 'roasted-cabbage-cashew-romesco', 1, 'Roasted Cabbage Steaks with Cashew Romesco', 'Thick cabbage steaks roasted in the oven until the cut faces are crisp, with a cashew romesco. Cashews only: no almonds and no dairy.', 4, 15, 30, 45, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Oven 425 F.', 'Cabbage tender at the core, cut faces browned and crisp. Romesco thick enough to spoon, not a broth.', '["roast"]', '[]', 'null', '[{"component_id":"romesco","name":"cashew romesco","made_in_recipe":true,"store_bought":false,"ingredients":["roasted red peppers","cashews","garlic","smoked paprika","red wine vinegar","olive oil"]}]', 'published', 'draft', 'global', NULL, '4f955668f087099553edbd26c7962cf0070474228f63ce2d0547145574092518', 'flavorweave-catalog-package', 'catalog/roasted-cabbage-cashew-romesco/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_roasted-cauliflower-shawarma-plate_v1', 'rcp_roasted-cauliflower-shawarma-plate', 'roasted-cauliflower-shawarma-plate', 1, 'Roasted Cauliflower Shawarma Plate', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["plant","dairy-free"]', 'null', '[]', 'retired', 'published', 'global', NULL, '8bdf1241bad9dc49cb37c607b50f33e5c9bdfc9d0fc265c9618d3dc9777d1df7', 'flavorweave-legacy-catalog-package', 'catalog/roasted-cauliflower-shawarma-plate/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_roasted-cauliflower-shawarma-plate_v2', 'rcp_roasted-cauliflower-shawarma-plate', 'roasted-cauliflower-shawarma-plate', 2, 'Roasted Cauliflower Shawarma Plate', 'Oven-roasted cauliflower with store-bought shawarma spice, tahini and lemon drizzle, diced cucumber, and warm pita.', 4, 15, 25, 40, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', 'Oven 425 F. The sauce is not cooked.', 'Cauliflower is done when the edges are charred and a stem is tender, about 25 minutes at 425 F.', '["oven"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'a8e8bae255345ed81bca7ff158ea70b20c7ad1da0936dd17e372fb960654117f', 'flavorweave-legacy-audit-draft', 'catalog/roasted-cauliflower-shawarma-plate/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_roasted-whole-branzino-salmoriglio_v1', 'rcp_roasted-whole-branzino-salmoriglio', 'roasted-whole-branzino-salmoriglio', 1, 'Roasted Whole Branzino with Salmoriglio and Lemon Potatoes', 'Two whole branzino stuffed with lemon, garlic, and oregano and roasted on a bed of crisp-edged sliced potatoes and red onion, then spooned with salmoriglio, the Sicilian lemon, oregano, garlic, and olive oil sauce.', 4, 15, 45, 60, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Oven preheated to 450 F, rack in the middle.', 'Fish flesh opaque and lifting easily from the backbone, 135 to 140 F at the thickest point; skin crisp at the edges. Potatoes golden and tender.', '["roast"]', '[]', 'null', '[{"component_id":"fish","name":"roasted whole branzino","made_in_recipe":true,"store_bought":false,"ingredients":["branzino","lemon","garlic","oregano","olive oil","salt"]},{"component_id":"potatoes","name":"lemon potatoes and onion","made_in_recipe":true,"store_bought":false,"ingredients":["Yukon Gold potatoes","red onion","olive oil","salt"]},{"component_id":"salmoriglio","name":"salmoriglio","made_in_recipe":true,"store_bought":false,"ingredients":["lemon","oregano","garlic","parsley","chile flakes","olive oil","salt"]}]', 'published', 'draft', 'global', NULL, '35acbea1dfa24f20fedc80716c48adcd301c7ceb90d29b6cd80c99317abd4597', 'flavorweave-catalog-package', 'catalog/roasted-whole-branzino-salmoriglio/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_russian-mushroom-stroganoff_v1', 'rcp_russian-mushroom-stroganoff', 'russian-mushroom-stroganoff', 1, 'Mushroom Stroganoff with Sour Cream, Dill, and Buttered Egg Noodles', 'Thick-sliced cremini mushrooms seared in batches until deeply browned, then simmered with onion, garlic, sweet paprika, Dijon mustard, and vegetable broth and finished with sour cream and fresh dill. Served over buttered wide egg noodles.', 4, 10, 31, 41, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '12-inch skillet over medium-high to sear the mushrooms, medium for the onion and the sauce, low once the sour cream goes in. 6-quart pot at a rolling boil for the noodles.', 'Mushrooms deep brown on the cut faces. Onion soft and pale gold. Sauce thick enough to coat a spoon; sour cream warmed through without boiling. Noodles tender.', '["sear","saute","simmer","boil"]', '[]', 'null', '[{"component_id":"stroganoff","name":"mushroom stroganoff","made_in_recipe":true,"store_bought":false,"ingredients":["cremini mushrooms","onion","garlic","butter","flour","paprika","Dijon mustard","vegetable broth","sour cream","dill"]},{"component_id":"noodles","name":"buttered egg noodles","made_in_recipe":true,"store_bought":false,"ingredients":["egg noodles","water","salt","butter"]}]', 'published', 'draft', 'global', NULL, '4499e10de0ec2cbc7a7945a6c962259af0212055d01b9fd0b697406c70883a00', 'flavorweave-catalog-package', 'catalog/russian-mushroom-stroganoff/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_saag-paneer_v1', 'rcp_saag-paneer', 'saag-paneer', 1, 'Saag Paneer', 'Browned paneer cubes simmered in a spiced spinach (saag) skillet sauce finished with cream and butter.', 4, 18, 28, 46, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Boil for spinach blanch (inside prep). Skillet medium-high for paneer, then medium for the saag base and simmer. Finish cream on low/off-hard-boil.', 'Paneer golden on several faces, soft inside, not rubbery-dry. Saag thick enough to coat a spoon, spinach cooked and green-olive rather than raw. Cream stirred smooth. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"spinach-saag","name":"spinach saag","made_in_recipe":true,"store_bought":false,"ingredients":["neutral oil","yellow onion","garlic","fresh ginger","jalapeño","ground cumin","ground coriander","ground turmeric","garam masala","cayenne pepper","canned diced tomatoes","baby spinach","water","kosher salt","heavy cream","unsalted butter","lemon juice","fresh cilantro"]}]', 'published', 'draft', 'global', NULL, 'defbe233a1b14513accc3780910045721be66159b1c1d5e44d00f8e4476151c3', 'flavorweave-catalog-package', 'catalog/saag-paneer/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sabich-pita-sandwiches_v1', 'rcp_sabich-pita-sandwiches', 'sabich-pita-sandwiches', 1, 'Sabich Pita with Crispy Eggplant and Tahini', 'Warm pocket pitas spread with hummus and stuffed with golden pan-fried eggplant, sliced hard-boiled egg, a chopped tomato-cucumber salad, dill pickles, and parsley, then drizzled with garlicky lemon tahini. Dairy-free pita contracted; amba (mango pickle sauce) optional.', 4, 15, 28, 43, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium-high skillet for shallow-frying; boiling water for eggs; medium dry skillet to warm pitas. No oven.', 'Eggplant deep golden with crisp edges and fully creamy inside (no white, spongy centers). Eggs boiled 10 minutes: whites set, yolks firm but moist. Tahini pourable. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"crispy-eggplant","name":"pan-fried eggplant rounds","made_in_recipe":true,"store_bought":false,"ingredients":["eggplant","kosher salt","neutral oil"]},{"component_id":"hard-boiled-eggs","name":"hard-boiled eggs","made_in_recipe":true,"store_bought":false,"ingredients":["eggs"]},{"component_id":"lemon-tahini","name":"garlic lemon tahini sauce","made_in_recipe":true,"store_bought":false,"ingredients":["tahini","lemon juice","garlic","kosher salt","cold water"]},{"component_id":"chopped-salad","name":"tomato-cucumber chopped salad","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","Persian cucumbers","parsley","lemon juice","olive oil","kosher salt"]},{"component_id":"store-bought-condiments","name":"hummus, dill pickles, optional amba","made_in_recipe":false,"store_bought":true,"ingredients":["hummus","dill pickles","amba"]}]', 'published', 'draft', 'global', NULL, 'c49dee4c088d9df638343c5d52159735ac839ec6ed047cf215d0f628ea3b8289', 'flavorweave-catalog-package', 'catalog/sabich-pita-sandwiches/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_salade-nicoise-seared-tuna_v1', 'rcp_salade-nicoise-seared-tuna', 'salade-nicoise-seared-tuna', 1, 'Salade Niçoise with Seared Tuna', 'A dinner-sized composed salad: pepper-crusted seared ahi tuna sliced rare, warm baby potatoes tossed in Dijon-shallot vinaigrette, jammy 7-minute eggs, crisp green beans, cherry tomatoes, olives, and capers on butter lettuce. Dairy-free vinaigrette; no butter anywhere.', 4, 15, 29, 44, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', 'Stovetop only. High heat for the boiling water and a steady boil for potatoes/eggs/beans; high heat, shimmering oil for the tuna sear. No oven.', 'Potatoes knife-tender; eggs jammy (7 minutes from cold); beans bright green and crisp-tender; tuna seared on the outside with a deep-red rare center (about 115 F) or 145 F if cooked through by preference. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"dijon-shallot-vinaigrette","name":"Dijon-shallot vinaigrette (dairy-free)","made_in_recipe":true,"store_bought":false,"ingredients":["extra-virgin olive oil","red wine vinegar","Dijon mustard","shallot","garlic","kosher salt","black pepper"]},{"component_id":"one-pot-potatoes-eggs-beans","name":"warm vinaigrette potatoes, jammy eggs, and blanched green beans (one pot)","made_in_recipe":true,"store_bought":false,"ingredients":["baby potatoes","eggs","green beans","kosher salt","vinaigrette"]},{"component_id":"pepper-seared-tuna","name":"pepper-seared ahi tuna","made_in_recipe":true,"store_bought":false,"ingredients":["yellowfin tuna","neutral oil","kosher salt","black pepper"]},{"component_id":"composed-salad","name":"composed niçoise salad","made_in_recipe":true,"store_bought":false,"ingredients":["butter lettuce","cherry tomatoes","olives","capers","parsley","optional anchovies"]}]', 'published', 'draft', 'global', NULL, '61e64943e53406bc4a5a0533f916ac256e236e23f0a5052d4416abfb8706cea6', 'flavorweave-catalog-package', 'catalog/salade-nicoise-seared-tuna/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_salvadoran-bean-cheese-pupusas_v1', 'rcp_salvadoran-bean-cheese-pupusas', 'salvadoran-bean-cheese-pupusas', 1, 'Salvadoran Bean-and-Cheese Pupusas with Curtido and Salsa Roja', 'Thick masa harina rounds stuffed with smooth refried small red beans and mozzarella and griddled until spotted brown, served with curtido, a tangy slaw of cabbage, carrot, onion, jalapeno, oregano, and cider vinegar, and a simple simmered salsa roja of roma tomatoes, onion, and garlic.', 4, 37, 33, 70, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', '12-inch cast-iron skillet over medium, lightly oiled, for the pupusas; 1-quart saucepan for the salsa.', 'Pupusas spotted golden-brown on both sides, hot through, with melted cheese at any small crack; curtido wilted but crunchy.', '["griddle","simmer","pickle"]', '[]', 'null', '[{"component_id":"curtido","name":"curtido","made_in_recipe":true,"store_bought":false,"ingredients":["green cabbage","carrot","white onion","jalapeno","dried oregano","apple cider vinegar","water","salt"]},{"component_id":"salsa","name":"salsa roja","made_in_recipe":true,"store_bought":false,"ingredients":["roma tomatoes","white onion","garlic","salt"]},{"component_id":"pupusas","name":"pupusas","made_in_recipe":true,"store_bought":false,"ingredients":["masa harina","warm water","salt","refried small red beans","mozzarella","neutral oil"]}]', 'published', 'draft', 'global', NULL, 'fd230dd5c1847b948c04bc78c98bcb5337c4dca73bd99cf1dee03aa0453ec077', 'flavorweave-catalog-package', 'catalog/salvadoran-bean-cheese-pupusas/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_san-francisco-cioppino_v1', 'rcp_san-francisco-cioppino', 'san-francisco-cioppino', 1, 'San Francisco Cioppino with Clams, Mussels, Shrimp, and Cod', 'A tomato and white wine broth built on onion, fennel, garlic, red pepper flakes, and tomato paste with crushed tomatoes, clam juice, bay, and oregano, in which littleneck clams, mussels, shrimp, and chunks of cod are cooked just until done, finished with parsley and served with toasted sourdough.', 4, 15, 45, 60, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '6-quart Dutch oven over medium for the base, then a steady simmer and a covered steam for the shellfish; 12-inch skillet over medium for the bread.', 'Clams and mussels opened (discard any that stay shut); shrimp pink and just opaque; cod flaking, 145 F.', '["simmer","steam","toast"]', '[]', 'null', '[{"component_id":"broth","name":"cioppino base","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","onion","fennel","garlic","red pepper flakes","tomato paste","white wine","crushed tomatoes","clam juice","water","bay leaves","dried oregano","salt"]},{"component_id":"seafood","name":"seafood","made_in_recipe":true,"store_bought":false,"ingredients":["littleneck clams","mussels","shrimp","cod","parsley"]},{"component_id":"bread","name":"toasted sourdough","made_in_recipe":true,"store_bought":false,"ingredients":["sourdough bread","olive oil"]}]', 'published', 'draft', 'global', NULL, '3b4dd94fbf69dae668729b901f152c7a4cb4606c3f4debe68011733310fe6e99', 'flavorweave-catalog-package', 'catalog/san-francisco-cioppino/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_seared-duck-breast-cherry_v1', 'rcp_seared-duck-breast-cherry', 'seared-duck-breast-cherry', 1, 'Seared Duck Breast with Cherry Pan Sauce', 'Duck breasts with the skin seared until crisp, a cherry pan sauce, and arugula. No butter.', 4, 10, 22, 32, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium skillet, starting with a cold pan so the skin renders. Medium for the sauce.', 'Skin crisp and golden, interior 135 F, then a 5-minute rest. Sauce syrupy enough to coat a spoon.', '["sear"]', '[]', 'null', '[{"component_id":"sauce","name":"cherry pan sauce","made_in_recipe":true,"store_bought":false,"ingredients":["cherries","shallot","red wine vinegar","red wine","honey","thyme"]}]', 'published', 'draft', 'global', NULL, '2fb5e760fbb5e50e9901699189d1e1d40e0c30e47f6506e72b965d2188b2ff14', 'flavorweave-catalog-package', 'catalog/seared-duck-breast-cherry/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_seared-scallops-parsnip-puree_v1', 'rcp_seared-scallops-parsnip-puree', 'seared-scallops-parsnip-puree', 1, 'Seared Scallops with Parsnip Purée and Crispy Sage', 'Golden-crusted sea scallops on a silky, sweet parsnip purée, spooned with nutty sage brown butter and crisp-fried sage leaves, with a lemony baby arugula salad for brightness.', 4, 10, 37, 47, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium to bring the parsnips to a bare simmer, then gentle; medium for the brown butter; high, very hot skillet for searing; lowest heat to hold the purée.', 'Parsnips very tender; purée completely silky. Sage crisp and butter nutty brown, not black. Scallops with a deep golden-brown crust, just opaque at the edges, translucent in the center (120 to 125 F). For fully cooked scallops (recommended for young children, pregnant, older, or immunocompromised diners), cook 1 to 2 minutes longer on the second side until opaque throughout (145 F). kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"parsnip-puree","name":"silky parsnip purée","made_in_recipe":true,"store_bought":false,"ingredients":["parsnips","whole milk","water","unsalted butter","kosher salt"]},{"component_id":"sage-brown-butter","name":"sage brown butter with crispy sage","made_in_recipe":true,"store_bought":false,"ingredients":["unsalted butter","fresh sage","kosher salt"]},{"component_id":"seared-scallops","name":"seared sea scallops","made_in_recipe":true,"store_bought":false,"ingredients":["sea scallops","neutral oil","kosher salt","black pepper"]},{"component_id":"lemony-arugula","name":"lemony arugula salad","made_in_recipe":true,"store_bought":false,"ingredients":["baby arugula","extra-virgin olive oil","lemon","kosher salt"]}]', 'published', 'draft', 'global', NULL, 'b9031916ca627a108b05c7dcc45ec8a5063b66c7d1111a2692bdbea64fffcd9f', 'flavorweave-catalog-package', 'catalog/seared-scallops-parsnip-puree/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_senegalese-fish-yassa_v1', 'rcp_senegalese-fish-yassa', 'senegalese-fish-yassa', 1, 'Senegalese Fish Yassa with Lemon-Mustard Onions and Rice', 'Broiled tilapia fillets under a heap of onions slowly cooked down in a lemon, Dijon, and garlic marinade until soft, golden, and jammy, with a whole habanero for gentle heat. Served over white rice with parsley and lemon.', 4, 15, 36, 51, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-high then medium-low skillet for the onions. Broiler on high, rack 6 inches below, for the fish. Low covered simmer for the rice.', 'Onions very soft, golden, and jammy with a thick, glossy sauce. Fish opaque, flaking, and 145 F, lightly browned at the edges. Rice tender and dry.', '["simmer","broil"]', '[]', 'null', '[{"component_id":"yassa-onions","name":"lemon-mustard yassa onions","made_in_recipe":true,"store_bought":false,"ingredients":["onions","lemon juice","Dijon mustard","garlic","habanero","bay leaves","water","oil"]},{"component_id":"broiled-fish","name":"broiled tilapia","made_in_recipe":true,"store_bought":false,"ingredients":["tilapia","marinade","oil"]},{"component_id":"rice","name":"steamed white rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain white rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '731bf52bcdf5402e2a1884132a34d6392ca7e11d45130496ca15b2acf03a747a', 'flavorweave-catalog-package', 'catalog/senegalese-fish-yassa/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sesame-soba-noodle-bowl_v1', 'rcp_sesame-soba-noodle-bowl', 'sesame-soba-noodle-bowl', 1, 'Sesame Soba Noodle Bowl', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["plant","dairy-free","bowl"]', 'null', '[]', 'retired', 'published', 'global', NULL, '6d9bfe7aa496d7f793ed7a848bb17b0cadfe68479b15f98fb49c3193e900cafb', 'flavorweave-legacy-catalog-package', 'catalog/sesame-soba-noodle-bowl/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sesame-soba-noodle-bowl_v2', 'rcp_sesame-soba-noodle-bowl', 'sesame-soba-noodle-bowl', 2, 'Sesame Soba Noodle Bowl', 'Cold rinsed soba tossed with sesame oil, rice vinegar, and soy, topped with julienned carrot, edamame, and sesame seeds.', 4, 15, 10, 25, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Boiling water for the soba. The dressing is not cooked.', 'Soba is done when tender but not mushy, 4 to 5 minutes, then rinsed cold. Edamame is already cooked and only thawed.', '["stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, '33d99cfe55c2e9b6329cef8d2a68d7b7f4eaef9a96079d42a3c1e70611969aaa', 'flavorweave-legacy-audit-draft', 'catalog/sesame-soba-noodle-bowl/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_shallow-fried-green-tomatoes_v1', 'rcp_shallow-fried-green-tomatoes', 'shallow-fried-green-tomatoes', 1, 'Shallow-Fried Green Tomatoes with White Beans and Slaw', 'Cornmeal-crusted green tomato slices, shallow-fried until golden, with smoky white beans and a vinegar slaw. No buttermilk and no mayonnaise.', 4, 18, 18, 36, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium skillet, about 1/4 inch of oil, for the tomatoes. A small pot over medium for the beans.', 'Tomato crust golden and crisp, interior hot and juicy, not raw and not mush. Beans heated through. Slaw still crunchy.', '["shallow-fry"]', '[]', 'null', '[{"component_id":"tomatoes","name":"shallow-fried green tomatoes","made_in_recipe":true,"store_bought":false,"ingredients":["green tomatoes","cornmeal","eggs"]},{"component_id":"beans","name":"smoky white beans","made_in_recipe":true,"store_bought":false,"ingredients":["cannellini beans","garlic","smoked paprika"]},{"component_id":"slaw","name":"vinegar slaw","made_in_recipe":true,"store_bought":false,"ingredients":["green cabbage","scallions","apple cider vinegar","sugar"]}]', 'published', 'draft', 'global', NULL, 'bc90dadccc25d7b2b6848afdf18e409133fb922c83d484bc82f0e89c4b72d207', 'flavorweave-catalog-package', 'catalog/shallow-fried-green-tomatoes/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sheet-pan-gnocchi-brussels-apples_v1', 'rcp_sheet-pan-gnocchi-brussels-apples', 'sheet-pan-gnocchi-brussels-apples', 1, 'Sheet-Pan Crispy Gnocchi with Brussels Sprouts and Apples', 'Shelf-stable potato gnocchi roasted straight from the package until golden and crisp, with deeply browned Brussels sprouts, red onion, and apple wedges, finished in a sticky maple-Dijon-cider glaze with fresh thyme. Egg-free, dairy-free gnocchi contracted; no Parmesan, no butter, no nuts.', 4, 15, 30, 45, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', '450°F oven, two racks (upper-middle and lower-middle). Preheat overlaps prep.', 'Gnocchi puffed, golden, and crisp at the edges with soft centers. Sprouts deeply browned on cut sides and knife-tender. Apples browned at edges but holding shape. Glaze sticky, not pooled. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"maple-dijon-glaze","name":"maple-Dijon-cider glaze","made_in_recipe":true,"store_bought":false,"ingredients":["pure maple syrup","apple cider vinegar","Dijon mustard","fresh thyme","kosher salt"]},{"component_id":"roasted-gnocchi-sprouts-apples","name":"roasted gnocchi, sprouts, apples, and onion","made_in_recipe":true,"store_bought":false,"ingredients":["shelf-stable potato gnocchi (egg-free, dairy-free)","Brussels sprouts","crisp apples","red onion","olive oil","fresh thyme"]}]', 'published', 'draft', 'global', NULL, 'b748d8df97b73c4034f933a76f15461750c8a55b16334906d09eb244792caef0', 'flavorweave-catalog-package', 'catalog/sheet-pan-gnocchi-brussels-apples/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sheet-pan-lemon-herb-chicken_v1', 'rcp_sheet-pan-lemon-herb-chicken', 'sheet-pan-lemon-herb-chicken', 1, 'Sheet-Pan Lemon Herb Chicken', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["poultry","meat","sheet-pan"]', 'null', '[]', 'retired', 'published', 'global', NULL, 'c5733191d72779325996b719dc655a3dfdb879b44e505575241e72983a8f2e23', 'flavorweave-legacy-catalog-package', 'catalog/sheet-pan-lemon-herb-chicken/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sheet-pan-lemon-herb-chicken_v2', 'rcp_sheet-pan-lemon-herb-chicken', 'sheet-pan-lemon-herb-chicken', 2, 'Sheet-Pan Lemon Herb Chicken', NULL, 4, 15, 45, 60, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', NULL, NULL, '["oven","sheet-pan"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, '2a857c9ef0142d94adc24e2288faad59d08c6ec63496e7a6993d306915be3c70', 'flavorweave-legacy-catalog-package', 'catalog/sheet-pan-lemon-herb-chicken/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sheet-pan-margherita-pizza_v1', 'rcp_sheet-pan-margherita-pizza', 'sheet-pan-margherita-pizza', 1, 'Sheet-Pan Margherita Pizza', 'Store-bought pizza dough pressed into an olive-oiled sheet pan, topped with a simple crushed-tomato sauce and torn fresh mozzarella, baked hot until crisp underneath, and finished with fresh basil.', 4, 15, 44, 59, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Oven 475 F, rack in the lower third, preheated about 20 minutes. Oiled heavy sheet pan directly on the rack — no pizza stone, no broiler, no grill.', 'Underside deep golden and crisp when a corner is lifted (not pale or doughy); edges golden and puffed. Fresh mozzarella melted, bubbling, lightly spotted — not separated into oil and not browned to rubber. Sauce reduced and jammy, not watery. Basil bright green, added after baking. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"sheet-pan-dough","name":"store-bought pizza dough base","made_in_recipe":false,"store_bought":true,"contract":"Store-bought raw pizza dough limited to wheat flour, water, yeast, salt, oil, optional sugar; no milk/egg/cheese/soy flour.","ingredients":["store-bought raw pizza dough","extra-virgin olive oil"]},{"component_id":"crushed-tomato-sauce","name":"uncooked crushed-tomato sauce","made_in_recipe":true,"store_bought":false,"ingredients":["canned crushed tomatoes","garlic","extra-virgin olive oil","kosher salt"]},{"component_id":"margherita-topping","name":"fresh mozzarella and basil topping","made_in_recipe":true,"store_bought":false,"ingredients":["fresh mozzarella","fresh basil"]}]', 'published', 'draft', 'global', NULL, '9c6c13cb8b3fc5fe052cea4e5a54c5223952a87e7a752c530e2a24cc8b1ba887', 'flavorweave-catalog-package', 'catalog/sheet-pan-margherita-pizza/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sheet-pan-shrimp-boil_v1', 'rcp_sheet-pan-shrimp-boil', 'sheet-pan-shrimp-boil', 1, 'Sheet-Pan Shrimp Boil with Corn and Andouille', 'All the flavor of a Lowcountry boil without the boil: Old Bay–seasoned baby potatoes, red onion, corn rounds, and smoky andouille roast until browned, then garlic-Old Bay butter shrimp go on for the last few minutes. Finished with lemon and parsley, straight from the pans.', 4, 15, 35, 50, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Oven 425 F, racks in upper and lower thirds, preheated during the 15-minute prep. Pans switch racks when the corn goes in. Microwave only to melt the garlic butter.', 'Potatoes fork-tender and browned on the cut side; corn kernels spotted golden; andouille browned at the edges; shrimp pink, opaque, loosely C-shaped (145 F), not tightly curled. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"old-bay-sheet-pan-vegetables-and-sausage","name":"Old Bay roasted potatoes, onion, corn, and andouille","made_in_recipe":true,"store_bought":false,"ingredients":["baby potatoes","red onion","corn","andouille sausage","olive oil","Old Bay seasoning","kosher salt"]},{"component_id":"garlic-old-bay-butter-shrimp","name":"garlic Old Bay butter shrimp","made_in_recipe":true,"store_bought":false,"ingredients":["shrimp","unsalted butter","garlic","Old Bay seasoning"]}]', 'published', 'draft', 'global', NULL, 'dcd0d345b574d9b77366ce09a2464ef13779e4d91253625d81e8d920a4c68f19', 'flavorweave-catalog-package', 'catalog/sheet-pan-shrimp-boil/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sichuan-dan-dan-noodles_v1', 'rcp_sichuan-dan-dan-noodles', 'sichuan-dan-dan-noodles', 1, 'Sichuan Dan Dan Noodles with Crisp Pork and Sesame Chili Sauce', 'Wheat noodles tossed in a sauce of Chinese sesame paste, chili oil, soy sauce, black vinegar, sugar, ground Sichuan peppercorn, and garlic, topped with crisp-cooked ground pork seasoned with Shaoxing wine and soy sauce, blanched baby bok choy, and scallions.', 4, 8, 20, 28, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', '6-quart pot over high for the noodles; 12-inch skillet over medium-high for the pork.', 'Pork crisp and browned in bits; noodles just tender with a little bite; sauce loosened to coat the noodles.', '["saute","boil"]', '[]', 'null', '[{"component_id":"sauce","name":"sesame chili sauce","made_in_recipe":true,"store_bought":false,"ingredients":["Chinese sesame paste","chili oil","soy sauce","black vinegar","sugar","Sichuan peppercorns","garlic"]},{"component_id":"pork","name":"crisp pork","made_in_recipe":true,"store_bought":false,"ingredients":["ground pork","neutral oil","Shaoxing wine","soy sauce"]},{"component_id":"noodles","name":"noodles and greens","made_in_recipe":true,"store_bought":false,"ingredients":["fresh wheat noodles","water","baby bok choy","scallions"]}]', 'published', 'draft', 'global', NULL, '3e21b5def4d67d220789803fad1343debdcd2913b26836cb2b344b1ede8400ed', 'flavorweave-catalog-package', 'catalog/sichuan-dan-dan-noodles/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sichuan-green-bean-mushroom-stir-fry_v1', 'rcp_sichuan-green-bean-mushroom-stir-fry', 'sichuan-green-bean-mushroom-stir-fry', 1, 'Sichuan Green Bean and Mushroom Stir-Fry', 'A hot stir-fry of blistered green beans and shiitake in chili bean paste, with steamed rice. No oyster sauce and no nuts.', 4, 15, 20, 35, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'A large pot for rice. A wok or 12-inch skillet over high for the beans.', 'Beans blistered and tender-crisp, mushrooms softened, sauce glossy and clinging. Rice tender.', '["stir-fry"]', '[]', 'null', '[{"component_id":"sauce","name":"chili bean sauce","made_in_recipe":true,"store_bought":false,"ingredients":["chili bean paste","soy sauce","rice vinegar","sugar","cornstarch","water (1/2 cup)"]},{"component_id":"paste","name":"chili bean paste","made_in_recipe":false,"store_bought":true,"ingredients":["chili bean paste"],"contract":"Broad beans, chile, and soy. No shrimp or shellfish in the paste."},{"component_id":"rice","name":"steamed rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain rice","water (2 1/4 cups)"]}]', 'published', 'draft', 'global', NULL, 'cff9d7ef125f2fbc02f77393d91d0132b95833cb2839634493bde7548c28d83c', 'flavorweave-catalog-package', 'catalog/sichuan-green-bean-mushroom-stir-fry/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sichuan-mapo-tofu-shiitake_v1', 'rcp_sichuan-mapo-tofu-shiitake', 'sichuan-mapo-tofu-shiitake', 1, 'Sichuan Mapo Tofu with Shiitake and Jasmine Rice', 'Soft tofu cubes simmered in a glossy, numbing-hot sauce of broad bean chili paste, fermented black beans, garlic, ginger, and toasted Sichuan peppercorn, with finely chopped shiitake for a meaty bite. Served over jasmine rice with scallions.', 4, 10, 31, 41, 'moderate', 'adventurous', 'faa682b9a0717b5d4bda5d085b90e9d959a1bb70b759e3868f62c05f4a543240', 'Dry 12-inch skillet over medium-low to toast the peppercorns; medium-high to brown the shiitake; medium for the chili bean sauce and a gentle simmer for the tofu. 2-quart saucepan covered on low for the rice.', 'Shiitake browned and no longer wet. Sauce brick-red with oil beading at the edges. Tofu heated through and intact. Sauce coats a spoon after the slurry. Rice tender with separate grains.', '["toast","saute","simmer"]', '[]', 'null', '[{"component_id":"mapo","name":"mapo tofu with shiitake","made_in_recipe":true,"store_bought":false,"ingredients":["tofu","shiitake","doubanjiang","fermented black beans","garlic","ginger","Sichuan peppercorn","chili flakes","soy sauce","sugar","cornstarch","scallions"]},{"component_id":"rice","name":"steamed jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water","salt"]}]', 'published', 'draft', 'global', NULL, 'ddd97b7f1fac320bd8b1a1b1766fa31c4c5f23bd4041196ea64fe980b2218df4', 'flavorweave-catalog-package', 'catalog/sichuan-mapo-tofu-shiitake/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sicilian-pasta-alla-norma_v1', 'rcp_sicilian-pasta-alla-norma', 'sicilian-pasta-alla-norma', 1, 'Sicilian Pasta alla Norma with Golden Eggplant and Ricotta Salata', 'Rigatoni tossed in a garlicky tomato-basil sauce with cubes of eggplant shallow-fried in olive oil until golden outside and creamy inside, finished with grated ricotta salata and torn basil.', 4, 12, 32, 44, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '12-inch skillet over medium-high for the eggplant, medium for the sauce. 8-quart pot at a rolling boil for the pasta.', 'Eggplant golden-brown on most sides and creamy inside. Sauce thickened, no longer watery. Rigatoni al dente.', '["shallow-fry","simmer","boil"]', '[]', 'null', '[{"component_id":"eggplant","name":"shallow-fried eggplant","made_in_recipe":true,"store_bought":false,"ingredients":["eggplant","olive oil","salt"]},{"component_id":"sauce","name":"tomato-basil sauce","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","garlic","crushed red pepper","tomatoes","basil","salt"]},{"component_id":"pasta","name":"rigatoni","made_in_recipe":true,"store_bought":false,"ingredients":["rigatoni","water","salt"]}]', 'published', 'draft', 'global', NULL, '8cdb7225eb5c24da869d0ed89347a542939bec789ddf4e90848b5a07e7c7bcfa', 'flavorweave-catalog-package', 'catalog/sicilian-pasta-alla-norma/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_skillet-shakshuka_v1', 'rcp_skillet-shakshuka', 'skillet-shakshuka', 1, 'Skillet Shakshuka', 'Eggs set in a skillet of tomato and red pepper sauce made from crushed tomatoes, peppers, onion, and ground spices.', 4, 12, 26, 38, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Medium for the onion, peppers, and sauce. Medium-low, covered, for the eggs. No oven.', 'Sauce holds a well after about 10 minutes of simmering. Eggs: whites fully set, no liquid white, yolks soft and glossy. Do not flip them. Firm yolks need about 2 extra covered minutes and are not the written target. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"tomato-pepper-sauce","name":"tomato-pepper sauce","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","yellow onion","red bell pepper","garlic","sweet paprika","ground cumin","ground coriander","canned crushed tomatoes","water","sugar","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, 'b56017fba05a6fd07bca2595226312c9bdb20ae1aa71c318f215694ec9dd975e', 'flavorweave-catalog-package', 'catalog/skillet-shakshuka/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_slow-cooker-ropa-vieja_v1', 'rcp_slow-cooker-ropa-vieja', 'slow-cooker-ropa-vieja', 1, 'Slow-Cooker Cuban Ropa Vieja with White Rice', 'Beef chuck slow-cooked all day with peppers, onion, garlic, tomato, cumin, and oregano until it pulls into tender shreds, then finished with green olives and a splash of vinegar. Served over white rice with cilantro.', 4, 15, 497, 512, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Slow cooker on LOW for 8 hours. Covered low simmer for the rice.', 'Beef pulls apart easily with two forks (about 200 F internal); sauce thick enough to coat the shreds. Rice tender and dry.', '["slow-cook","simmer"]', '[]', 'null', '[{"component_id":"ropa-vieja","name":"slow-cooked shredded beef","made_in_recipe":true,"store_bought":false,"ingredients":["beef chuck","onion","bell peppers","garlic","tomato sauce","tomato paste","cumin","oregano","bay","olives","vinegar"]},{"component_id":"rice","name":"white rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain rice","water","salt"]}]', 'published', 'draft', 'global', NULL, 'e993d191ac5ef2f2552e999a6e7a5a738c6ead3d536b86487a43fb209b13548c', 'flavorweave-catalog-package', 'catalog/slow-cooker-ropa-vieja/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_smoky-lentil-sweet-potato-stew_v1', 'rcp_smoky-lentil-sweet-potato-stew', 'smoky-lentil-sweet-potato-stew', 1, 'Smoky Lentil Sweet Potato Stew', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["plant","dairy-free","stew"]', 'null', '[]', 'retired', 'published', 'global', NULL, '10eb898591fda56e7f3ba86278b8576332de90437729a0f5bb5a3a4cf5fa95f6', 'flavorweave-legacy-catalog-package', 'catalog/smoky-lentil-sweet-potato-stew/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_smoky-lentil-sweet-potato-stew_v2', 'rcp_smoky-lentil-sweet-potato-stew', 'smoky-lentil-sweet-potato-stew', 2, 'Smoky Lentil Sweet Potato Stew', NULL, 4, 15, 25, 40, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', NULL, 'Sweet potato cubes tender when pierced. Red lentils broken down. Stew thick enough to mound slightly after a partial mash, not a thin broth.', '["stovetop"]', '["plant","dairy-free"]', 'null', '[]', 'published', 'draft', 'global', NULL, '9eb6c1842c6e9e97dc75cafa0ace93f0d17d47b1cd6523a971bcdddc1b6d7dc5', 'flavorweave-legacy-catalog-package', 'catalog/smoky-lentil-sweet-potato-stew/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_south-african-bobotie_v1', 'rcp_south-african-bobotie', 'south-african-bobotie', 1, 'South African Bobotie with Yellow Rice and Tomato Sambal', 'Cape Malay comfort food: gently curried ground beef baked with apricot jam, raisins, and milk-soaked bread under a golden savory egg custard studded with bay leaves. Served with turmeric-and-cinnamon yellow rice and a fresh tomato-onion sambal.', 4, 15, 60, 75, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Oven preheated to 350 F. Medium skillet for the beef. Covered low simmer for the rice.', 'Custard set, puffed, and golden at the edges, with no liquid when the dish is tilted; filling 160 F. Rice tender and yellow.', '["saute","bake","simmer"]', '[]', 'null', '[{"component_id":"filling","name":"curried beef filling","made_in_recipe":true,"store_bought":false,"ingredients":["ground beef","onions","garlic","curry powder","turmeric","apricot jam","raisins","bread","milk","vinegar"]},{"component_id":"bread","name":"white sandwich bread","made_in_recipe":false,"store_bought":true,"ingredients":["white sandwich bread"],"contract":"Store-bought white sandwich bread whose label lists no soy (including soy flour or soy lecithin) and no sesame."},{"component_id":"custard","name":"egg custard with bay leaves","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","milk","bay leaves","turmeric"]},{"component_id":"rice","name":"yellow rice","made_in_recipe":true,"store_bought":false,"ingredients":["rice","turmeric","cinnamon stick","raisins","water"]},{"component_id":"sambal","name":"tomato-onion sambal","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","onion","vinegar","sugar"]}]', 'published', 'draft', 'global', NULL, 'cf46898e42947f7dd7263434fa5597bf29589d1a7188e69339d59cbe8b8e37ad', 'flavorweave-catalog-package', 'catalog/south-african-bobotie/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_south-indian-sambar-rice_v1', 'rcp_south-indian-sambar-rice', 'south-indian-sambar-rice', 1, 'South Indian Vegetable Sambar with Toor Dal and Steamed Rice', 'Toor dal simmered soft with turmeric, then cooked with carrots, eggplant, shallots, and tomatoes in a tangy tamarind broth seasoned with coriander and chili powder, finished with a sizzling tempering of mustard seeds, cumin seeds, dried chiles, and curry leaves, and served over basmati rice with cilantro.', 4, 12, 59, 71, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', '4-quart pot over high, then a gentle simmer, for the dal and sambar; 2-quart saucepan for the rice; small skillet over medium-high for the tempering.', 'Dal completely soft and collapsing when whisked; carrots and eggplant tender to a knife; sambar pourable but not watery.', '["simmer","steam"]', '[]', 'null', '[{"component_id":"sambar","name":"vegetable sambar","made_in_recipe":true,"store_bought":false,"ingredients":["toor dal","water","turmeric","carrots","eggplant","shallots","tomatoes","tamarind concentrate","ground coriander","chili powder","salt"]},{"component_id":"tempering","name":"tempering","made_in_recipe":true,"store_bought":false,"ingredients":["neutral oil","mustard seeds","cumin seeds","dried red chiles","curry leaves"]},{"component_id":"rice","name":"steamed basmati rice","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","water","salt"]}]', 'published', 'draft', 'global', NULL, 'aa93ce5f94bf08cb2de252774fc667626ff194f5b05b28e5a979fee22c02d6a7', 'flavorweave-catalog-package', 'catalog/south-indian-sambar-rice/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_southern-chicken-and-dumplings_v1', 'rcp_southern-chicken-and-dumplings', 'southern-chicken-and-dumplings', 1, 'Southern Chicken and Dumplings with Carrots, Celery, and Thyme', 'Chicken thighs simmered in chicken broth with onion, carrots, celery, thyme, and bay, thickened with a butter and flour roux, then topped with fluffy drop dumplings of flour, baking powder, milk, butter, and parsley steamed under the lid.', 4, 16, 53, 69, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '6-quart Dutch oven over medium, then low with the lid on.', 'Chicken 175 F; stew thick enough to coat a spoon; dumplings puffed, dry inside, and 200 F at the center.', '["saute","simmer","steam"]', '[]', 'null', '[{"component_id":"stew","name":"chicken stew","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","butter","yellow onion","carrots","celery","flour","chicken broth","thyme","bay leaf","salt","black pepper"]},{"component_id":"dumplings","name":"drop dumplings","made_in_recipe":true,"store_bought":false,"ingredients":["flour","baking powder","salt","whole milk","butter","parsley"]}]', 'published', 'draft', 'global', NULL, 'e5c4f8930eb95ffa1c99e4acac38337818a05fa6f0c28fc65ce3581163f41e26', 'flavorweave-catalog-package', 'catalog/southern-chicken-and-dumplings/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_southern-shrimp-and-grits_v1', 'rcp_southern-shrimp-and-grits', 'southern-shrimp-and-grits', 1, 'Shrimp and Grits with Smoky Garlic-Lemon Pan Sauce and Cheddar Grits', 'Old-fashioned grits simmered in milk and water until creamy, finished with sharp cheddar and butter, and topped with shrimp seared with smoked paprika and cayenne, then tossed with garlic, scallions, and lemon in a buttery pan sauce.', 4, 10, 29, 39, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '3-quart saucepan brought to a boil over medium-high, then low with frequent whisking for the grits. 12-inch skillet over medium-high for the shrimp, medium for the pan sauce.', 'Grits thick, creamy, and tender with no raw bite. Shrimp pink and opaque throughout (145 F), curled into a loose C. Pan sauce glossy.', '["simmer","sear"]', '[]', 'null', '[{"component_id":"grits","name":"cheddar grits","made_in_recipe":true,"store_bought":false,"ingredients":["grits","water","milk","salt","cheddar","butter"]},{"component_id":"shrimp","name":"smoky garlic-lemon shrimp","made_in_recipe":true,"store_bought":false,"ingredients":["shrimp","smoked paprika","cayenne","olive oil","butter","garlic","scallions","lemon","water"]}]', 'published', 'draft', 'global', NULL, 'ff26c11d738a579f77ac05cd4a43b15ca6f4ba2916392d26d13cde959a1e111f', 'flavorweave-catalog-package', 'catalog/southern-shrimp-and-grits/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_southern-smothered-pork-chops_v1', 'rcp_southern-smothered-pork-chops', 'southern-smothered-pork-chops', 1, 'Southern Smothered Pork Chops in Onion Gravy with Rice and Green Beans', 'Bone-in pork chops seasoned and lightly floured, browned, then smothered and braised in a rich brown onion gravy until tender. Served over white rice with garlicky skillet green beans.', 4, 14, 64, 78, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-high in a 12-inch skillet with a lid to brown, medium to cook the onions and roux, then a covered low simmer. Medium-high in a second skillet for the green beans. Low covered heat for the rice.', 'Chops 145 F or higher and tender after the braise. Gravy smooth, brown, and thick enough to coat a spoon. Green beans crisp-tender.', '["sear","braise","saute"]', '[]', 'null', '[{"component_id":"chops","name":"smothered pork chops","made_in_recipe":true,"store_bought":false,"ingredients":["pork chops","flour","paprika","garlic powder","onion powder","onions","water","oil"]},{"component_id":"rice","name":"white rice","made_in_recipe":true,"store_bought":false,"ingredients":["rice","water"]},{"component_id":"green-beans","name":"skillet green beans","made_in_recipe":true,"store_bought":false,"ingredients":["green beans","garlic","oil"]}]', 'published', 'draft', 'global', NULL, '2594b16e135d5fea35c5644c3e9f7f774fb944e4f6b7838dd73a9d2de4ddd096', 'flavorweave-catalog-package', 'catalog/southern-smothered-pork-chops/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_spaghetti-puttanesca_v1', 'rcp_spaghetti-puttanesca', 'spaghetti-puttanesca', 1, 'Spaghetti Puttanesca', 'Spaghetti tossed in a quick, punchy tomato sauce built on olive oil-melted anchovies, garlic, and chile flakes, with Kalamata olives and capers, finished with parsley and a last splash of olive oil. Egg-free dried pasta; no cheese, no butter.', 4, 10, 16, 26, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'High heat for the pasta water; medium for the anchovy-garlic bloom; brisk simmer (medium to medium-high) for the sauce; medium-high to toss. No oven.', 'Anchovies fully dissolved; garlic pale gold, not brown. Sauce thick enough to cling, glossy with oil at the edges. Spaghetti al dente with sauce on every strand. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"puttanesca-sauce","name":"anchovy-olive-caper tomato sauce","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","anchovy fillets","garlic","red pepper flakes","tomato paste","whole peeled tomatoes","kalamata olives","capers","dried oregano"]},{"component_id":"spaghetti","name":"spaghetti cooked al dente","made_in_recipe":true,"store_bought":false,"ingredients":["spaghetti","salted water"]}]', 'published', 'draft', 'global', NULL, 'e7861ae73533cbfdfb1fb39f4cd8405f55ba156188b986e0e2d343eabbc2e18d', 'flavorweave-catalog-package', 'catalog/spaghetti-puttanesca/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_spanish-chorizo-pepper-rice_v1', 'rcp_spanish-chorizo-pepper-rice', 'spanish-chorizo-pepper-rice', 1, 'Spanish Chorizo and Pepper Rice', 'One-pan Spanish-style rice cooked with sliced cured chorizo, blistered peppers, onion, garlic, smoked paprika, and tomatoes.', 4, 12, 33, 45, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium for browning chorizo and peppers; medium-high to bring to simmer; low covered for absorb. No oven. No grill.', 'Rice tender and liquid absorbed after covered cook plus 5-minute rest. Peppers blistered at edges. Chorizo browned. No raw crunchy rice. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"chorizo-pepper-sofrito","name":"chorizo-pepper sofrito base","made_in_recipe":true,"store_bought":false,"ingredients":["Spanish chorizo","yellow onion","red bell pepper","green bell pepper","garlic","smoked paprika","ground cumin","olive oil"]},{"component_id":"one-pan-arroz","name":"one-pan Spanish-style rice","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","crushed tomatoes","stock","chorizo-pepper sofrito"]}]', 'published', 'draft', 'global', NULL, 'a6a09635408919abd854ae6f018194487a26739f855a39932c4d852cb72d8d6e', 'flavorweave-catalog-package', 'catalog/spanish-chorizo-pepper-rice/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_spanish-potato-tortilla_v1', 'rcp_spanish-potato-tortilla', 'spanish-potato-tortilla', 1, 'Spanish Potato Tortilla', 'Yukon Gold potatoes and onion shallow-fried in olive oil, folded into egg, and set in a skillet. No cheese and no chorizo.', 4, 15, 30, 45, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', 'Medium for the potatoes, then medium-low to set the eggs. No oven.', 'Potatoes tender, not browned hard. Tortilla set at the edge, the center just firm, not dry. A knife comes out with a moist crumb.', '["shallow-fry"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'c14043513d18efb271a0a988320ad58ce1299152b3f9b282a8b63920c751ab10', 'flavorweave-catalog-package', 'catalog/spanish-potato-tortilla/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_spanish-sopa-de-ajo-egg_v1', 'rcp_spanish-sopa-de-ajo-egg', 'spanish-sopa-de-ajo-egg', 1, 'Castilian Garlic Soup with Poached Eggs and Spinach', 'Sopa de ajo: golden sliced garlic and chunks of crusty bread toasted in olive oil, bloomed with smoked pimentón, simmered in vegetable stock with spinach, and finished by poaching eggs right in the soup. A sherry-vinegar splash brightens it.', 4, 8, 20, 28, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Medium-low to toast the garlic and bread; medium simmer; low, barely bubbling for poaching the eggs.', 'Garlic pale gold, not brown; bread softened in the broth but still in pieces; egg whites set and yolks runny.', '["saute","simmer","poach"]', '[]', 'null', '[{"component_id":"soup","name":"garlic soup with eggs","made_in_recipe":true,"store_bought":false,"ingredients":["garlic","bread","smoked paprika","vegetable stock","spinach","eggs","parsley","sherry vinegar","olive oil"]}]', 'published', 'draft', 'global', NULL, '5abaaee7f2a8cab1a9548edaf1e1644bb332958a53ad49f5e464b77f11fec6aa', 'flavorweave-catalog-package', 'catalog/spanish-sopa-de-ajo-egg/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_spiced-lamb-meatballs_v1', 'rcp_spiced-lamb-meatballs', 'spiced-lamb-meatballs', 1, 'Spiced Lamb Meatballs with Tomato-Herb Sauce', 'Lamb meatballs seasoned with cumin, coriander, mint, and parsley, browned and simmered in a skillet tomato-herb sauce.', 4, 18, 28, 46, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium-high to brown. Medium for sauce aromatics. Medium-low simmer for meatballs in sauce. No oven.', 'Meatball centers 160 F. Sauce slightly thickened, spoon-coating. Herbs fresh at the finish. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"spiced-lamb-meatballs","name":"spiced lamb meatballs","made_in_recipe":true,"store_bought":false,"ingredients":["ground lamb","egg","panko breadcrumbs","yellow onion","garlic","fresh parsley","fresh mint","ground cumin","ground coriander","sweet paprika","red pepper flakes","kosher salt","black pepper"]},{"component_id":"tomato-herb-sauce","name":"tomato-herb sauce","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","yellow onion","garlic","tomato paste","canned crushed tomatoes","water","kosher salt","fresh parsley"]}]', 'published', 'draft', 'global', NULL, '340caffc461b9455aa207747cbf716a7d2792d3ef17cb672e4dd2ad713437f95', 'flavorweave-catalog-package', 'catalog/spiced-lamb-meatballs/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_steak-au-poivre-smashed-potatoes_v1', 'rcp_steak-au-poivre-smashed-potatoes', 'steak-au-poivre-smashed-potatoes', 1, 'Steak au Poivre with Crispy Smashed Potatoes', 'Strip steaks pressed into cracked black peppercorns, seared to a dark crust, and finished with a classic French pan sauce of shallot, brandy, Dijon, and cream. Served with baby potatoes boiled, smashed, and oven-roasted until crispy.', 4, 10, 49, 59, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Oven preheated to 450 F for the potatoes. High heat cast iron for the steaks; medium for the sauce.', 'Steaks 130 F for medium-rare after resting. Potatoes deep golden and crisp at the edges. Sauce reduced until it coats a spoon.', '["boil","roast","sear"]', '[]', 'null', '[{"component_id":"steak","name":"peppercorn-crusted strip steaks with pan sauce","made_in_recipe":true,"store_bought":false,"ingredients":["strip steaks","black peppercorns","shallot","brandy","Dijon","cream","butter","salt","oil"]},{"component_id":"potatoes","name":"crispy smashed potatoes","made_in_recipe":true,"store_bought":false,"ingredients":["baby potatoes","water","olive oil","salt","chives"]}]', 'published', 'draft', 'global', NULL, 'b98614e66b76087d16f57cad934943845a6da91cca09dece14c440046853fd1f', 'flavorweave-catalog-package', 'catalog/steak-au-poivre-smashed-potatoes/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_swedish-meatballs-lingonberry_v1', 'rcp_swedish-meatballs-lingonberry', 'swedish-meatballs-lingonberry', 1, 'Swedish Meatballs in Cream Gravy with Lingonberry and Dill Potatoes', 'Tender beef and pork meatballs scented with allspice, browned in butter and simmered in a silky cream gravy with a touch of Dijon, served with boiled potatoes tossed in dill and a spoonful of tart lingonberry jam.', 4, 20, 26, 46, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium to brown the meatballs; medium to cook the roux; low simmer for the meatballs in gravy; boil for the potatoes.', 'Meatballs browned and 160 F in the center. Gravy coats a spoon. Potatoes tender to a knife tip.', '["saute","simmer","boil"]', '[]', 'null', '[{"component_id":"meatballs","name":"meatballs","made_in_recipe":true,"store_bought":false,"ingredients":["ground beef","ground pork","panko","milk","egg","onion","allspice","salt","pepper"]},{"component_id":"gravy","name":"cream gravy","made_in_recipe":true,"store_bought":false,"ingredients":["butter","flour","beef stock","cream","dijon"]},{"component_id":"potatoes","name":"dill potatoes","made_in_recipe":true,"store_bought":false,"ingredients":["potatoes","water","salt","dill"]},{"component_id":"jam","name":"lingonberry jam","made_in_recipe":false,"store_bought":true,"ingredients":["lingonberry jam"]}]', 'published', 'draft', 'global', NULL, '6bf721a90331c8e6b0163e04d08caf97f7ebefba542814adf8e64df1a23a5956', 'flavorweave-catalog-package', 'catalog/swedish-meatballs-lingonberry/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_swedish-pytt-i-panna_v1', 'rcp_swedish-pytt-i-panna', 'swedish-pytt-i-panna', 1, 'Swedish Pytt i Panna Ham and Potato Hash with Pan-Fried Eggs and Pickled Beets', 'Diced Yukon Gold potatoes browned crisp in butter and oil with onion, diced ham, and smoked kielbasa, topped with pan-fried eggs, and served with pickled beets and chopped parsley.', 4, 15, 47, 62, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '12-inch nonstick or cast-iron skillet over medium; a second 10-inch nonstick skillet for the eggs.', 'Potatoes tender inside and browned on several sides; meat browned at the edges; egg whites set with runny or firm yolks as preferred.', '["saute","pan-fry"]', '[]', 'null', '[{"component_id":"hash","name":"pytt i panna","made_in_recipe":true,"store_bought":false,"ingredients":["Yukon Gold potatoes","neutral oil","butter","yellow onion","ham","kielbasa","salt","black pepper"]},{"component_id":"eggs","name":"pan-fried eggs","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","butter"]},{"component_id":"serve","name":"beets and parsley","made_in_recipe":true,"store_bought":false,"ingredients":["pickled beets","parsley"]}]', 'published', 'draft', 'global', NULL, '4d153436625ad4f0064e2712ee9c95d243177cb4441014d4bdf209055a94deeb', 'flavorweave-catalog-package', 'catalog/swedish-pytt-i-panna/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_swiss-raclette-potatoes-pickles_v1', 'rcp_swiss-raclette-potatoes-pickles', 'swiss-raclette-potatoes-pickles', 1, 'Swiss Raclette Night: Melted Raclette over Potatoes with Cornichons and Pickled Onions', 'A home version of the Valais classic: slices of raclette cheese melted under the broiler until bubbling and blistered, scraped over hot boiled new potatoes, and eaten with cornichons, pickled pearl onions, and a crisp green salad with mustard vinaigrette.', 4, 10, 44, 54, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'A 6-quart pot at a boil for the potatoes. Broiler preheated on high for 5 minutes with the rack 6 inches below the element.', 'Potatoes tender all the way through. Cheese fully melted, bubbling, and blistered golden in spots.', '["boil","broil"]', '[]', 'null', '[{"component_id":"potatoes","name":"boiled new potatoes","made_in_recipe":true,"store_bought":false,"ingredients":["new potatoes","water","salt"]},{"component_id":"raclette","name":"melted raclette","made_in_recipe":true,"store_bought":false,"ingredients":["raclette cheese","black pepper","paprika"]},{"component_id":"pickles","name":"cornichons and pickled onions","made_in_recipe":false,"store_bought":true,"ingredients":["cornichons","pickled pearl onions"]},{"component_id":"salad","name":"green salad","made_in_recipe":true,"store_bought":false,"ingredients":["butter lettuce","Dijon","white wine vinegar","olive oil"]}]', 'published', 'draft', 'global', NULL, '2e4d93015dc94ebd80c9070144a579e17987dbeb13d93fce51a10f4954ee8cc1', 'flavorweave-catalog-package', 'catalog/swiss-raclette-potatoes-pickles/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_swiss-rosti-smoked-trout_v1', 'rcp_swiss-rosti-smoked-trout', 'swiss-rosti-smoked-trout', 1, 'Swiss Rösti with Smoked Trout and Dill-Caper Salad', 'One large golden potato rösti, pan-fried in oil until shatteringly crisp outside and tender inside, cut into wedges and topped with flaked smoked trout and a lemony arugula, cucumber, radish, dill, and caper salad in a Dijon vinaigrette.', 4, 15, 31, 46, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high to set the rösti crust, then medium for even cooking; repeat on the second side.', 'Deep golden-brown and crisp on both sides; a knife slides through the center with no raw crunch.', '["pan-fry"]', '[]', 'null', '[{"component_id":"rosti","name":"potato rösti","made_in_recipe":true,"store_bought":false,"ingredients":["Yukon Gold potatoes","shallot","salt","pepper","oil"]},{"component_id":"trout","name":"hot-smoked trout","made_in_recipe":false,"store_bought":true,"ingredients":["smoked trout"]},{"component_id":"salad","name":"dill-caper salad","made_in_recipe":true,"store_bought":false,"ingredients":["arugula","cucumber","radishes","dill","capers","Dijon","lemon","olive oil"]}]', 'published', 'draft', 'global', NULL, '085de9baf2dac1437bab1cd3f10df32f1fc05236ad72ba38a47f025ef8eff49a', 'flavorweave-catalog-package', 'catalog/swiss-rosti-smoked-trout/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_taiwanese-beef-noodle-soup_v1', 'rcp_taiwanese-beef-noodle-soup', 'taiwanese-beef-noodle-soup', 1, 'Taiwanese Red-Braised Beef Noodle Soup', 'Taiwan''s national dish: beef shank braised for two hours in a deep, spicy broth of chili bean paste, soy, star anise, Sichuan peppercorn, cinnamon, ginger, and tomato, ladled over chewy wheat noodles with baby bok choy, pickled mustard greens, scallions, and cilantro.', 4, 20, 153, 173, 'moderate', 'adventurous', 'faa682b9a0717b5d4bda5d085b90e9d959a1bb70b759e3868f62c05f4a543240', 'Rolling boil to blanch the beef; medium to cook the aromatics in oil; low covered braise.', 'Beef shank fork-tender and gelatinous; broth deep red-brown and fragrant; noodles chewy-tender; bok choy bright green.', '["boil","saute","braise"]', '[]', 'null', '[{"component_id":"braise","name":"red-braised beef and broth","made_in_recipe":true,"store_bought":false,"ingredients":["beef shank","doubanjiang","soy sauce","brown sugar","star anise","Sichuan peppercorns","cinnamon","ginger","garlic","scallions","onion","tomatoes","water","oil"]},{"component_id":"noodles","name":"wheat noodles and bok choy","made_in_recipe":true,"store_bought":false,"ingredients":["wheat noodles","bok choy","water"]},{"component_id":"toppings","name":"pickled mustard greens, scallions, cilantro","made_in_recipe":false,"store_bought":true,"ingredients":["pickled mustard greens","scallions","cilantro"]}]', 'published', 'draft', 'global', NULL, 'bddac34d50b8c01cbe3b6427aaa51f5432cbdf5f337c0ce3cc9495497ab160ee', 'flavorweave-catalog-package', 'catalog/taiwanese-beef-noodle-soup/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_taiwanese-lu-rou-fan_v1', 'rcp_taiwanese-lu-rou-fan', 'taiwanese-lu-rou-fan', 1, 'Taiwanese Lu Rou Fan: Braised Pork Belly over Rice with Soy Eggs and Bok Choy', 'Diced skinless pork belly browned with golden shallots and garlic, then braised in soy sauce, dark soy sauce, Shaoxing wine, brown sugar, and five-spice with peeled boiled eggs until glossy and tender, spooned over short-grain rice with garlicky baby bok choy.', 4, 15, 82, 97, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '5.5-quart Dutch oven over medium, then low and covered; 2-quart saucepans for the eggs and rice; 12-inch skillet for the bok choy.', 'Pork belly tender and the fat translucent; sauce glossy and lightly sticky; eggs stained mahogany.', '["boil","saute","braise","steam"]', '[]', 'null', '[{"component_id":"eggs","name":"boiled eggs","made_in_recipe":true,"store_bought":false,"ingredients":["eggs","water"]},{"component_id":"pork","name":"braised pork","made_in_recipe":true,"store_bought":false,"ingredients":["pork belly","neutral oil","shallots","garlic","soy sauce","dark soy sauce","Shaoxing wine","brown sugar","five-spice powder","water"]},{"component_id":"rice","name":"rice","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","water"]},{"component_id":"greens","name":"bok choy","made_in_recipe":true,"store_bought":false,"ingredients":["baby bok choy","neutral oil","garlic","water","salt"]}]', 'published', 'draft', 'global', NULL, 'b5642cac59eecfd28f59169e6522bf007ba131e220955bec159562bceff959d4', 'flavorweave-catalog-package', 'catalog/taiwanese-lu-rou-fan/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_taiwanese-three-cup-mushrooms_v1', 'rcp_taiwanese-three-cup-mushrooms', 'taiwanese-three-cup-mushrooms', 1, 'Taiwanese Three-Cup King Oyster Mushrooms with Jasmine Rice', 'Thick king oyster mushroom rounds seared until deeply browned, then glazed in the classic three-cup sauce of toasted sesame oil, soy sauce, and Shaoxing wine with a heap of ginger, whole garlic cloves, and Thai basil. Served with jasmine rice and blanched bok choy.', 4, 12, 27, 39, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high in a 12-inch skillet to sear, medium for the aromatics, then a fast reducing simmer. A rolling boil for the bok choy. Low covered heat for the rice.', 'Mushrooms deeply browned on both cut faces and tender; sauce reduced to a sticky glaze that coats them; basil just wilted. Bok choy bright green and crisp-tender.', '["sear","braise","boil"]', '[]', 'null', '[{"component_id":"three-cup","name":"three-cup mushrooms","made_in_recipe":true,"store_bought":false,"ingredients":["king oyster mushrooms","sesame oil","soy sauce","Shaoxing wine","ginger","garlic","chiles","Thai basil"]},{"component_id":"rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]},{"component_id":"bok-choy","name":"blanched bok choy","made_in_recipe":true,"store_bought":false,"ingredients":["baby bok choy","water","salt"]}]', 'published', 'draft', 'global', NULL, '2d9674739b67192a38d94fbb4d46aa17ef91604a202925832fc473fbd9bf5b93', 'flavorweave-catalog-package', 'catalog/taiwanese-three-cup-mushrooms/v1.json', '2026-10-04T00:00:00.000Z');
