INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_tex-mex-steak-fajitas_v1', 'rcp_tex-mex-steak-fajitas', 'tex-mex-steak-fajitas', 1, 'Tex-Mex Skirt Steak Fajitas with Peppers, Onions, and Pico de Gallo', 'Skirt steak marinated in lime juice, garlic, cumin, and chili powder, seared hard in cast iron and sliced across the grain, served with charred bell peppers and onion, warm flour tortillas, fresh pico de gallo of tomato, onion, jalapeno, and cilantro, avocado, and sour cream.', 4, 20, 30, 50, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '12-inch cast-iron skillet over high.', 'Steak deeply browned outside and 130 to 135 F for medium-rare; peppers charred at the edges but still crisp-tender.', '["sear","saute","toast"]', '[]', 'null', '[{"component_id":"steak","name":"steak","made_in_recipe":true,"store_bought":false,"ingredients":["skirt steak","lime juice","garlic","cumin","chili powder","neutral oil","salt"]},{"component_id":"peppers","name":"peppers and onions","made_in_recipe":true,"store_bought":false,"ingredients":["bell peppers","white onion","neutral oil","salt"]},{"component_id":"pico","name":"pico de gallo","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","white onion","jalapeno","cilantro","lime juice","salt"]},{"component_id":"serve","name":"tortillas and toppings","made_in_recipe":true,"store_bought":false,"ingredients":["flour tortillas","avocado","sour cream"]}]', 'published', 'draft', 'global', NULL, '2a62f037b234bed23bdf7c1ecdd616f342a2d25cea672ab4dfd3f7f79fe89bb3', 'flavorweave-catalog-package', 'catalog/tex-mex-steak-fajitas/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-basil-eggplant-stir-fry_v1', 'rcp_thai-basil-eggplant-stir-fry', 'thai-basil-eggplant-stir-fry', 1, 'Thai Basil Eggplant Stir-Fry', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["plant","dairy-free"]', 'null', '[]', 'retired', 'published', 'global', NULL, '29062adb3a9e3ea6b0411d3378cd7a58e2b0472e8e06199b9091ae0c6f3ea08e', 'flavorweave-legacy-catalog-package', 'catalog/thai-basil-eggplant-stir-fry/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-basil-eggplant-stir-fry_v2', 'rcp_thai-basil-eggplant-stir-fry', 'thai-basil-eggplant-stir-fry', 2, 'Thai Basil Eggplant Stir-Fry', 'Browned Japanese eggplant and wilted Thai basil over jasmine rice, seasoned with soy sauce and garlic.', 4, 15, 25, 40, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'none', 'Eggplant browned and tender, center creamy with no raw white spongy core. Basil wilted, not blackened. Rice tender.', '["stovetop"]', '["plant","dairy-free"]', '{"soy sauce":"Keep wheat-containing soy sauce. Wheat-free tamari would drop the wheat allergen and is not this version.","fish sauce":"Do not substitute fish sauce. It would drop the plant claim and add finfish."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, 'c07864661aac95b2f645c4a7357180a9a21d6c166b8389dfa88bcc543c455fc6', 'flavorweave-legacy-catalog-package', 'catalog/thai-basil-eggplant-stir-fry/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-crispy-barramundi-tamarind_v1', 'rcp_thai-crispy-barramundi-tamarind', 'thai-crispy-barramundi-tamarind', 1, 'Thai Crispy Barramundi with Three-Flavor Tamarind Sauce', 'Barramundi pieces dredged in rice flour and cornstarch and deep-fried until shatteringly crisp, then spooned with a Thai three-flavor sauce (sweet, sour, and spicy) of tamarind, palm or brown sugar, fish sauce, garlic, shallots, and chiles. Served with jasmine rice and cucumber.', 4, 12, 34, 46, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', '6 cups oil at 350 F in a 5-quart Dutch oven; hold between 340 F and 360 F. A small saucepan at medium for the sauce. Low covered heat for the rice.', 'Coating deep golden and crisp; fish opaque inside and 145 F. Sauce glossy and syrupy, coating a spoon.', '["deep-fry","simmer"]', '[]', 'null', '[{"component_id":"fish","name":"crispy barramundi","made_in_recipe":true,"store_bought":false,"ingredients":["barramundi","rice flour","cornstarch","oil"]},{"component_id":"sauce","name":"three-flavor tamarind sauce","made_in_recipe":true,"store_bought":false,"ingredients":["tamarind","brown sugar","fish sauce","garlic","shallots","chiles","water"]},{"component_id":"rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]}]', 'published', 'draft', 'global', NULL, '48ad5c4623f869734c960f5866e2f357b2d54d8429e1b5de04bdfaf705f522b1', 'flavorweave-catalog-package', 'catalog/thai-crispy-barramundi-tamarind/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-fish-cakes-cucumber-relish_v1', 'rcp_thai-fish-cakes-cucumber-relish', 'thai-fish-cakes-cucumber-relish', 1, 'Thai Fish Cakes with Cucumber Relish', 'Springy, curry-red Thai fish cakes of ground white fish, shrimp-paste-free red curry paste, fish sauce, lime, and sliced green beans, pan-fried until crisp at the edges and served with a sweet-sour cucumber-shallot relish and jasmine rice. No peanuts, no shellfish.', 4, 15, 28, 43, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'High to boil the rice, then low; medium-high skillet for shallow-frying. No oven.', 'Cakes puffed, deep golden with crisp edges, opaque and springy in the center (145 F). Rice tender and fluffy. Relish crisp, sweet-sour, and lightly hot. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"red-curry-fish-cakes","name":"red curry fish cakes","made_in_recipe":true,"store_bought":false,"ingredients":["white fish","shrimp-paste-free red curry paste","fish sauce","egg","sugar","green beans","lime zest","makrut lime leaves (optional)","neutral oil"]},{"component_id":"cucumber-relish","name":"sweet-sour cucumber relish (ajad)","made_in_recipe":true,"store_bought":false,"ingredients":["English cucumber","shallot","red chile","rice vinegar","sugar","kosher salt","warm water","cilantro"]},{"component_id":"jasmine-rice","name":"steamed jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]}]', 'published', 'draft', 'global', NULL, 'ff662722f0d9cfecce6c55457cf91272f06bcaa75409eb8d4ac2650905bd6c29', 'flavorweave-catalog-package', 'catalog/thai-fish-cakes-cucumber-relish/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-khao-man-gai_v1', 'rcp_thai-khao-man-gai', 'thai-khao-man-gai', 1, 'Thai Khao Man Gai: Poached Chicken and Garlic-Ginger Rice with Soybean Sauce', 'Bangkok''s hawker classic: chicken thighs gently poached with ginger and cilantro stems, jasmine rice cooked in the poaching broth with garlic and ginger, and a punchy sauce of fermented soybean paste, ginger, garlic, chile, and vinegar. Served with cucumber and a cup of the broth.', 4, 12, 76, 88, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'A bare simmer in a 6-quart pot for the chicken, never a rolling boil. Medium in a 3-quart saucepan to toast the rice, then low and covered.', 'Chicken 175 F at the thickest part of the thigh, juicy and just set. Rice tender, glossy, and fragrant. Broth clear.', '["poach","saute","simmer"]', '[]', 'null', '[{"component_id":"chicken","name":"poached chicken","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","ginger","cilantro stems","water","salt"]},{"component_id":"rice","name":"garlic-ginger rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","garlic","ginger","poaching broth"]},{"component_id":"sauce","name":"soybean dipping sauce","made_in_recipe":true,"store_bought":false,"ingredients":["fermented soybean paste","ginger","garlic","chile","soy sauce","vinegar","sugar"]},{"component_id":"sides","name":"cucumber and broth","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber","broth","cilantro"]}]', 'published', 'draft', 'global', NULL, 'a3b9bb00b4237e5bde2ce4703f0d214c1884c953ed3007bae4a938e00bf72495', 'flavorweave-catalog-package', 'catalog/thai-khao-man-gai/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-moo-ping-sticky-rice_v1', 'rcp_thai-moo-ping-sticky-rice', 'thai-moo-ping-sticky-rice', 1, 'Thai Moo Ping: Grilled Pork Skewers with Sticky Rice and Jaew Dipping Sauce', 'Bangkok street-style pork skewers: thin slices of pork shoulder marinated in garlic, cilantro stems, white pepper, palm sugar, soy sauce, fish sauce, and coconut milk, grilled and basted until caramelized. Served with steamed sticky rice, cucumber, and a tangy chile-lime jaew sauce with toasted rice powder.', 4, 20, 102, 122, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Grill preheated on medium-high for 10 minutes, about 425 F at the grate. A covered steamer over a steady boil for the sticky rice. A dry 8-inch skillet over medium to toast the rice for the jaew.', 'Pork caramelized and charred at the edges and 145 F. Sticky rice translucent, chewy, and tender all the way through.', '["grill","steam"]', '[]', 'null', '[{"component_id":"moo-ping","name":"grilled pork skewers","made_in_recipe":true,"store_bought":false,"ingredients":["pork shoulder","garlic","cilantro stems","white pepper","palm sugar","soy sauce","fish sauce","coconut milk"]},{"component_id":"sticky-rice","name":"steamed sticky rice","made_in_recipe":true,"store_bought":false,"ingredients":["glutinous rice","water"]},{"component_id":"jaew","name":"jaew dipping sauce","made_in_recipe":true,"store_bought":false,"ingredients":["fish sauce","lime","chile flakes","toasted rice powder","shallot","cilantro"]},{"component_id":"cucumber","name":"cucumber","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber"]}]', 'published', 'draft', 'global', NULL, '2ff20bd8d8890e951bc94597b17785f459d555ff628d4ca5a87754c8fb3a0f66', 'flavorweave-catalog-package', 'catalog/thai-moo-ping-sticky-rice/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-pad-see-ew-tofu_v1', 'rcp_thai-pad-see-ew-tofu', 'thai-pad-see-ew-tofu', 1, 'Thai Pad See Ew with Tofu, Broccoli, and Egg', 'Wide rice noodles stir-fried over high heat with seared extra-firm tofu, broccoli, garlic, and scrambled eggs in a sweet-salty sauce of dark soy sauce, soy sauce, brown sugar, and rice vinegar, finished with white pepper.', 4, 10, 31, 41, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '4-quart pot for the noodles; 12-inch nonstick skillet over medium-high for the tofu, then high for the noodles.', 'Noodles tender-chewy with dark caramelized patches; tofu golden on several sides; broccoli bright green and crisp-tender; egg in soft set pieces.', '["boil","sear","stir-fry"]', '[]', 'null', '[{"component_id":"noodles","name":"rice noodles","made_in_recipe":true,"store_bought":false,"ingredients":["wide rice noodles","water","neutral oil"]},{"component_id":"tofu","name":"seared tofu","made_in_recipe":true,"store_bought":false,"ingredients":["extra-firm tofu","neutral oil"]},{"component_id":"stir-fry","name":"pad see ew","made_in_recipe":true,"store_bought":false,"ingredients":["garlic","broccoli","water","eggs","dark soy sauce","soy sauce","brown sugar","rice vinegar","white pepper"]}]', 'published', 'draft', 'global', NULL, '0bcd7732a22a67cf204a6a128ae74364fb52e09f393e626ddfa292de507a9a5d', 'flavorweave-catalog-package', 'catalog/thai-pad-see-ew-tofu/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-red-curry-kabocha_v1', 'rcp_thai-red-curry-kabocha', 'thai-red-curry-kabocha', 1, 'Thai Red Curry with Kabocha and Tofu', 'Kabocha squash and browned tofu simmered in a coconut red curry built from vegetarian Thai red curry paste — no fish sauce, no dairy.', 4, 20, 35, 55, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high to brown tofu. Medium to bloom paste and simmer curry. Rice: covered simmer then rest. No oven.', 'Kabocha tender when pierced. Tofu golden on edges. Spinach wilted. Curry cohesive, coconut-red, not broken. Rice fluffy. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"thai-red-coconut-curry","name":"Thai red coconut curry","made_in_recipe":true,"store_bought":false,"ingredients":["coconut oil","vegetarian/vegan Thai red curry paste","full-fat coconut milk","water","light brown sugar","kosher salt","kabocha squash","red bell pepper","extra-firm tofu","baby spinach","lime juice","fresh Thai basil"]},{"component_id":"jasmine-rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["uncooked jasmine rice","water"]}]', 'published', 'draft', 'global', NULL, '2364e9750ed832e7594c0822ca2e85374c133181a776e21555e6be1016782121', 'flavorweave-catalog-package', 'catalog/thai-red-curry-kabocha/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-turkey-larb-lettuce-wraps_v1', 'rcp_thai-turkey-larb-lettuce-wraps', 'thai-turkey-larb-lettuce-wraps', 1, 'Thai Turkey Larb Lettuce Wraps', 'Ground turkey cooked into fine crumbles and dressed warm with lime juice, fish sauce, and chile flakes, then tossed with shallots, scallions, a fistful of mint and cilantro, and nutty homemade toasted rice powder. Spooned into butter lettuce cups with cool cucumber. Bright, herby, and on the table in under 30 minutes.', 4, 10, 19, 29, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', 'Stovetop only. Medium dry heat to toast the rice; medium-high for the turkey. Dressing goes in off the heat. No oven.', 'Rice powder deep golden and nutty; turkey in fine crumbles, no pink (165 F), liquid evaporated; herbs bright and just barely wilted from the residual warmth. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"toasted-rice-powder","name":"toasted rice powder (khao khua)","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice"]},{"component_id":"turkey-larb","name":"lime-chile turkey larb","made_in_recipe":true,"store_bought":false,"ingredients":["ground turkey","neutral oil","water","fish sauce","lime juice","sugar","dried chile flakes","shallots","scallions","fresh mint","cilantro","toasted rice powder"]},{"component_id":"wraps","name":"butter lettuce cups with cucumber and lime","made_in_recipe":true,"store_bought":false,"ingredients":["butter lettuce","English cucumber","lime wedges"]}]', 'published', 'draft', 'global', NULL, '84a1fec19cd634c18bcbf08672d7323e31ee8de49246b4b284de1f88447b4f88', 'flavorweave-catalog-package', 'catalog/thai-turkey-larb-lettuce-wraps/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-yum-nua-beef-salad_v1', 'rcp_thai-yum-nua-beef-salad', 'thai-yum-nua-beef-salad', 1, 'Thai Yum Nua: Seared Steak Salad with Lime-Chile Dressing and Jasmine Rice', 'Flank steak seared hard in a cast-iron skillet, rested, sliced thin, and tossed warm with cucumber, cherry tomatoes, shallots, scallions, mint, and cilantro in a sharp lime, fish sauce, garlic, and bird chile dressing, piled over romaine with jasmine rice on the side.', 4, 12, 30, 42, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', '10- or 12-inch cast-iron skillet over high until smoking for the steak. 2-quart saucepan covered on low for the rice.', 'Steak deeply browned outside and 130 F for medium-rare at the thickest point (USDA safe minimum is 145 F with a 3-minute rest). Vegetables raw and crisp; herbs fresh, not wilted. Rice tender.', '["sear"]', '[]', 'null', '[{"component_id":"steak","name":"seared flank steak","made_in_recipe":true,"store_bought":false,"ingredients":["flank steak","salt","black pepper","neutral oil"]},{"component_id":"dressing","name":"lime-chile dressing","made_in_recipe":true,"store_bought":false,"ingredients":["lime","fish sauce","brown sugar","bird chiles","garlic"]},{"component_id":"salad","name":"herb salad","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber","cherry tomatoes","shallots","scallions","mint","cilantro","romaine"]},{"component_id":"rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water","salt"]}]', 'published', 'draft', 'global', NULL, 'a4cfb4860ef4d409a87115c780da4b99eb78852182f9e941dc72c865621e5bfc', 'flavorweave-catalog-package', 'catalog/thai-yum-nua-beef-salad/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_tomato-goat-cheese-galette_v1', 'rcp_tomato-goat-cheese-galette', 'tomato-goat-cheese-galette', 1, 'Rustic Tomato and Goat Cheese Galette with Lemony Arugula', 'A free-form all-butter pastry folded around a Dijon-brushed base of creamy goat cheese and ricotta, topped with salted, drained ripe tomato slices, garlic, and thyme, baked until bronzed and finished with a drizzle of honey. Served with a lemony arugula and Parmesan salad.', 4, 52, 50, 102, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', '400 F oven.', 'Crust deep golden and crisp underneath; tomatoes slumped and juices thickened.', '["bake"]', '[]', 'null', '[{"component_id":"pastry","name":"all-butter pastry","made_in_recipe":true,"store_bought":false,"ingredients":["flour","butter","water","salt"]},{"component_id":"filling","name":"goat cheese and tomato filling","made_in_recipe":true,"store_bought":false,"ingredients":["goat cheese","ricotta","dijon","garlic","tomatoes","thyme","honey","egg"]},{"component_id":"salad","name":"arugula salad","made_in_recipe":true,"store_bought":false,"ingredients":["arugula","lemon","parmesan-style cheese","olive oil"]}]', 'published', 'draft', 'global', NULL, '3cbbb93928a96d431f9cd519c3e01507a4f3df17fb4004b5a1810fd6b357f62d', 'flavorweave-catalog-package', 'catalog/tomato-goat-cheese-galette/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_tomato-soup-grilled-cheese_v1', 'rcp_tomato-soup-grilled-cheese', 'tomato-soup-grilled-cheese', 1, 'Roasted Tomato Soup with Grilled Cheese', 'Silky soup of oven-roasted Roma tomatoes, onion, and garlic blended with vegetable broth, basil, and a splash of cream, served with golden, buttery sharp-cheddar grilled cheese on sourdough for dunking.', 4, 12, 44, 56, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Oven 450 F for roasting (upper-middle rack); medium-high to bring the soup to a simmer, then gentle; medium-low skillet for the grilled cheese.', 'Tomatoes slumped and blistered with browned edges; soup silky, no skins visible. Grilled cheese deep golden and crisp with fully melted cheese. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"roasted-tomato-soup","name":"roasted tomato soup","made_in_recipe":true,"store_bought":false,"ingredients":["Roma tomatoes","yellow onion","garlic","olive oil","kosher salt","black pepper","tomato paste","vegetable broth","fresh basil","heavy cream","sugar (optional)"]},{"component_id":"cheddar-grilled-cheese","name":"sharp cheddar grilled cheese on sourdough","made_in_recipe":true,"store_bought":false,"ingredients":["sourdough bread","sharp cheddar","unsalted butter"]}]', 'published', 'draft', 'global', NULL, '3675b8fe704bf39945743265cebfa5bf11ec06d70c812433902fc8938577e24a', 'flavorweave-catalog-package', 'catalog/tomato-soup-grilled-cheese/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_turkey-sloppy-joes_v1', 'rcp_turkey-sloppy-joes', 'turkey-sloppy-joes', 1, 'Turkey Sloppy Joes with Quick Garlic Zucchini', 'A 25-minute family favorite: ground turkey simmered with onion, green pepper, and a tangy-sweet tomato, cider vinegar, and brown sugar sauce until thick and saucy, piled onto toasted buns. Served with garlicky skillet zucchini.', 4, 8, 17, 25, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Medium-high to brown the turkey; medium-low simmer; medium-high for the zucchini.', 'Turkey cooked through (165 F) and the sauce thick enough to mound on a spoon. Zucchini browned at the edges and crisp-tender.', '["saute","simmer"]', '[]', 'null', '[{"component_id":"filling","name":"turkey sloppy joe filling","made_in_recipe":true,"store_bought":false,"ingredients":["ground turkey","onion","green pepper","garlic","tomato sauce","tomato paste","brown sugar","cider vinegar","soy sauce","chili powder"]},{"component_id":"zucchini","name":"garlic zucchini","made_in_recipe":true,"store_bought":false,"ingredients":["zucchini","garlic","olive oil","salt"]},{"component_id":"buns","name":"toasted buns","made_in_recipe":false,"store_bought":true,"ingredients":["hamburger buns"]}]', 'published', 'draft', 'global', NULL, 'a5f2c59d83e88c637b9df55ebb87b3af16ba107a0d29719111a1a7fd40ea3abe', 'flavorweave-catalog-package', 'catalog/turkey-sloppy-joes/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_turkish-balik-ekmek-mackerel_v1', 'rcp_turkish-balik-ekmek-mackerel', 'turkish-balik-ekmek-mackerel', 1, 'Turkish Balik Ekmek: Seared Mackerel Sandwiches with Sumac Onions', 'Skin-on Atlantic mackerel fillets seared crisp and tucked into toasted crusty rolls with shredded romaine, tomato, and a red onion salad tossed with sumac, parsley, and Aleppo pepper, with lemon squeezed over.', 4, 12, 19, 31, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '12-inch heavy skillet over medium-high for the fish, then medium for the rolls.', 'Mackerel skin crisp and blistered, flesh just opaque and flaking, 145 F; roll cut sides toasted.', '["sear"]', '[]', 'null', '[{"component_id":"onions","name":"sumac onion salad","made_in_recipe":true,"store_bought":false,"ingredients":["red onion","sumac","parsley","Aleppo pepper","salt","olive oil"]},{"component_id":"fish","name":"seared mackerel","made_in_recipe":true,"store_bought":false,"ingredients":["mackerel fillets","salt","olive oil"]},{"component_id":"sandwich","name":"sandwich","made_in_recipe":true,"store_bought":false,"ingredients":["crusty rolls","romaine","tomatoes","lemon"]}]', 'published', 'draft', 'global', NULL, 'e5ba64fe3fd464510250bf25ff8ee909cc28cc5e4022552022a9e258a6d544d1', 'flavorweave-catalog-package', 'catalog/turkish-balik-ekmek-mackerel/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_turkish-iskender-kebab_v1', 'rcp_turkish-iskender-kebab', 'turkish-iskender-kebab', 1, 'Turkish İskender Kebab: Sliced Lamb over Pide with Tomato Sauce, Brown Butter, and Yogurt', 'A home version of the Bursa classic: thin slices of seared, marinated lamb laid over cubes of toasted pide, ladled with a warm buttery tomato sauce, finished at the table with sizzling brown butter, and served with cool garlic yogurt and blistered green peppers and tomatoes.', 4, 15, 66, 81, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Broiler preheated on high for 5 minutes for the pide and vegetables. High in a 12-inch cast-iron skillet for the lamb. Medium in a 1-quart saucepan for the tomato sauce and in an 8-inch skillet for the brown butter.', 'Lamb seared and browned at the edges, slightly pink inside (145 F). Pide crisp at the edges. Butter nutty brown and foaming.', '["sear","simmer","broil"]', '[]', 'null', '[{"component_id":"lamb","name":"seared marinated lamb","made_in_recipe":true,"store_bought":false,"ingredients":["lamb leg steaks","onion juice","olive oil","paprika","cumin","oregano"]},{"component_id":"pide","name":"toasted pide","made_in_recipe":false,"store_bought":true,"ingredients":["pide"]},{"component_id":"sauce","name":"tomato-butter sauce","made_in_recipe":true,"store_bought":false,"ingredients":["tomato paste","crushed tomatoes","butter","water","sugar"]},{"component_id":"yogurt","name":"garlic yogurt","made_in_recipe":true,"store_bought":false,"ingredients":["yogurt","garlic"]},{"component_id":"vegetables","name":"blistered peppers and tomatoes","made_in_recipe":true,"store_bought":false,"ingredients":["long green peppers","cherry tomatoes"]}]', 'published', 'draft', 'global', NULL, '154c46206b04e11ec1eab00b0635699075d82f3a63040980e92ff903cd4cde78', 'flavorweave-catalog-package', 'catalog/turkish-iskender-kebab/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_turkish-lahmacun_v1', 'rcp_turkish-lahmacun', 'turkish-lahmacun', 1, 'Turkish Lahmacun with Herb Salad', 'Thin flatbreads spread edge to edge with a spiced lamb, tomato, pepper, and parsley paste seasoned with Aleppo pepper and cumin, baked in a very hot oven until the rims crisp. Topped with a sumac red-onion, tomato, and parsley salad and a squeeze of lemon, then rolled up to eat. No cheese.', 4, 20, 32, 52, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Oven 475 F with an inverted rimmed sheet pan on the lowest rack, preheated 20 minutes during prep. Lahmacun start on parchment for 3 minutes, then finish directly on the hot pan; 7 to 8 minutes total per batch.', 'Flatbread rims and underside browned and crisp, still flexible enough to roll; topping sizzling, browned in spots, cooked through with no pink (160 F). kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"lamb-topping","name":"spiced lamb, tomato, and parsley paste","made_in_recipe":true,"store_bought":false,"ingredients":["ground lamb","yellow onion","red bell pepper","Roma tomato","garlic","flat-leaf parsley","tomato paste","Aleppo pepper","ground cumin","kosher salt","black pepper","olive oil"]},{"component_id":"thin-flatbreads","name":"rolled thin flatbreads","made_in_recipe":true,"store_bought":false,"ingredients":["store-bought plain pizza dough","all-purpose flour"],"contract":"Store-bought plain pizza dough (no milk, egg, or cheese), rolled and baked in the recipe."},{"component_id":"sumac-herb-salad","name":"sumac onion, tomato, and parsley salad","made_in_recipe":true,"store_bought":false,"ingredients":["red onion","sumac","kosher salt","Roma tomatoes","flat-leaf parsley","lemon juice","olive oil","Aleppo pepper"]}]', 'published', 'draft', 'global', NULL, 'f43cb892cdb9fb31d75c1e0efcc4e9611b3f83adef4e498c0586c85f15c8b423', 'flavorweave-catalog-package', 'catalog/turkish-lahmacun/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_turkish-mucver-zucchini-fritters_v1', 'rcp_turkish-mucver-zucchini-fritters', 'turkish-mucver-zucchini-fritters', 1, 'Turkish Mücver: Zucchini-Feta Fritters with Garlic Yogurt and Tomato-Cucumber Salad', 'Grated zucchini, squeezed dry and mixed with feta, scallions, dill, mint, eggs, flour, and red pepper flakes, shallow-fried into golden fritters. Served with cool garlic yogurt flecked with dill and a tomato, cucumber, and red onion salad dressed with lemon and olive oil.', 4, 25, 23, 48, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', '12-inch skillet over medium for shallow-frying, oil about 1/8 inch deep (2/3 cup per batch).', 'Fritters deep golden on both sides and set through the middle with no wet batter. Salad crisp and freshly dressed.', '["shallow-fry"]', '[]', 'null', '[{"component_id":"mucver","name":"zucchini-feta fritters","made_in_recipe":true,"store_bought":false,"ingredients":["zucchini","salt","feta","scallions","dill","mint","eggs","flour","red pepper flakes","neutral oil"]},{"component_id":"yogurt","name":"garlic-dill yogurt","made_in_recipe":true,"store_bought":false,"ingredients":["yogurt","garlic","dill","salt"]},{"component_id":"salad","name":"tomato-cucumber salad","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","cucumber","red onion","lemon","olive oil","salt"]}]', 'published', 'draft', 'global', NULL, 'b45b4128f36cc4c657bef60307c4d764658628bd9f7505b8dcf1981b4cd26ee1', 'flavorweave-catalog-package', 'catalog/turkish-mucver-zucchini-fritters/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_tuscan-panzanella-white-beans_v1', 'rcp_tuscan-panzanella-white-beans', 'tuscan-panzanella-white-beans', 1, 'Tuscan Panzanella with White Beans and Basil', 'A summer bread salad as a full dinner: oven-toasted chunks of crusty bread soaking up the juices of salted ripe tomatoes, cucumber, and red onion in a garlicky red wine vinaigrette, with creamy white beans, capers, and lots of basil.', 4, 10, 18, 28, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Oven preheated to 400 F for toasting the bread.', 'Bread golden and crisp outside, still a little chewy inside, then softened at the edges by the dressing after a 5-minute rest.', '["bake"]', '[]', 'null', '[{"component_id":"bread","name":"toasted bread","made_in_recipe":true,"store_bought":false,"ingredients":["crusty bread","olive oil","salt"]},{"component_id":"salad","name":"tomato, bean, and basil salad","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","cucumber","red onion","white beans","capers","basil","garlic","red wine vinegar","olive oil","salt"]}]', 'published', 'draft', 'global', NULL, '6d74c7e73d9cd2193e7dd063dfc05cfbc9d0d13d1624aa0b49edf42677a9d0ea', 'flavorweave-catalog-package', 'catalog/tuscan-panzanella-white-beans/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_ukrainian-beet-borscht_v1', 'rcp_ukrainian-beet-borscht', 'ukrainian-beet-borscht', 1, 'Ukrainian Beet Borscht with White Beans and Dill', 'A ruby-red vegetable borscht of beets, cabbage, carrot, potato, and white beans in a tomato-and-vinegar broth sweetened with a little sugar and finished with garlic and fresh dill. Served with rye bread.', 4, 20, 47, 67, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium sauté for the base, then a medium-low covered simmer.', 'Beets and potatoes tender to a knife; cabbage soft; broth deep ruby and balanced sweet-sour.', '["saute","simmer"]', '[]', 'null', '[{"component_id":"borscht","name":"vegetable beet borscht","made_in_recipe":true,"store_bought":false,"ingredients":["beets","cabbage","carrot","onion","potato","white beans","tomato paste","vinegar","sugar","garlic","dill","bay","water","oil"]},{"component_id":"bread","name":"rye bread","made_in_recipe":false,"store_bought":true,"ingredients":["rye bread"]}]', 'published', 'draft', 'global', NULL, '77869aeac1baf268336bfd0e69c1826b4ca57dd094f5e5f72f96ea40c29195aa', 'flavorweave-catalog-package', 'catalog/ukrainian-beet-borscht/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_uruguayan-chivito-sandwiches_v1', 'rcp_uruguayan-chivito-sandwiches', 'uruguayan-chivito-sandwiches', 1, 'Uruguayan Chivito Steak Sandwiches with Ham, Bacon, Mozzarella, and Egg', 'Thin seared beef steaks layered on toasted rolls with ham, crisp bacon, melted mozzarella, a pan-fried egg, mayonnaise, lettuce, tomato, and sliced green olives.', 4, 10, 34, 44, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '12-inch skillet over medium for the bacon, medium-high for the steaks, medium for the eggs.', 'Bacon crisp; steaks browned and 145 F; cheese melted; egg whites set with yolks still soft or cooked through, as preferred.', '["sear","pan-fry","toast"]', '[]', 'null', '[{"component_id":"fillings","name":"steak, ham, bacon, and egg","made_in_recipe":true,"store_bought":false,"ingredients":["beef sirloin","salt","black pepper","bacon","ham","mozzarella","eggs"]},{"component_id":"sandwich","name":"sandwich","made_in_recipe":true,"store_bought":false,"ingredients":["rolls","mayonnaise","lettuce","tomato","green olives"]}]', 'published', 'draft', 'global', NULL, '2563124e7f4d7c97241c2f4cc0af84fe90c344f3d7dfa6cc4c3c723a5134a4e5', 'flavorweave-catalog-package', 'catalog/uruguayan-chivito-sandwiches/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_uzbek-lamb-plov_v1', 'rcp_uzbek-lamb-plov', 'uzbek-lamb-plov', 1, 'Uzbek Lamb Plov with Carrots, Chickpeas, and a Whole Garlic Head', 'Cubes of lamb shoulder browned with onions and a heap of julienned carrots, simmered with cumin seeds, coriander, and dried chiles into a rich base, then covered with basmati rice, chickpeas, raisins, and a whole head of garlic and steamed until every grain is separate.', 4, 25, 121, 146, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '5.5-quart Dutch oven over medium-high to brown, then medium-low and covered.', 'Lamb tender when pierced; rice tender with separate grains; no liquid pooling at the bottom.', '["sear","saute","simmer","steam"]', '[]', 'null', '[{"component_id":"plov","name":"lamb plov","made_in_recipe":true,"store_bought":false,"ingredients":["lamb shoulder","salt","neutral oil","yellow onions","carrots","cumin seeds","ground coriander","dried red chiles","water","basmati rice","chickpeas","raisins","garlic"]}]', 'published', 'draft', 'global', NULL, '75e18fe1c7d667709be5d5378dd3b8524e61a140dbe27a4e073de768108261a4', 'flavorweave-catalog-package', 'catalog/uzbek-lamb-plov/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_vegetable-biryani-cashews_v1', 'rcp_vegetable-biryani-cashews', 'vegetable-biryani-cashews', 1, 'Vegetable Biryani with Saffron and Cashews', 'Long-grain basmati parboiled and steamed (dum) over a garam-masala vegetable base of cauliflower, carrots, and peas, streaked with saffron and layered with crisp-fried onions, mint, and toasted cashews. Oil instead of ghee; no yogurt, cream, or butter; cashews are the only nut.', 4, 20, 50, 70, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium oil for cashews, medium-high for onions, medium covered for vegetables, high boil for rice, then medium 2 minutes and lowest heat for the dum. No oven.', 'Onions deep golden and crisp. Rice grains long, separate, fully tender, streaked saffron-orange. Cauliflower tender but holding shape; no wet puddle at the bottom. Cashews golden. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"fried-onions-cashews","name":"crisp-fried onions (birista) and toasted cashews","made_in_recipe":true,"store_bought":false,"ingredients":["yellow onions","raw cashews","neutral oil","kosher salt"]},{"component_id":"vegetable-masala","name":"garam-masala vegetable base","made_in_recipe":true,"store_bought":false,"ingredients":["garlic","ginger","serrano","garam masala","turmeric","cauliflower","carrots","peas","lemon juice","mint","fried onions"]},{"component_id":"saffron-rice","name":"parboiled basmati with saffron water","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","saffron","salted water","neutral oil","lemon juice","garam masala"]}]', 'published', 'draft', 'global', NULL, '3253b0e145c0043100a3774dc08d17254741fcde2c7b8f042682b5cc62e3c12a', 'flavorweave-catalog-package', 'catalog/vegetable-biryani-cashews/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_venezuelan-black-bean-plantain-arepas_v1', 'rcp_venezuelan-black-bean-plantain-arepas', 'venezuelan-black-bean-plantain-arepas', 1, 'Venezuelan Arepas with Black Beans, Sweet Plantains, and Avocado', 'Golden, crusty corn arepas made from masarepa, seared on a griddle and finished in the oven until they puff, then split and stuffed with cumin-spiced black beans, oven-roasted sweet plantains, and avocado (a plant-based take on domino-style fillings).', 4, 5, 45, 50, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Oven at 400 F for the plantains and to finish the arepas. Medium cast-iron griddle for the arepa crust. Medium skillet for the beans.', 'Arepas crusty and spotted gold, puffed, and hollow-sounding when tapped. Plantains deeply caramelized at the edges and soft. Beans thick and spoonable.', '["sear","bake","roast","simmer"]', '[]', 'null', '[{"component_id":"arepas","name":"masarepa arepas","made_in_recipe":true,"store_bought":false,"ingredients":["masarepa","water","salt","oil"]},{"component_id":"beans","name":"cumin black beans","made_in_recipe":true,"store_bought":false,"ingredients":["black beans","onion","red bell pepper","garlic","cumin","smoked paprika","water","oil"]},{"component_id":"plantains","name":"roasted sweet plantains","made_in_recipe":true,"store_bought":false,"ingredients":["ripe plantains","oil","salt"]},{"component_id":"avocado","name":"avocado and cilantro","made_in_recipe":true,"store_bought":false,"ingredients":["avocado","cilantro","lime"]}]', 'published', 'draft', 'global', NULL, '4ffd42a302f9ea7f5e5e606c0a483d824298de576c717bf21720ecef410e7f37', 'flavorweave-catalog-package', 'catalog/venezuelan-black-bean-plantain-arepas/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_vietnamese-bun-cha_v1', 'rcp_vietnamese-bun-cha', 'vietnamese-bun-cha', 1, 'Vietnamese Bún Chả: Grilled Pork Patties with Noodles and Herbs', 'Hanoi''s lunchtime classic: caramelized pork patties seasoned with shallot, garlic, fish sauce, and sugar, grilled over high heat and served swimming in warm, sweet-tart nước chấm, with cool rice vermicelli, a heap of lettuce and fresh herbs, and quick-pickled carrot.', 4, 20, 19, 39, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Gas grill (or grill pan) preheated to medium-high, about 450 F, clean oiled grates. Rolling boil for the noodles.', 'Patties charred in spots and 160 F in the center. Noodles tender and springy, rinsed cool.', '["grill","boil"]', '[]', 'null', '[{"component_id":"patties","name":"grilled pork patties","made_in_recipe":true,"store_bought":false,"ingredients":["ground pork","shallots","garlic","fish sauce","sugar","pepper","oil"]},{"component_id":"nuoc-cham","name":"nước chấm","made_in_recipe":true,"store_bought":false,"ingredients":["fish sauce","sugar","lime","water","garlic","Thai chiles"]},{"component_id":"noodles","name":"rice vermicelli","made_in_recipe":true,"store_bought":false,"ingredients":["rice vermicelli","water"]},{"component_id":"herbs","name":"herb plate and pickled carrot","made_in_recipe":true,"store_bought":false,"ingredients":["lettuce","mint","cilantro","Thai basil","carrot","rice vinegar","sugar"]}]', 'published', 'draft', 'global', NULL, '8b1a45b810ad68f4a7421ff0ef48cc6f5a868e941a39c5a86ed7c9b4d7cb3ac1', 'flavorweave-catalog-package', 'catalog/vietnamese-bun-cha/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_vietnamese-ca-kho-catfish_v1', 'rcp_vietnamese-ca-kho-catfish', 'vietnamese-ca-kho-catfish', 1, 'Vietnamese Ca Kho: Caramel-Braised Catfish with Black Pepper and Jasmine Rice', 'Catfish pieces braised in a dark sugar caramel with fish sauce, coconut water, shallots, garlic, black pepper, and Thai chiles until glazed and sticky, scattered with scallions and served with jasmine rice and cucumber slices.', 4, 10, 31, 41, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', '12-inch heavy skillet over medium for the caramel, then a steady simmer; 2-quart saucepan for the rice.', 'Caramel deep amber; sauce reduced to a thick, sticky glaze; catfish opaque, flaking, and 145 F.', '["braise","steam"]', '[]', 'null', '[{"component_id":"ca-kho","name":"caramel catfish","made_in_recipe":true,"store_bought":false,"ingredients":["sugar","water","shallots","garlic","fish sauce","coconut water","catfish","black pepper","Thai chiles","scallions"]},{"component_id":"rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]},{"component_id":"cucumber","name":"cucumber","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber"]}]', 'published', 'draft', 'global', NULL, '19f6f3ca0f699364d8d11b80260713526912614b3c8b09f1971ac08e57da3982', 'flavorweave-catalog-package', 'catalog/vietnamese-ca-kho-catfish/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_vietnamese-chicken-pho_v1', 'rcp_vietnamese-chicken-pho', 'vietnamese-chicken-pho', 1, 'Vietnamese Chicken Pho', 'Chicken simmered with charred onion, ginger, and whole spices into a clear broth, served over flat rice noodles with herbs and lime.', 4, 20, 55, 75, 'involved', 'adventurous', '6ee7bb37273cbc12eff6d5be73cdb6c79a88a65cdfe5ea686de96c0b7a43a78d', 'Dry medium-high skillet for charring. Stockpot: high to boil, then gentle simmer. No oven.', 'Chicken thighs 175 F near the bone before shredding. Broth clear, savory, lightly sweet. Rice noodles pliable, not mushy. Broth steaming hot in the bowl. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"pho-chicken-broth","name":"pho chicken broth","made_in_recipe":true,"store_bought":false,"ingredients":["bone-in chicken thighs","yellow onion","fresh ginger","star anise","cinnamon stick","whole cloves","coriander seeds","water","fish sauce","kosher salt","sugar"]}]', 'published', 'draft', 'global', NULL, 'e95da3c7cad2fce8166f2326670103288c555a8b667ba127add1045c3ea222ce', 'flavorweave-catalog-package', 'catalog/vietnamese-chicken-pho/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_vietnamese-lemongrass-tofu-banh-mi_v1', 'rcp_vietnamese-lemongrass-tofu-banh-mi', 'vietnamese-lemongrass-tofu-banh-mi', 1, 'Vietnamese Lemongrass Tofu Banh Mi with Pickled Carrot and Daikon', 'Slabs of extra-firm tofu marinated in lemongrass, garlic, soy sauce, and sugar and seared golden, tucked into toasted baguettes with sriracha mayonnaise, quick-pickled carrot and daikon, cucumber, jalapeno, and cilantro.', 4, 21, 20, 41, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', '12-inch nonstick skillet over medium-high for the tofu, then medium to toast the bread.', 'Tofu deep golden on both sides with caramelized edges; baguette cut sides crisp and lightly browned; pickles crisp and tangy.', '["sear","pickle"]', '[]', 'null', '[{"component_id":"tofu","name":"lemongrass tofu","made_in_recipe":true,"store_bought":false,"ingredients":["extra-firm tofu","lemongrass","garlic","soy sauce","sugar","neutral oil"]},{"component_id":"pickles","name":"do chua pickles","made_in_recipe":true,"store_bought":false,"ingredients":["carrot","daikon","rice vinegar","water","sugar","salt"]},{"component_id":"mayo","name":"sriracha mayonnaise","made_in_recipe":true,"store_bought":false,"ingredients":["mayonnaise","sriracha"]},{"component_id":"baguettes","name":"baguettes","made_in_recipe":false,"store_bought":true,"ingredients":["baguettes"]}]', 'published', 'draft', 'global', NULL, '029e4673520716199a88f8306568284b83c06e9e7e45b616a15ecb5eff65e2cb', 'flavorweave-catalog-package', 'catalog/vietnamese-lemongrass-tofu-banh-mi/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_vietnamese-turmeric-dill-fish_v1', 'rcp_vietnamese-turmeric-dill-fish', 'vietnamese-turmeric-dill-fish', 1, 'Vietnamese Turmeric Fish with Dill and Noodles', 'Chả cá–style catfish: bite-size pieces marinated in turmeric, ginger, shallot, and fish sauce, seared golden, then tossed with a big handful of dill and scallions wilted in the hot pan. Served over cool rice vermicelli with mint, chopped roasted cashews, red chile, and a bright lime nước chấm. No shrimp paste; cashews instead of peanuts.', 4, 20, 17, 37, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Stovetop only. Rolling boil for noodles; medium-high, shimmering oil for the sear and the quick dill wilt. No oven.', 'Fish deep golden on the seared side, opaque and flaking through (145 F); dill just wilted and still vivid green; noodles tender, rinsed cool, and not clumped. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"turmeric-catfish","name":"turmeric-ginger marinated seared catfish","made_in_recipe":true,"store_bought":false,"ingredients":["catfish","ground turmeric","fresh ginger","shallot","garlic","fish sauce","sugar","kosher salt","black pepper","neutral oil"]},{"component_id":"wilted-dill-scallions","name":"pan-wilted dill and scallions","made_in_recipe":true,"store_bought":false,"ingredients":["fresh dill","scallions","neutral oil"]},{"component_id":"nuoc-cham","name":"lime nước chấm","made_in_recipe":true,"store_bought":false,"ingredients":["fish sauce","lime juice","sugar","warm water","garlic","red chile"]},{"component_id":"noodles-and-toppings","name":"rice vermicelli with mint, cashews, and chile","made_in_recipe":true,"store_bought":false,"ingredients":["rice vermicelli","fresh mint","roasted cashews","red chile","lime wedges"]}]', 'published', 'draft', 'global', NULL, '45176e2f2516c5246dc9d290d1fe31de379d189d35f88006287313018f74bd23', 'flavorweave-catalog-package', 'catalog/vietnamese-turmeric-dill-fish/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_white-bean-kale-soup_v1', 'rcp_white-bean-kale-soup', 'white-bean-kale-soup', 1, 'White Bean Kale Soup', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["plant","dairy-free"]', 'null', '[]', 'retired', 'published', 'global', NULL, 'a9025ee246a4283d9cb2a96e28336bec6c1aba93307c8fd5356588c4aac1a739', 'flavorweave-legacy-catalog-package', 'catalog/white-bean-kale-soup/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_white-bean-kale-soup_v2', 'rcp_white-bean-kale-soup', 'white-bean-kale-soup', 2, 'White Bean Kale Soup', 'Stovetop soup of cannellini beans, fennel, diced tomato, and kale in vegetable broth.', 4, 15, 30, 45, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Medium heat to soften the fennel, then a simmer. No oven.', 'Fennel is softened at 5 minutes. The soup simmers 20 minutes. Kale is tender at about 5 minutes more. Canned beans are already cooked.', '["stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'c9539f30ffe1a7ecd031159e2d87d845a77e7e18877c6fd1c65445d3776d3f7d', 'flavorweave-legacy-audit-draft', 'catalog/white-bean-kale-soup/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_xian-cumin-lamb-stir-fry_v1', 'rcp_xian-cumin-lamb-stir-fry', 'xian-cumin-lamb-stir-fry', 1, 'Xi''an Cumin Lamb Stir-Fry with Jasmine Rice', 'Thin slices of lamb seared hard in a wok with whole cumin seeds, dried chile flakes, Sichuan peppercorn, garlic, ginger, and onion until crisp-edged and fragrant, finished with scallions and cilantro. A bold, dry-spiced northwestern Chinese stir-fry over rice.', 4, 12, 15, 27, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Very high wok heat to sear the lamb in two batches; high for the aromatics.', 'Lamb browned and crisp at the edges, just cooked through; onion crisp-tender; spices toasted but not burnt.', '["stir-fry"]', '[]', 'null', '[{"component_id":"lamb","name":"cumin lamb stir-fry","made_in_recipe":true,"store_bought":false,"ingredients":["lamb","soy sauce","cornstarch","cumin seeds","chile flakes","Sichuan peppercorns","onion","garlic","ginger","scallions","cilantro","oil"]},{"component_id":"rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]}]', 'published', 'draft', 'global', NULL, '4b0562236de1dcddf582301166dcc955c0f850507f539fa7b7ecdf48d2fd9e49', 'flavorweave-catalog-package', 'catalog/xian-cumin-lamb-stir-fry/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_yucatecan-tikin-xic-fish_v1', 'rcp_yucatecan-tikin-xic-fish', 'yucatecan-tikin-xic-fish', 1, 'Yucatecan Tikin Xic: Achiote-Citrus Baked Fish with Pickled Red Onions', 'Cod fillets rubbed with achiote paste blended with orange juice, lime, garlic, oregano, and cumin, layered with tomato and green bell pepper slices, baked in a foil packet, and served with habanero-pickled red onions, cilantro, and white rice.', 4, 27, 20, 47, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Oven at 425 F for the fish on a foil-lined sheet pan; 2-quart saucepan for the rice.', 'Fish opaque, flaking, and 145 F at the thickest point; tomatoes and pepper softened; onions bright pink and tangy.', '["bake","steam","pickle"]', '[]', 'null', '[{"component_id":"onions","name":"pickled red onions","made_in_recipe":true,"store_bought":false,"ingredients":["red onion","habanero","lime juice","orange juice","salt"]},{"component_id":"fish","name":"tikin xic","made_in_recipe":true,"store_bought":false,"ingredients":["cod fillets","achiote paste","orange juice","lime juice","garlic","dried oregano","ground cumin","salt","neutral oil","tomato","green bell pepper"]},{"component_id":"rice","name":"white rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain white rice","water","salt"]},{"component_id":"garnish","name":"cilantro","made_in_recipe":true,"store_bought":false,"ingredients":["cilantro"]}]', 'published', 'draft', 'global', NULL, '65075e0979a0e46aec835fb1ac77e3c4fa5a9830ed7497eeedbc18968ca9e3a5', 'flavorweave-catalog-package', 'catalog/yucatecan-tikin-xic-fish/v1.json', '2026-10-04T00:00:00.000Z');

